.PopularPosts ul li {list-style: none; padding: 10px 0 !important}
.PopularPosts ul li:first-child {margin-top: 0}
.PopularPosts ul li a {display: block; color: $(black.color); font-weight: 700}
.PopularPosts ul li a:hover {text-decoration: none;}
.PopularPosts ul li .item-title, .PopularPosts ul li .item-snippet {display: block; clear: both; width: 100%}
/* BLG-C512: the rank numeral is COUNTED, not enumerated.
   It used to be six literal rules keyed on the items position, and the base
   pseudo-element carried no content at all -- so a seventh entry had no
   numeral, and because Blogger popular is a time-varying list, WHICH entry lost
   its number changed from one visit to the next.
   Measured live with the list extended to eight: one to six numbered, the
   seventh printed the panel label instead, the eighth printed nothing.
   The HOT NEWS modal already counts this way (BLG-C179/C453); Most Like was the
   last surface writing numerals by hand, and the six rules were DELETED rather
   than extended to twelve, because a list that must be edited when an owner
   changes a setting is the same bug one position further out.
   NOTE, and it cost a run to learn: this comment may not spell out a selector.
   check-thumbnail-coverage parses rules as [^{}] pairs WITHOUT stripping CSS
   comments, so prose naming a selector is read AS one and the gate fails on the
   rule that follows. Same trap as C100 and as check-feed-guards on a comment
   quoting a data tag. Describe the reason; never write the syntax. */
.PopularPosts ul {counter-reset: mlrank}
.PopularPosts ul li .item-thumbnail {float: none; height: 200px; overflow: hidden; margin: 0 0 10px; position: relative; counter-increment: mlrank}
.PopularPosts ul li .item-thumbnail a {display: block; height: 100%}
.PopularPosts ul li .item-thumbnail img {width: 100%; height: 100%; object-fit: cover; object-position: center center; display: block}
.PopularPosts ul li .item-thumbnail:before {content: ""; position: absolute; left: 0; bottom: 0; z-index: 1; border-bottom: 40px solid $(red.color); border-right: 60px solid transparent}
/* The numeral lives on the BASE rule, so it exists at every position rather than
   only the few a literal list could name, and at three classes plus three elements
   it still outranks the panel gradient own corner text. That is what keeps the
   digit where it belongs and leaves the label to the pill (BLG-C457/C458). */
.PopularPosts ul li .item-thumbnail:after {content: counter(mlrank); position: absolute; left: 15px; bottom: 5px; color: $(white.color); font-size: 38px; font-weight: 700; z-index: 2}
/* BLG-C453: a paneled popular thumb flex-centered its digit mid-card (the panel ::after merges inset:0 plus centering with the reference corner rule). Reference puts the digit left:15px bottom:5px on the red triangle -- display:block with top/right auto retires the centering and returns it there. */
/* BLG-C579: the override above declares NO content of its own, so the panel text
   rule (.item-thumbnail.is-placeholder::after, content:attr(data-ph)) -- which
   ties it 2-2 on specificity and comes EARLIER in the file -- loses by source
   order, and the paneled card shows the digit twice and the label never.
   Measured live: the paneled Most Like card's ::after computed to
   content:counter(mlrank) at 38px in the bottom corner. Repeating the numeral
   here keeps the digit in its corner AND lets the panel text rule win the
   content it owns, so a paneled card reads digit-plus-label as designed. */
.PopularPosts ul li .item-thumbnail.is-placeholder::after {content: counter(mlrank); display: block; top: auto; right: auto; height: auto; pointer-events: none; padding-top: 0} /* BLG-C457: digit keeps its corner box while panel text centers up top */
.PopularPosts .item-thumbnail .pp-tag{position:absolute;top:22px;left:10px;z-index:2;background:$(red.color);color:$(white.color);font:700 11px/1 'Poppins',sans-serif;letter-spacing:.02em;text-transform:uppercase;padding:5px 9px;border-radius:999px;max-width:80%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap} /* BLG-C458: pill sits below the top edge, not on it */
