.blog-pager .showpage:hover, .blog-pager .displaypageNum:hover, .blog-pager .pagecurrent {background: #ebf0fd;}
.blog-pager .displaypageNum {display: inline-block; margin: 0 5px; width: 32px; border-radius: 100%;}
.blog-pager .firstpage, .blog-pager .prevpage, .blog-pager .nextpage, .blog-pager .lastpage {width: auto; padding: 0 10px; border-radius: 0;}
.blog-pager .pager-list-post a {color: $(black.color)}
.blog-pager .newer-link {float: left}
.blog-pager .newer-link .uk-icon {margin-right: 5px}
.blog-pager .older-link {float: right}
.blog-pager .older-link .uk-icon {margin-left: 5px}
.uk-breadcrumb li {padding: 0; display: inline-flex; align-items: center}
.uk-breadcrumb li a {display: inline-flex; align-items: center; font-size: 14px; line-height: 1.5; text-transform: capitalize; color: #2C4E60} /* BLG-C307: UIkit ships `.uk-breadcrumb>*>*{color:#999}` and nothing in the skin set the crumb link colour, so every crumb link measured 2.84:1 on the white crumb bar (WCAG 1.4.3) while the skin-only contrast gate reported PASS. #2C4E60 is 8.88:1 and already pinned. */
.uk-breadcrumb>:nth-child(n+2):not(.uk-first-column)::before {content: ">"; margin: 0 10px; color: #999; font-size: 12px; line-height: 1}
.uk-breadcrumb {margin-bottom: 50px}
.uk-breadcrumb a.current {max-width: 260px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; display: inline-block}
/* BLG-C593: on a phone the crumb trail wrapped the current title onto a second
   line instead of ellipsising inside one row. UIkit's ul is a normal block, so
   the 260px title still overflowed the 280px trail at 320px (title li 286.4px),
   and a narrower max-width alone would just move the wrap. Below 480px the list
   is one non-wrapping flex row: the parent crumbs keep their width, the current
   item takes the remainder, and the full title stays in the DOM (BLG-C500).
   Measured at 320px: trail 280x21, title link 144.3px, scrollWidth 280; at
   390px title link 214.3px. Desktop is outside this query and is unchanged. */
@media (max-width: 480px) {
  .uk-breadcrumb {display: flex; flex-wrap: nowrap; align-items: center; min-width: 0}
  .uk-breadcrumb > li {flex: 0 0 auto; min-width: 0}
  .uk-breadcrumb > li:last-child {flex: 1 1 auto; min-width: 0; overflow: hidden}
  .uk-breadcrumb a.current {max-width: 100%}
}
.sr-only {position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0}
/* BLG-C222: the skip link's :focus state. It inherits .sr-only, so the only
   thing this has to undo is the clipping and the 1px box, and the focus ring
   must come back with it, or the link is reachable and still invisible.
   The ring is --cp-text, NOT --cp-soft-border: measured, soft-border on card is
   2.46:1 in light and 1.47:1 in dark, and a focus indicator is non-text UI
   content, which needs 3:1. --cp-text on --cp-card measures 21.00:1 light and
   10.51:1 dark, and it is already the chip's own text colour, so the ring costs
   no new token and no new colour. Both modes, from the tokens each defines. */
.cp-skip:focus {position: fixed; top: 8px; left: 8px; z-index: 1000; width: auto; height: auto; margin: 0; padding: 10px 16px; clip: auto; overflow: visible; background: var(--cp-card); color: var(--cp-text); border: 2px solid var(--cp-text); border-radius: 4px; font-weight: 700; text-decoration: none; white-space: nowrap}
/* Moving focus to the main section should not also slide the fixed header over
   the article, so the target carries the scroll margin and the browser does the
   rest. */
#main {scroll-margin-top: 80px}
.video-placeholder {aspect-ratio: 16 / 9; height: auto; max-width: 100%}
.grp-post {margin-top: 10px}
/* BLG-C561: author, date and comment count share one row until the column
   cannot hold them; then the line wraps as a unit instead of stacking each
   field on its own row. The reset margin is intentional: the generic
   `.post-entry .post-panel span` rule adds a right margin, and with flex that
   would double the gap. */
.grp-post {display: flex; flex-wrap: wrap; align-items: center; column-gap: 10px; row-gap: 2px}
.post.hentry .grp-post > span {margin: 0}
.post.hentry .grp-post .post-date {display: inline}
.grp-post span a {color: #2C4E60; font-size: 14px} /* BLG-C306: #999 on the light card measured 2.84:1 live. #2C4E60 is 8.88:1 and already pinned; the same palette-consequence fix C215 applied to the post date. */
.grp-post span a.g-profile span {margin-right: 0}
.grp-post span .uk-icon {margin-right: 2px; position: relative; top: -1px; color: #999}
.post-social {width: 35px}
.post-social ul li {padding: 0}
.post-social ul li a {display: inline-block; width: 35px; height: 35px; border-radius: 100%; text-align: center; line-height: 33px; color: $(white.color)}
.post-social ul li a.icon-fb {background: #3a5794}
.post-social ul li a.icon-x {background: #000000}
.post-social ul li a.icon-in {background: #0076b3}
.post-social ul li a.icon-th {background: #000000} /* BLG-C487: Threads shares through an intent URL, not a Blogger share target, so it cannot use data:post.sharePostUrl the way facebook/x do -- hence a hand-built href. Same near-black as the X button beside it: both marks are black on white, and reusing the pinned value keeps the frozen palette untouched (tests/palette-freeze.txt). */
.post-social ul li a.icon-wa {background: #05c645}
.entry-content {font-family: 'PT Serif', serif; font-weight: 400; font-size: 18px}
.entry-content .separator a {margin: 0 !important}
.entry-content .separator:first-child img {width: 100%}
.entry-content h1, .entry-content h2, .entry-content h3, .entry-content h4, .entry-content h5, .entry-content h6 {margin: 10px 0 !important; font-family: 'PT Serif', serif; font-weight: 700; text-transform: uppercase}
.entry-content h1 {font-size: 32px}
/* BLG-C273: this read `font-size: 28` with no unit. A unitless non-zero length is
   invalid CSS, so the parser discarded the declaration and h2 fell back to the
   `h1..h6 {font-size: inherit}` rule -- every h2 in every post body rendered at
   the 18px body size. Inherited verbatim from the Gellian base theme. */
.entry-content h2 {font-size: 28px; border-top: none; padding-top: 0}
.entry-content h2:before {content: none}
.entry-content h3 {font-size: 24px}
.entry-content h4 {font-size: 20px}
.entry-content h5 {font-size: 16px}
.entry-content h6 {font-size: 12px}
td.tr-caption {padding: 5px 0; background: #f8f7ff}
.tr_bq {background: #f8f7ff; padding: 10px 20px; border-left: solid 5px $(green.color); color: $(black.color); font-size: 18px}
blockquote p:last-of-type {font-weight: 700}
.uk-list-striped>li {padding: 10px 20px !important; margin: 0 !important}
.uk-list-striped>li:nth-of-type(odd) {background: #f8f7ff; border: none}
.post-tags-container {margin-top: 20px; padding-top: 10px; border-top: solid 1px #ebf0fd}
.post-tags-container .post-tags-tt {display: inline-block}
.post-tags-container .post-tags-tt .uk-icon {position: relative; top: -1px}
.post-tags-container .post-label {padding: 0 10px}
/* BLG-C184: the tag strip is ONE line by the operator's instruction, so it can
   never push the author box, the comments and everything under them down the
   page. nowrap stops the wrap and overflow hides what will not fit; the mask
   fades the last tag out instead of cutting it in half, which is what a plain
   clip looks like. The links carry their own right margin now that the comma
   that used to separate them is gone, so the gap survives the removal. The
   mask is colour-independent, so dark mode needs no rule of its own. The black
   is written in six digits deliberately: the palette freeze counts every hex
   literal, and the shorthand form is not in the pinned set. */
.post-tags-container .post-labels{display: block;white-space: nowrap;overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, #000000 88%, transparent);
  mask-image: linear-gradient(90deg, #000000 88%, transparent)}
.post-tags-container .post-labels a{margin: 0 6px 0 0}
.post-tags-container .post-labels a:last-child{margin-right: 0}
.post-tags-container .post-label a {color: #2C4E60; font-size: 14px} /* BLG-C306: #999 on #ffffff measured 2.84:1 at 14px live -- the three tag links both Lighthouse and axe flagged as serious on the post page. #2C4E60 is 8.88:1 and already pinned. */
.post-tags-container .post-label .uk-icon {position: relative; top: -1px}
.post-footer-line-3 {margin: 20px 0}
.author-profile {background: #f8f7ff; padding: 20px; margin: 0}
.author-profile .author-img img {height: 150px; margin-right: 20px}
.author-bio ul li {display: inline-block}
.author-bio .g-profile {display: block}
.author-bio .g-profile:hover {text-decoration: none}
.author-bio .g-profile span {color: #288047; font-weight: 700; text-transform: uppercase; font-size: 18px} /* BLG-C308: $(green.color) #34ad60 on the #f8f7ff author panel measured 2.71:1 at 18px/700, under the 4.5 floor (18px bold sits below WCAG's 18.66px large-text line). #288047 -- the literal BLG-C216 already chose for green text on this ground -- measures 4.62:1; in dark the name joins the author panel's muted rule above. Found by the extended contrast harness, not by the live run, because the live post had no About-me text so the panel never rendered. */
.author-bio .text-profile {display: block; margin: 5px 0 15px; line-height: 1.4; font-size: 15px; color: #2C4E60} /* BLG-C306: #999 on the light author panel measured 2.84:1. #2C4E60 is 8.88:1 and already pinned. */
.author-bio ul li {padding: 0 5px 0 0}
.author-bio ul li a {display: inline-block; color: #9693ab; width: 32px; height: 32px; text-align: center; line-height: 30px; background: #f0eef7; border-radius: 100%}
.author-bio ul li a:hover {color: $(white.color); background: $(green.color)}
/* BLG-C158: the author bio clones the social section after the icon script has
   run, so the clone carries the label spans the drawer's list view needs. The
   bio keeps its 32px circles and shows icons only -- labels stay drawer-only. */
.author-bio .sn-label {display: none}
.related-main h2.title {font-size: clamp(20px, 6.25vw, 24px); margin-bottom: 10px}
.related-main .related-posts .pager-nav {top: 10px; right: 0; z-index: 9}
.related-main .related-posts .pager-nav a {padding: 3px 2px; color: $(white.color);} /* BLG-C306: same 24x24 target-size floor as the breaking-news pager. */
.related-main .related-posts .pager-nav a .uk-icon {position: relative; top: -1px}
.comments h2.title {background: #f8f7ff; text-align: center; padding: 5px 0; font-size: 20px}
.comments h2.title:before {content: none}
.comments .avatar-image-container {width: 60px; max-height: 60px}
.comments .avatar-image-container img {max-width: 60px; border-radius: 100%}
.comments .comment-block {margin-left: 80px}
.comments .comment-block .user a {color: $(black.color)}
.comments .comments-content .datetime {display: block; margin-left: 0}
.comments .comments-content .datetime a {color: #2C4E60; font-size: 14px} /* BLG-C306: #999 on white measured 2.84:1. #2C4E60 is 8.88:1 and already pinned. */
.comments .comments-content .comment-content {margin: 15px 0}
.comments .comment-actions a {font-size: 12px; padding: 0 8px 1px !important; margin-right: 5px; color: $(white.color); background: $(red.color); border-radius: 24px}
.comments .comment-actions .comment-reply {background: $(green.color)}
.comments .comments-content .comment-replies {margin-left: 80px}
.comments .comments-content .inline-thread {padding: 0; border-top: solid 1px #ebf0fd}
.comments .comments-content .comment-replies .thread-count a {font-size: 12px; color: $(black.color)}
.comments .thread-toggle {background: #f8f7ff; padding: 0 10px}
.comments .thread-toggle .thread-arrow {position: relative; top: 3px; width: 5px}
.comments .comments-content .comment-thread ol {margin: 10px 0 0}
.comments .continue a {background: #f8f7ff; text-align: center; color: $(black.color); font-size: 14px; padding: 5px}
.status-msg-wrap {text-align: center; background: #f8f8fe; padding: 5px 0; margin: 0 auto 20px; font-size: 14px; width: 100%; color: $(black.color); border: solid 1px #ebf0fd;}
.status-msg-wrap b {text-transform: capitalize; font-size: 16px; margin: 0 5px}
/* BLG-C216: $(green.color) on this strip's #f8f8fe measured 2.72:1, so the
 * light-mode link takes the theme's teal #046e8c at 5.41:1. Dark keeps the
 * green, 4.55:1 on --cp-surface, in the html.dark override. */
.status-msg-wrap a {color: #046e8c;}
/* BLG-C216: the feed-error panel is UIkit's .uk-alert-danger, injected by the
 * script at #HTML3. UIkit's own alert red measured 3.21:1 on UIkit's tinted
 * panel; #da0100 (a pinned palette colour) is 4.90:1 on it. */
.uk-alert-danger, .uk-alert-danger p {color: #da0100}
.uk-offcanvas-overlay::before {background: rgba(0,0,0,.7)}
.uk-offcanvas-bar {background: $(white.color); padding: 30px}
.uk-offcanvas-close {color: $(black.color) !important}
.uk-offcanvas-bar .post-box:nth-child(2) {margin-top: 0}
body:not(#layout) .full-width-control {display: none}
body:not(#layout) .cookie-control {display: none}
  body:not(#layout) .default-images-control {display: none}
  body:not(#layout) .newsletter-control {display: none}
.cp-cookie-banner {display: none; position: fixed; left: 0; right: 0; bottom: 0; z-index: 1200; background: var(--cp-card, $(white.color)); border-top: 1px solid var(--cp-soft-border, #A5A5A5); box-shadow: 0 -4px 12px rgba(0,0,0,.18); color: var(--cp-text, $(black.color)); font-size: 14px; line-height: 1.5}
.cp-cookie-inner {max-width: 1200px; margin: 0 auto; padding: 12px 16px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; justify-content: space-between}
.cp-cookie-text {margin: 0; flex: 1 1 280px}
.cp-cookie-actions {display: flex; align-items: center; gap: 8px; flex-wrap: wrap}
.cp-cookie-btn {border: 0; cursor: pointer; font-size: 13px; line-height: 1; padding: 11px 20px; border-radius: 3px; background: var(--cp-surface, #F3F3F3); color: var(--cp-text, $(black.color)); border: 1px solid var(--cp-soft-border, #A5A5A5)}
.cp-cookie-btn-accept {background: $(red.color); color: $(white.color); border-color: $(red.color)}
.cp-cookie-policy {color: var(--cp-text, $(black.color)); text-decoration: underline; font-size: 13px}
@media screen and (max-width: 480px) {.cp-cookie-inner {gap: 8px; padding: 12px} .cp-cookie-actions {justify-content: flex-start} .cp-cookie-btn {padding: 10px 16px}}
.Profile {text-align: center}
.Profile h2 {display: none}
.Profile .widget-content>a {display: block; text-align: center; margin-bottom: 10px}
.Profile .widget-content>a>img {float: none; width: 160px; height: 160px; border: solid 1px #ebf0fd; padding: 5px; border-radius: 100%; margin: 0 0 10px; overflow: hidden; position: relative}
.Profile .widget-content>a>img:after {content: ""; background: rgba(255,255,255,0.6); width: 100%; height: 32px; position: absolute; left: 0; bottom: 0; z-index: 1}
.Profile .profile-name-link {color: $(green.color) !important; background-image: none !important; padding-left: 0; font-size: 22px}
.Profile .profile-textblock {font-size: 14px}
.Profile .profile-link {display: inline-block !important; background: $(red.color); font-size: 12px; padding: 2px 15px; border-radius: 24px}
.contact-me {background: #F8F8FF; padding: 20px; border: solid 1px #ebf0fd}
.contact-me h2.title {text-align: center; color: $(black.color); font-size: 22px}
.contact-me form {font-size: 14px}
.contact-form-name, .contact-form-email {height: 32px; padding: 0 10px; border: solid 1px #ebf0fd; max-width: 100%}
.contact-form-email-message {padding: 10px; border: solid 1px #ebf0fd; max-width: 100%}
.contact-form-button {border: solid 1px $(green.color); background: $(green.color); border-radius: 24px}
.uk-modal-full .uk-modal-dialog {padding: 5% 0}
.uk-modal-full .logo-modal h2.title, .uk-modal-full .logo-modal h2.title a {height: auto; line-height: 42px; display: flex; justify-content: center}
.uk-modal-full .search-modal h2.title, .uk-modal-full .tags-modal h2 {display: none}
.uk-modal-full .search-modal table.gsc-search-box td.gsc-input {width: 95%}
.uk-modal-full .search-modal input.gsc-input {border: none; height: 30px; padding: 0 10px; background: #f5f5f5}
.uk-modal-full .search-modal table.gsc-search-box td {padding: 0; background: $(red.color); position: relative; z-index: 1}
.uk-modal-full .search-modal input.gsc-search-button {color: $(white.color); background: transparent; border: none}
.uk-modal-full .tags-modal ul li {border-bottom: solid 1px rgba(0,0,0,0.05);}
.uk-modal-full .tags-modal ul li a, .uk-modal-full .tags-modal ul li span:nth-child(1), .uk-modal-full .tags-modal ul li span:nth-child(2) {color: $(black.color) !important}
.mog-adv {display: inline-block; width: 100%;}
.mog-adv-ct {display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 700; color: #058bb1; text-transform: uppercase; text-align: center; background: #F8F8FF; border: solid 1px #d1d1dc;} /* BLG-C216: the label was #d1d1dc on #F8F8FF -- 1.43:1 against a 3:1 requirement. #058bb1 is 3.72:1; the grey moves to the box border, where it still draws the placeholder's edge. */
.mog-adv-1 {height: 120px}
.mog-adv-2 {height: 250px}


/* --------------- Footer ---------------- */
#footer {padding: 30px 0}
/* BLG-C217: the footer's logo is the same Header widget as the header's, but at
 * h2 -- and C216 whitened .logo-hd h1.title, the header's heading level, which
 * cannot reach it. The Layout editor also offers the site title as text instead
 * of an image, and in that mode nothing coloured the h2 or its link, so both
 * fell to the UA default: measured 1.01:1 light / 1.23:1 dark on the .bg-grd
 * band. White is 7.03:1 / 12.7:1 here, the same ground the header logo was
 * measured on. The selector already listed the a, so one declaration covers
 * both. */
.logo-ft h2.title, .logo-ft h2.title a {height: 65px; color: $(white.color)}
.text-info-ft .widget-content {font-size: 14px; color: $(white.color); line-height: 1.5}
.social-network-ft ul {padding: 0}
.social-network-ft ul li {padding: 2px; display: inline-block}
.social-network-ft ul li a {display: inline-block; width: 35px; height: 35px; line-height: 33px; color: $(white.color); text-align: center; background: rgba(255,255,255,0.1); border-radius: 100%}

/* BLG-C078: the footer's Policy & Terms box.
   This design used to live inside the gadget's CONTENT, so it travelled as data:
   a new owner received a raw HTML blob in a text widget, the styling could not be
   edited or re-skinned, and the clean distribution copy had to strip it out. It
   is theme CSS now. The owner adds page links in Layout, and renames the box in
   Layout too, because the heading is the widget's title.
   Colours are the theme's own Variables, with the two former literals derived
   from them by color-mix, so a new owner who changes red.color gets a matching
   border and hover tint automatically. This block adds NO hex of its own, so the
   palette fingerprint is unchanged.
   R13: identical in light and dark by design (brand red, white text in both), so
   there is nothing to override and nothing to record as one-sided. */
.policy-section {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  margin: 16px;
  padding: 16px 20px 20px;
  max-width: 100%; /* cover the full footer column, like the logo and tags gadgets */
  box-sizing: border-box;
  border-radius: 8px;
  background-color: $(red.color);
  color: $(white.color);
  font-weight: bold;
}
.policy-section h2 {
  margin-top: 0;
  margin-bottom: 15px;
  border-bottom: 2px solid color-mix(in srgb, $(red.color) 55%, $(white.color));
  padding-bottom: 10px;
  font-size: 1.1em;
  color: $(white.color);
}
.policy-section ul {list-style-type: none; padding: 0; margin: 0}
.policy-section li {margin-bottom: 10px}
.policy-section a {
  text-decoration: none;
  color: $(white.color);
  transition: color 0.2s ease-in-out;
}
.policy-section a:hover {
  color: color-mix(in srgb, $(white.color) 85%, $(black.color));
  text-decoration: underline;
}
/* BLG-C216: html.dark h1..h6 outranks .policy-section h2, so in dark mode the
 * heading inherited --cp-text on the red panel -- 3.65:1 against a 4.5:1
 * requirement. White on that red is 5.49:1 in either mode. */
html.dark .policy-section h2 {color: $(white.color)}

/* BLG-C475: an EMPTY policy section is a red rectangle.
 * This panel is a filled red block (background: red.color), so a section with
 * nothing in it does not read as "nothing" -- it reads as a design element, and
 * on the testing blog it rendered as a 246x36 red bar under the footer. The
 * product ships the Policy & Terms LinkList with its links stripped (they are
 * the previous site's navigation and the sweep removes them), so a fresh
 * install has an empty section until the owner adds their own links.
 * Blogger tags a section it would render empty with `no-items`, and the rendered
 * element has no children at all, so both tests are used: the class when
 * Blogger supplies it, `:empty` when it does not. Neither can hide a panel that
 * has content. */
.policy-section.no-items, .policy-section:empty {display: none}

/* BLG-C475: the same shape of defect, one level up. A Blog widget with no posts
 * renders Blogger's own empty state ("No posts.") plus a pager that reads
 * "Page 1 of 0" -- a count of pages out of no pages. The empty state is
 * correct and stays; the pager is arithmetic nobody needs, so it is removed
 * only when the total is zero. */
.blog-pager .showpageOf + * {margin-left: 0}
.social-network-ft ul li:hover a {background: $(green.color)}
.grp-tags h2 {font: $(cate.text.ft); color: $(white.color); text-transform: uppercase}
.grp-tags ul {padding: 0}
.grp-tags ul li {display: block; padding: 8px 0 8px 20px; border-bottom: solid 1px rgba(255,255,255,0.1); position: relative}
.grp-tags ul li:before {content: ""; position: absolute; left: 0; top: 16px; width: 6px; height: 6px; background: $(green.color)}
.grp-tags ul li:last-child {border-bottom: none}
.grp-tags ul li a, .grp-tags ul li span:nth-child(1) {color: $(white.color); text-transform: capitalize; font-size: 14px}
.grp-tags ul li span:nth-child(1) {color: rgba(255,255,255,0.5)}
.grp-tags ul li span:nth-child(2) {float: right; color: rgba(255,255,255,0.5); font-size: 14px}
.grp-tags .tags-footer ul {max-height: 300px; overflow-y: auto}
/* BLG-C185: the operator asked for a limit in the footer's Tags column, and it
   shipped as six. BLG-C439: the operator lowered that limit to FIVE. Now the
   operator raised it back to SIX.
   Before C185 the column was a scrolling box -- max-height 300px with
   overflow-y auto -- so it showed every tag the owner had selected and hid the
   rest behind a scrollbar nobody discovers in a footer. Six rows measure about
   215px, so the box is no longer needed at all and the scrollbar goes with it;
   the seventh tag and everything after it is simply not rendered.

   nth-child rather than a count in the widget settings, because Blogger's Label
   widget has no "how many" field: this survives the owner adding or removing
   labels, and it holds whether the widget is showing their selected labels or
   all of them. The scope stays .tags-footer so the post tag strip and any other
   label list are untouched. */
.grp-tags .tags-footer ul {max-height: none; overflow: visible}
.grp-tags .tags-footer ul li:nth-child(n+7) {display: none}
.newsletter-sd {width: 100%}
.premium-newsletter-side {position: relative; overflow: hidden; padding: 22px 20px; background: var(--cp-card); border: 1px solid var(--cp-soft-border); border-radius: 0; color: var(--cp-text)}
.premium-newsletter-side:before {content: ""; position: absolute; left: 0; top: 0; width: 4px; height: 100%; background: $(green.color)}
.newsletter-side-icon {width: 42px; height: 42px; margin-bottom: 14px; display: flex; align-items: center; justify-content: center; background: #288047; color: $(white.color); font-size: 18px} /* BLG-C215: white on $(green.color) measured 2.88:1 live, under the 3.0 non-text floor. #288047 is the same green one step darker and is already pinned, so the approved palette is unchanged. The cost, recorded rather than hidden: this circle no longer tracks the theme's green Blogger Variable. */
.newsletter-side-title {margin: 0 0 8px !important; padding: 0 !important; color: var(--cp-text) !important; font: $(cate.text.ft) !important; font-size: 20px !important; line-height: 1.3 !important; text-transform: uppercase}
.newsletter-side-description {margin: 0 0 16px !important; color: #012E3F; font-family: 'Poppins', sans-serif; font-size: 12px; line-height: 1.7}
/* BLG-C061: light-mode AA contrast for the newsletter description. #A5A5A5 on white was 2.46:1; #012E3F is 14.35:1. Dark is left on --cp-muted, which already measures 5.64:1 on #163442. */
html.dark .newsletter-side-description {color: var(--cp-muted);}
.newsletter-side-form {display: block; width: 100%; margin: 0}
.newsletter-side-email {display: block; width: 100%; height: 40px; margin: 0 0 8px; padding: 0 12px; border: 1px solid var(--cp-soft-border); border-radius: 0; outline: none; background: var(--cp-bg); color: var(--cp-text); font-family: 'Poppins', sans-serif; font-size: 12px; box-sizing: border-box}
.newsletter-side-email::placeholder {color: var(--cp-muted)}
.newsletter-side-email:focus {border-color: $(green.color)}
.newsletter-side-submit {display: block; width: 100%; height: 40px; padding: 0 15px; border: 0; border-radius: 0; background: #046e8c; color: $(white.color); font-family: 'Poppins', sans-serif; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .4px; cursor: pointer; transition: opacity .2s ease, transform .2s ease}
.newsletter-side-submit:hover {opacity: .9; transform: translateY(-1px)}
.newsletter-side-trust {display: flex; align-items: center; gap: 5px; margin-top: 10px; color: #012E3F; font-family: 'Poppins', sans-serif; font-size: 9px; line-height: 1.4} /* BLG-C215: live-measured 2.46:1 at 9px in light mode. Same token doing two jobs as BLG-C061 found on the sibling .newsletter-side-description; same literal-plus-dark-override fix, so dark keeps --cp-muted at 5.64:1. */ html.dark .newsletter-side-trust {color: var(--cp-muted);}
.newsletter-side-trust span:first-child {font-size: 9px}
.bot-ft {padding-top: 20px; margin-top: 20px; border-top: solid 1px rgba(255,255,255,0.1);}
.copyright-ft .widget-content {font-size: 14px; color: $(white.color);} /* BLG-C216: the 50% white measured 2.12:1 over the gradient's pale end; full white on the darkened span is 5.43:1. */
/* BLG-C216: this footer text widget sits on .bg-grd, where green measured
 * 2.45:1 (light) and 4.39:1 (dark) -- against a 4.5:1 requirement. White is
 * 7.03:1 / 12.7:1 there, and it already is the footer's link colour. */
.copyright-ft .widget-content a {color: $(white.color);}
      /* One footer line, centred: the copyright widget's own content, with the
         guard appending the free-edition credit beside it on every unlicensed
         blog. The credit is what keeps the free edition free; the guard verifies
         it survives, so the owner cannot remove it through Layout. */
      .bot-ft-line {text-align:center;}
      /* BLG-C479 + BLG-C519 + BLG-C520: the credit is ONE line on a desktop
         and TWO or THREE on a phone. It is built as parts -- the free edition
         ships three (title, rights+year, studio), the activated default two
         (rights, then title+year) -- and the pipes between them are CSS, not
         text. Each separator is a `::before` on the second and third parts,
         never an `::after` on every part, so the last part carries no pipe (the
         activated two-part line used to end on a stray `|`). At the 640px
         breakpoint each part becomes a block and the pipes drop, so the credit
         reads on two balanced lines, or three for the free edition. The parts
         stay spans (not text nodes), so `creditVisible()` and the
         `overflow-wrap` backstop for a long unbroken blog title are unchanged;
         the selectors are scoped to `.copyright-ft`, covering the guard's own
         `#meva-free-credit` and the owner-editable widget default, which
         reuses the same `.mcp-*` classes. */
      .copyright-ft {overflow-wrap:anywhere;}
      .copyright-ft .mcp-2::before, .copyright-ft .mcp-3::before {content:' | '}
      #meva-free-credit a {color:#ea0c3e;}
      @media (max-width:640px) {
        .copyright-ft .mcp-1, .copyright-ft .mcp-2, .copyright-ft .mcp-3 {display:block}
        .copyright-ft .mcp-2::before, .copyright-ft .mcp-3::before {content:''}
      }
      /* BLG-C294: reading mode, the full reader -- all six steps of
         docs/READING-MODE.md behind one switch. The switch is the
          'Reading Mode' Layout gadget (widget HTML23) in the post sidebar:
         the gadget's presence turns the feature on for the blog, and
         removing the gadget turns it off -- the same switch the dark-mode
         gadget (HTML13) already is. The chrome is hidden with display:none
         rather than removed, so the article keeps its place in the DOM and
         the tab order; the control bar lives at the top of the sheet,
         inside the one surface the mode never hides, so the way out
         cannot leave with the chrome. Every colour is a theme token,
         which keeps check-contrast measuring real values in both modes. */
      body.rm-on #header,
      body.rm-on #footer,
      body.rm-on .main-sidebar,
      body.rm-on .sidebar,
      body.rm-on .uk-breadcrumb,
      body.rm-on .post-footer,
      body.rm-on .post-social,
      body.rm-on .post-toc,
      body.rm-on .comments,
      body.rm-on #comments {display: none !important}
      /* BLG-C564: the site pager is a sibling of the sheet, so it collapses
         under the sheet when the sheet goes fixed -- and the post's fade-in
         made it visible through the title for the length of the animation.
         Reading mode has its own pager inside the sheet (below), so the page
         one steps out completely. */
      body.rm-on .blog-pager {display: none !important}
      body.rm-on, body.rm-on #wrapper {background: var(--cp-bg)}
      /* BLG-C561: the sheet scrolls inside its own column; the control bar
         is its first child, sticky at the sheet's top, so it sits between
         the ticker and the title and never covers the text. The page itself
         stops scrolling while the mode is on (BLG-C555). */
      body.rm-on .post.hentry {position: fixed; top: calc(78px + env(safe-area-inset-top, 0px)); bottom: calc(12px + env(safe-area-inset-bottom, 0px)); left: 0; right: 0; margin: 0 auto; width: calc(100% - 24px); width: min(72ch, calc(100% - 24px)); padding: 0 4px; overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; z-index: 9998; background: var(--cp-bg)}
      /* BLG-C558: the sheet owns the scrolling; its scroll bar is chrome
         the reader never asked for. Both spellings, so Firefox and
         WebKit agree. */
      body.rm-on .post.hentry {scrollbar-width: none; -ms-overflow-style: none}
      body.rm-on .post.hentry::-webkit-scrollbar {display: none}
      body.rm-on .post.hentry {padding-bottom: calc(56px + env(safe-area-inset-bottom, 0px))}
      body.rm-on {overflow: hidden}
      body.rm-on .post-top-container,
      body.rm-on .post-first-image,
      body.rm-on .post-body.entry-content {max-width: 68ch; margin-left: auto; margin-right: auto}
      body.rm-on .post-top-container h3.post-title {font-family: 'PT Serif', Georgia, serif; font-weight: 700; font-size: clamp(28px, 3.4vw, 40px); line-height: 1.3; text-transform: none}
      body.rm-on .post-body.entry-content {font-family: 'PT Serif', Georgia, serif; font-size: 1.125em; line-height: 1.8; --rm-fs: 1}
      body.rm-on .post-body.entry-content img {max-width: 100%; height: auto}
      /* BLG-C558: the size step scales TEXT only. The container keeps its
         base font-size, so every em-based structural metric around the
         words -- the table of contents, section boxes, the post graphics
         -- stays put and the step never jerks the layout. */
      body.rm-fs-1 .post-body.entry-content {--rm-fs: 1.111}
      body.rm-fs-2 .post-body.entry-content {--rm-fs: 1.222}
      body.rm-on .post-body.entry-content :where(p, h1, h2, h3, h4, h5, h6, li, dd, dt, td, th, blockquote, figcaption, summary, cite):not(.post-toc *) {font-size: calc(1em * var(--rm-fs, 1))}
      /* BLG-C559: the reading aids (read time, quick read) are gone -- the
         operator judged them noise on a quiet surface. The end-of-post card
         is the one thing that follows the article. */
      .rm-exit {display: none}
      body.rm-on .rm-exit {display: block; max-width: 68ch; margin: 24px auto 8px; padding: 14px 16px; border: 1px solid var(--cp-soft-border); border-radius: 12px; background: var(--cp-card); text-align: center}
      .rm-exit button {display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; padding: 10px 18px; border: 1px solid var(--cp-soft-border); border-radius: 999px; background: var(--cp-text); color: var(--cp-bg); font: 600 14px/1.3 'Poppins', 'Segoe UI', Arial, sans-serif; cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
      .rm-exit button:focus-visible {outline: 3px solid var(--cp-text); outline-offset: 2px}
      /* BLG-C561: the sentence marker is a thin rule under the tracked line,
         not a filled background -- a filled span reads as a text selection,
         especially on the dark section cards. `color: inherit` is load-bearing:
         the browser's own `mark` colour would otherwise turn the sentence black
         in dark mode. The current word keeps the token pair. */
      .rm-say {background: none; color: inherit; box-shadow: inset 0 -2px 0 currentColor; -webkit-box-decoration-break: clone; box-decoration-break: clone}
      .rm-word {background: var(--cp-text); color: var(--cp-bg); border-radius: 4px; padding: 0 .12em; margin: 0 -.12em; -webkit-box-decoration-break: clone; box-decoration-break: clone}
      /* The sidebar entry gadget. The includable renders it on post pages
         only; the reader script hides it everywhere else as a belt to the
         server's braces. */
      .rm-entry-box {padding: 14px; border: 1px solid var(--cp-soft-border); background: var(--cp-card)}
      .rm-entry {display: inline-flex; align-items: center; justify-content: center; gap: 8px; width: 100%; padding: 10px 14px; border: 1px solid var(--cp-soft-border); border-radius: 999px; background: var(--cp-card); color: var(--cp-text); font: 600 14px/1 'Poppins', 'Segoe UI', Arial, sans-serif; cursor: pointer}
      .rm-entry:hover {border-color: var(--cp-text)}
      .rm-entry[aria-pressed='true'] {background: var(--cp-text); color: var(--cp-bg)}
      .rm-entry:focus-visible {outline: 3px solid var(--cp-text); outline-offset: 2px}
      .rm-entry-hint {margin: 10px 0 0; font: 300 12px/1.5 'Poppins', 'Segoe UI', Arial, sans-serif; color: var(--cp-text)} /* BLG-C589: --cp-muted measured 2.46:1 on this card's own --cp-card ground in light mode (12px, weight 300 -- no large-text allowance). Same remedy as BLG-C216's footer copy: the size and weight already make it quiet, the ink has to be readable. */
      /* BLG-C562: on a phone the sidebar is below the whole article, so its
         entry button is the last thing a reader can reach. A second button
         immediately before the table of contents is the same control and the
         same switch; the reader script reveals it only after it confirms the
         HTML23 gadget, so removing the gadget still removes the feature. The
         sidebar box steps aside at the same breakpoint to avoid a duplicate
         entry at the end of the post. BLG-C564 moved it out of the title
         panel and gave it the column's rhythm: 14px above and below, so it
         never touches the header divider or the table of contents. */
      .rm-entry-top {display: none}
      .rm-entry-top[hidden] {display: none !important}
      @media (max-width: 960px) {
        .rm-entry-top {display: inline-flex; width: auto; min-height: 40px; margin: 14px 0; padding: 8px 14px; font-size: 13px}
        .post-first-image + .rm-entry-top {margin-top: 14px}
        .rm-entry-box {display: none}
        body.rm-on .rm-entry-top {display: none}
      }
      /* BLG-C561: the control bar lives at the TOP OF THE READING SHEET,
         between the breaking-news ticker and the post title, and sticks as
         the sheet scrolls -- the fixed top-centre pill used to sit on the
         ticker. It is a child of the sheet (not the hidden chrome), and the
         env(safe-area-inset-*) terms keep the chip clear of notched-phone
         bezels. Buttons sit at 40px -- the WCAG 2.2 AA target minimum -- with
         touch-action set so a double-tap never waits out the zoom delay. */
      .rm-bar {position: sticky; top: 0; z-index: 9999; display: none; align-items: center; gap: 2px; width: max-content; max-width: 100%; margin: 0 auto 10px; padding: 5px; border: 1px solid var(--cp-soft-border); border-radius: 999px; background: var(--cp-card); box-shadow: 0 8px 24px rgba(0,0,0,.18); overflow-x: auto; scrollbar-width: none}
      .rm-bar::-webkit-scrollbar {display: none}
      body.rm-on .rm-bar {display: flex}
      .rm-bar button {display: inline-flex; align-items: center; justify-content: center; min-width: 40px; height: 40px; padding: 0 10px; border: 0; border-radius: 999px; background: transparent; color: var(--cp-text); font: 600 13px/1 'Poppins', 'Segoe UI', Arial, sans-serif; cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
      .rm-bar button:hover {background: var(--cp-surface)}
      .rm-bar button[aria-pressed='true'] {background: var(--cp-text); color: var(--cp-bg)}
      .rm-bar button:disabled {opacity: .45; cursor: default}
      .rm-bar .rm-pos {min-width: 40px; padding: 0 4px; text-align: center; font: 400 11px/1 'Poppins', 'Segoe UI', Arial, sans-serif; color: var(--cp-muted)}
      .rm-bar button:focus-visible {outline: 3px solid var(--cp-text); outline-offset: 2px}
      /* BLG-C592: a zero-height flex break, hidden until the narrowest phone.
         It forces play/prev/next/rate onto the first line and fs/lang/dark/
         close onto the second, instead of squeezing every label into one
         clipped row. Hidden by default so the desktop bar is untouched. */
      .rm-bar .rm-break {display: none}
      /* BLG-C564: reading mode's own post pager. The site pager is outside
         the fixed sheet and flashed through the post's fade-in across the
         title; this copy lives inside the sheet, in the gap between the
         author/date row and the hero, and stays for as long as the reader
         wants it. Three fixed columns keep Home centred when a first or last
         post has only one neighbour. */
      .rm-pager {display: none}
      body.rm-on .rm-pager {display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 4px; width: 100%; max-width: 68ch; margin: 0 auto 18px; padding: 4px 0; border-top: 1px solid var(--cp-soft-border); border-bottom: 1px solid var(--cp-soft-border)}
      .rm-pager a {display: inline-flex; align-items: center; gap: 6px; min-height: 40px; padding: 0 6px; border-radius: 10px; color: var(--cp-text); font: 600 13px/1.3 'Poppins', 'Segoe UI', Arial, sans-serif; text-decoration: none; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
      .rm-pager a:hover {background: var(--cp-surface)}
      .rm-pager a:focus-visible {outline: 3px solid var(--cp-text); outline-offset: 2px}
      .rm-pager .rm-pager-older {justify-self: end}
      .rm-pager .rm-pager-home {justify-self: center; min-width: 40px; padding: 0; justify-content: center}
      .rm-pager svg {flex: 0 0 auto}
      /* The manual-scroll-paused affordance: the reader's gesture outranks
         the feature, and this is the way back. */
      /* BLG-C563: a fixed box at left:50% shrink-to-fits against HALF the
         viewport, so on a phone the chip squeezed its flex items and
         "Resume" broke into two lines. Size to content instead, cap it at
         the viewport, and never let the button shrink or wrap. */
      .rm-resume-chip {position: fixed; bottom: calc(16px + env(safe-area-inset-bottom, 0px)); left: 50%; transform: translateX(-50%); width: max-content; max-width: calc(100vw - 24px); z-index: 9999; display: none; align-items: center; gap: 8px; padding: 8px 8px 8px 14px; border: 1px solid var(--cp-soft-border); border-radius: 999px; background: var(--cp-card); box-shadow: 0 8px 24px rgba(0,0,0,.18); font: 400 13px/1 'Poppins', 'Segoe UI', Arial, sans-serif; color: var(--cp-text)}
      .rm-resume-chip.rm-show {display: inline-flex}
      .rm-resume-chip button {flex: 0 0 auto; white-space: nowrap; padding: 7px 12px; border: 0; border-radius: 999px; background: linear-gradient(135deg, $(black.color) 0%, $(black.color) 55%, $(green.color) 165%); color: $(white.color); font: 600 12px/1 'Poppins', 'Segoe UI', Arial, sans-serif; cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent}
      /* BLG-C561: a phone gets the same bar in the same place as the desktop
         -- at the top of the sheet, between the ticker and the title. The
         sentence counter steps out on the narrowest column so every remaining
         control keeps its full 40px target; the sheet uses the phone's width,
         which leaves room for the eight controls in one row. The body step to
         1.2em is the reading size a phone arm's length wants; the size
         multiplier rides on top of it, and break-word keeps long URLs and
         Devanagari runs inside the column. */
      @media (max-width: 480px) {
        .rm-bar {justify-content: center; gap: 0; padding: 4px}
        .rm-bar .rm-pos {display: none}
        .rm-bar .rm-lang {white-space: nowrap; font-size: 12px; padding: 0 4px}
        .rm-resume-chip {bottom: calc(16px + env(safe-area-inset-bottom, 0px))}
        body.rm-on .post.hentry {width: calc(100% - 8px); bottom: calc(12px + env(safe-area-inset-bottom, 0px))}
        body.rm-on .post-body.entry-content {font-size: 1.2em; overflow-wrap: break-word}
        .rm-exit button {width: 100%}
      }
      @media (max-width: 380px) {
        .rm-bar {flex-wrap: wrap; gap: 2px}
        .rm-bar .rm-break {display: block; flex: 0 0 100%; height: 0; margin: 0; padding: 0}
      }
      @media print {.rm-bar, .rm-pager, .rm-resume-chip, .rm-entry-box, .rm-exit {display: none !important}}
      /* BLG-C408: the Licence Activation gadget. Hidden by default and revealed
         only in Layout mode. Palette-frozen literals only (check 5a). */
      #HTML22 {display:none;}
      body#layout #HTML22 {display:block;}
      #HTML22 .lic-hint {margin:0 0 12px;font-size:13px;line-height:1.55;color:#d9e9f0;}
      #HTML22 .lic-hint code {font:13px ui-monospace,SFMono-Regular,Menlo,monospace;color:#fff;}
      /* The free-edition release serial, in the same Layout-only gadget. It sits
         with the paste instructions and inherits their visibility, so no rule is
         needed to hide it from readers; these only make the block readable and
         visually separate from the licence box above it.
         Every colour here is already in tests/palette-freeze.txt: the operator
         froze the palette on 2026-09-26, so a new literal is a build failure and
         the right move is to reuse what the gadget already renders in. */
      #HTML22 .lic-fes-hint {margin:16px 0 4px;font-size:13px;line-height:1.55;color:#d9e9f0;border-top:1px solid #2c4e60;padding-top:12px;}
      #HTML22 .meva-fes {font:13px ui-monospace,SFMono-Regular,Menlo,monospace;color:#fff;word-break:break-all;}
      #HTML22 .lic-fes-note {margin:4px 0 0;font-size:12px;line-height:1.5;color:#8fafbf;}
      /* BLG-C535: the gadget carries its own ground. Blogger paints this Layout
         region #daca08 and white text there measures 1.69:1, so the serial was
         invisible in the one editor it exists in -- see FREE-SERIAL-LOCK.md. */
      body#layout #HTML22 {background:#0b1d27;padding:14px 16px;border-radius:10px;}
.icon-to-top {color: #fff; width: 48px; height: 48px; background: #ea0c3e; border-radius: 100%; display: flex; align-items: center; justify-content: center; position: fixed; right: 16px; bottom: 72px; z-index: 990; box-shadow: 0 8px 24px rgba(0,0,0,.18); opacity: 0; visibility: hidden; pointer-events: none; transform: translateY(8px); transition: opacity .18s ease, visibility .18s ease, transform .18s ease, box-shadow .18s ease, background-color .18s ease;}
/* BLG-C562: the control is absent until the reader has actually scrolled.
   The page script adds .is-visible at 30% of the scrollable height and takes
   it away again at the top, so the fixed button never covers the article's
   opening screen. visibility (not just opacity) keeps the hidden link out of
   the tab order and the accessibility tree. */
.icon-to-top.is-visible {opacity: 1; visibility: visible; pointer-events: auto; transform: none;}
.icon-to-top:hover {color: #fff; background: #da0100; transform: translateY(-2px); box-shadow: 0 12px 28px rgba(0,0,0,.18);}
.icon-to-top:focus-visible {outline: 2px solid #fff; outline-offset: 2px;}
.icon-to-top .cp-ico-up {display: block;}


/* --------------- 404 ---------------- */
.mog-404 {text-align: center; margin: 170px auto; padding: 0 20px; max-width: 840px}
.mog-text-error {position: relative}
.mog-text-error span {position: absolute; width: 100%; left: 0; top: 0; text-transform: uppercase; color: #999; font-size: 22px;}
.mog-text-404 {font-weight: 700; font-size: 92px; color: $(green.color); text-transform: uppercase}
.mog-text-if-404 {}
.mog-text-if-404 span {font: $(cate.text.ft); text-transform: uppercase; line-height: 32px}
.mog-text-if-404 p {margin: 10px 0 0; color: #999;}
.mog-text-if-404 p a {display: inline-block; color: $(green.color)}
.mog-search-404 {margin-top: 30px}
.mog-form-search-404 {margin-bottom: 10px; position: relative; padding-right: 110px}
.mog-input-text-404 {border: none; background: #f5f5f5; padding: 0 15px; height: 38px; width: 100%}
.mog-btn-search-404 {position: absolute; right: 0; top: 0; height: 38px; background: $(green.color); color: #fff; padding: 0 15px; border: none; font-size: 12px; text-transform: uppercase;}

/* --------------- Post TOC (F13) ---------------- */
.post-toc {margin: 0 0 25px; background: #F8F8FF; border: solid 1px #ebf0fd; border-left: 3px solid $(red.color); font-size: 14px}
.post-toc-title {margin: 0; padding: 12px 14px; font: 700 13px 'Poppins', sans-serif; text-transform: uppercase; letter-spacing: .5px; color: $(black.color); display: flex; align-items: center; gap: 8px; cursor: pointer; border: none; background: none; width: 100%; text-align: left; -webkit-user-select: none; user-select: none}
.post-toc-title:hover {color: $(red.color)}
.post-toc-title:focus {outline: none; color: $(red.color)}
.post-toc-title .uk-icon {color: $(red.color)}
.post-toc-caret {margin-left: auto; width: 8px; height: 8px; border-right: 2px solid $(red.color); border-bottom: 2px solid $(red.color); transform: rotate(-135deg); transition: transform .2s ease}
.post-toc.is-collapsed .post-toc-caret {transform: rotate(45deg)}
.post-toc ol {margin: 0; padding: 8px 14px 12px 32px; border-top: solid 1px #ebf0fd}
.post-toc ol[hidden] {display: none}
.post-toc ol li {margin: 4px 0; line-height: 1.5}
.post-toc ol li::marker {color: $(red.color); font-weight: 700}
.post-toc ol li a {color: $(black.color); text-decoration: none; border-bottom: 1px solid transparent; transition: color .15s ease, border-color .15s ease}
.post-toc ol li a:hover {color: $(red.color); border-bottom-color: $(red.color)}
html.dark .post-toc {background: var(--cp-surface); border-color: rgba(255,255,255,.1); border-left-color: $(red.color)}



/* --------------- Responsive ---------------- */
@media (min-width: 641px) and (max-width: 960px) {
.post-entry-2 .post-thumb {height: 300px}
.post-entry-6 .post-thumb {height: 465px}
.post-entry-7 .post-thumb {height: 150px}
.PopularPosts ul li {float: left; width: 47%; padding: 10px !important}
.PopularPosts ul li:last-child {display: none}
.PopularPosts ul li .item-thumbnail {float: none; width: 100%; margin: 0 0 10px;}
}

@media (min-width: 960px) {
.sidebar-container .sidebar {position: sticky; top: 0}
}

@media (max-width: 640px) {
/* BLG-C149: this reserve is STALE and the operator found the result. The logo's
   max-width subtracts a fixed 180px to leave room for the header controls on
   the right, and 180 was correct when there were fewer of them. Measured on the
   live blog at 390px the header shows FOUR controls, which after the padding
   change below occupy 162px, and the logo was still being allowed
   min(220px, 100vw - 180px) = 210px of image inside 25px of its own padding and
   20px of the header's, so the logo box ended at x=255 while the first control
   icon started at x=197. TWO icons were sitting on top of the wordmark, which is
   the defect the operator reported as an icon overlapping the logo. The reserve
   is now 230px, which is the 162px of controls plus the 25px logo padding plus
   the 20px header padding plus 23px of clearance, and it is a floor-guarded
   expression so a viewport too narrow for the arithmetic yields a small logo
   rather than a negative max-width, which the browser would discard and let the
   250px rule on the earlier line win. At 390 that gives a 160px logo ending at
   x=205 against controls starting at x=228. On desktop this line does not apply
   at all: it is inside the 640px query and the logo is capped at 220px there
   anyway, so nothing above 640px moves. */
.logo-hd a img {max-width: min(220px, max(60px, calc(100vw - 230px)))}
.bk-news {padding-left: 35px;}
.post-entry-2 .post-thumb, .post-entry-6 .post-thumb {height: 400px;}
.post-entry-3 .post-date {display: block;}
.post-entry-3 .post-thumb, .post-entry-4 .post-thumb, .post-entry-8 .post-thumb, .post-entry-10 .post-thumb {height: 250px;}
.post-entry-7 .post-item {margin: -10px 0 0;}
.post-entry-7 .post-thumb, .post-entry-9 .post-thumb, .post-entry-11 .post-thumb, .post-entry-12 .post-thumb, .post-entry-13 .post-thumb, .post-entry-14>div>div>div>.post-thumb {height: 125px;}
.post-entry-12 h3.post-title, .post-entry-12 h3.post-title a {font-size: 16px} /* BLG-C450: heading carries the clamp, so it takes the size too */
.PopularPosts ul li .item-thumbnail {float: none; width: 100%; margin: 0 0 10px;}
/* BLG-C124: on mobile the Most Like thumbnail box is a wide 125px-tall strip,
   so object-fit cover centered vertically (50% 50%) shows only the middle band
   of the 300x250 source: the subject's face is cropped off the top and the
   bold text line peeks through at the bottom. Shifting the vertical object
   position to 20% (measured: the face/subject spans source rows ~32-148 and
   text starts at row 149, so 20% lands the visible window on rows ~29-136)
   reveals the whole face and hides the text completely on mobile only. Base
   rule at 50% 50% stays untouched for desktop and tablet. */
.PopularPosts ul li .item-thumbnail img {object-position: 50% 20%;}
.post-social {width: 100%; text-align: center}
.post-social ul li {display: inline-block; margin: 0 !important}
.author-profile {text-align: center}
.author-img {display: inline-block; width: 100%}
.author-img img {float: none; margin: 0 0 20px}
.post .tr-caption-container {width: 100%; padding: 0}
.uk-list-striped {padding: 0 !important}
.comments .comments-content .comment-replies {margin-left: 0}
.uk-offcanvas-bar {width: 320px}
/* BLG-C068: the header control row is a uk-grid whose children are sized only at
   @s and above (uk-child-width-1-5@s). Below 640px nothing sizes them, so all
   four controls land on auto columns and the first two sit over the logo. Hide
   the social and search controls on mobile; hot news and the dark-mode toggle
   stay. Same 640px boundary every other mobile rule in this file uses, so
   "mobile" means one thing here. Scoped body:not(#layout) so the Blogger Layout
   editor still shows both gadgets -- an editor that hides gadgets you may need
   to configure is a worse problem than the one being fixed. NOT uk-hidden@s,
   which would hide them in the editor too. No !important needed:
   body:not(#layout) .cp-hd-social is 0-2-1 against .control-hd's 0-1-0.
   Identical in light and dark (R13): one rule, both modes, no token involved. */
body:not(#layout) .cp-hd-social {display: none}
/* BLG-C122: despite BLG-C068, the header control row still carries a suffix-less
   uk-child-width-1-5 on its container, which forces every child to 1/5 of the
   shrink-to-fit absolute container at ALL widths. Below 640px that collapsed the
   three visible controls (hot news, dark-mode toggle, nav) to ~24px cells and
   4px buttons, making them visually broken and effectively untappable on phones.
   Override the child width to auto on mobile so each control is content-sized
   (~40px cell, 24px+ tap target); shrink the logo in step with the viewport so
   it never overlaps the control cluster. Scoped body:not(#layout) like BLG-C068
   so the Layout editor still sees the original layout. No !important needed:
   body:not(#layout) .grp-control-hd > .control-hd is 1-2-1 against
   uk-child-width-1-5 > *'s 0-2-0. Identical in light and dark (R13). */
}

/* BLG-C139: the same collapse happens on DESKTOP, which the mobile-only C122 rule
   above never covered. .grp-control-hd is a uk-grid inside a shrink-to-fit
   .uk-position-right, and the suffix-less uk-child-width-1-5 on its container
   forces every control into a fifth of that width at EVERY breakpoint. Measured
   on the live header at 1280px: each .control-hd was 30px wide, and because
   .control-hd carries 10px of side padding the button got a 10px content box --
   so a 20x20 icon rendered at 10x10 inside a 10x38 tap target. The controls are
   therefore content-sized at base level rather than only under 640px, and the
   icon is given an explicit box so a narrow cell cannot squeeze it again. The
   dark toggle keeps its own padding: it sets that on .cp-dark-toggle at 2
   classes, and this selector is more specific, so padding is left alone here. */
body:not(#layout) .grp-control-hd > .control-hd {width: auto; flex: 0 0 auto}
body:not(#layout) .grp-control-hd > .control-hd button {min-width: 34px; min-height: 34px; display: flex; align-items: center; justify-content: center}
body:not(#layout) .grp-control-hd > .control-hd .uk-icon,
body:not(#layout) .grp-control-hd > .control-hd .uk-icon svg {width: 20px; height: 20px; display: block}

/* BLG-C157: the Social Network Header section sits in a header-group cell so the
   Layout editor shows four header gadgets as two rows of two, but on the front
   end it belongs inside .cp-hd-social's dropdown panel, which is where the
   relocation script that follows the header element puts it back. The cell that
   carries it in the header row is therefore an editor surface only. Hide it on
   the front end for two reasons: the header row keeps its three cells whether or
   not the script has run, and the link list cannot flash inline in the row before
   it is moved. Scoped body:not(#layout) like BLG-C068/C122/C139 so the editor
   keeps the cell and the gadget inside it. No !important needed: the slot class
   is unique to this cell, so nothing competes with it. */
body:not(#layout) #header .cp-hd-social-slot {display: none}

/* BLG-C601: the desktop nav is a single line of six top-level links measuring
   870px, and the header's control cluster is absolutely positioned over the
   right end of that row. Below 1360px there is no viewport where both fit: at
   1024px the nav cell is 744px, so Speed & SEO and About wrap to a second line
   at y=61 and paint over the ticker (y=72.7); at 1155px the line fits but its
   last 127px sits under the controls; at 1280px the overlap is 22px. Only from
   1360px up does the centered 1200px container leave the 18px of clearance the
   row needs. So the shipped phone menu is now the menu for every width below
   1360 as well: the same #nav-mb list, the same .nav-hidden toggle, the same
   accordion rules, one breakpoint instead of two behaviours that never fit.
   The toggle cell was .uk-hidden@m before, so it vanished at exactly the width
   where the row started to break; it is .cp-nav-toggle now and is hidden only
   at 1360px and above. */
@media (max-width: 1359px) {
.nav-hd ul li.mega-menu {position: relative;}
/* BLG-C212: this rule is the reason the panel would not close on a phone.
 * `:hover` on a TOUCH device does not behave like hover. A tap sets the hover
 * state and the browser KEEPS it, because there is no cursor to move away; it
 * survives until the user taps somewhere else entirely. So below 1360 this rule
 * forced `display: block` on the panel the moment it was tapped, and it stayed
 * forced -- the `data-open` attribute the tap toggled went away, but this rule
 * did not, because it is not conditioned on anything the script controls.
 * The panel then sat open over the content with no way to dismiss it short of
 * tapping elsewhere on the page. That is the "options remain back when we close
 * it" report, still present after the :focus-within fix, because the cause here
 * is a sticky :hover and not :focus-within at all.
 * The fix is to scope hover to pointers that actually hover. `(hover: hover)`
 * is false on a touch device, so the rule does not apply there and touch is left
 * entirely to `data-open`, which the script owns and can always clear. On a
 * laptop or a desktop nothing changes, because `(hover: hover)` is true.
 * `display` is a discrete property and cannot be transitioned, so this is done
 * with the media feature rather than a transition. */
@media (hover: hover) {
  .nav-hd ul li.mega-menu:hover .mega-container {display: block;}
}
/* BLG-C208. This forced `visibility: visible !important` with no condition at
 * all, so below 1360 the mega panel was laid out whether or not it was open --
 * which is the spread-across-the-header on load. The panel is now visible only
 * when it is actually open: the hover rule above, or the parent carrying
 * data-open / :focus-visible (see the block at the foot of the skin).
 * BLG-C211: `position: inherit` is replaced by `position: static`. `inherit`
 * takes the parent's computed value, and the parent `li` is `position: relative`
 * (L1038), so the panel became a positioned box inside that li -- while
 * `margin: 10px 0` still reserved vertical space whether it was shown or not.
 * `static` with an explicit zero margin when closed, and a real margin only in
 * the open state (foot of skin), means a shut panel occupies nothing. */
.nav-hd ul li .mega-container {position: static !important; margin: 0; display: none;}
.nav-hidden {display: block !important;}
/* BLG-C601: display:none is new. Above 960px the nav used to be forced visible
   by uk-visible@m; that class is gone, so the closed state has to be declared
   here. The absolute box is the shipped phone menu, unchanged. The Layout
   editor keeps the cell: a hidden Navigation section would leave the operator
   no surface to edit the link list, so body#layout opts out. */
.nav-hd {position: absolute; width: 100%; left: 0; top: 100%; height: auto; z-index: 999; background: $(black.color); display: none}
body#layout .nav-hd {display: block;}
.nav-hd ul ul {width: 100%; top: auto;}
.nav-hd ul li {display: block; border-bottom: dashed 1px rgba(255,255,255,0.1); padding: 8px 20px;}
.nav-hd ul li .icon-parent {position: absolute; top: 12px; right: 20px;}
.nav-hd ul ul, .nav-hd ul ul ul {position: relative; margin: 5px 0; display: none;}
.nav-hd ul ul ul {left: 0; display: none; box-shadow: none;}
.nav-hd ul ul ul li {padding: 8px 0; margin: 0 20px;}
/* BLG-C212: same sticky-:hover trap as the mega panel above, applied to the
 * plain dropdowns. A tap on a parent row sets :hover and the browser keeps it,
 * so `display: block` was stuck on and the submenu could not be dismissed.
 * Scoped to (hover: hover) so touch devices are driven by the script's
 * data-open state instead, which is always clearable. No change on desktop. */
@media (hover: hover) {
  .nav-hd ul li.uk-parent:hover > ul {display: block; top: auto;}
  .nav-hd ul ul li:hover ul {left: 0; display: block; top: auto;}
}
}

/* BLG-C605: at phone widths the 44px logo inset existed only to clear the
   absolute left trigger. That trigger now lives in the right control cluster
   at phones, so below 961 the inset is gone and the logo starts on the page's
   own content edge -- x=20 -- exactly where the ticker and article column
   start. At tablet widths (961-1359) BLG-C606 puts the trigger back on the left
   and restores the inset there. From 1360 up the left trigger stays in the wide
   outer margin and the logo is already aligned, so nothing in that band
   changes. */
@media (max-width: 960px) {
body:not(#layout) #header > .uk-position-left {display: block; overflow: hidden;}
.logo-hd:not(.logo-ft) {padding-left: 32px; justify-content: flex-start;}
.cp-hd-menu {display: none;}
}

/* BLG-C606: the operator's live tablet screenshot showed the logo aligned
   but the menu icon sitting in the right control cluster; the tablet row is
   re-arranged so the drawer icon stays on the left. At 961-1359 the absolute
   left trigger is restored (966-1360 display:block), the inset comes back with
   it, and the right `.cp-hd-menu` cell created for phones in C605 is hidden,
   so each width shows exactly one drawer trigger. The icon is the same 34px
   tap target C605 measured, with the old 20px horizontal padding and stacking
   lift dropped again because it no longer sits under .uk-container. */
@media (min-width: 961px) and (max-width: 1359px) {
body:not(#layout) #header > .uk-position-left {display: block;}
.logo-hd:not(.logo-ft) {padding-left: 44px; justify-content: flex-start;}
.cp-hd-menu {display: none;}
#header .cp-nav-toggle {margin-left: auto; order: 99;}
}

/* BLG-C607: pin the tablet row to the CONTENT edges, not the viewport edges.
   The operator's tablet screenshot approved the menu-on-the-left layout, then
   asked for both ends pinned to where content starts and ends -- the way the
   pre-C605 logo sat on the left edge. Padding the logo by the margin (variant
   B) fails the ask at every width: the 44px trigger box sits at x=0 first and
   would need a negative pull-back to meet the edge, while the kebab already
   ends 4px short of it. So the row is inset instead:
   left, the trigger wraps in `overflow:hidden` and is pulled in by exactly
   the bleed, so the icon's visible glyph starts exactly where the content
   does; the icon keeps its glyph and a 34px tap box, only its slack is
   hidden;
   the logo then clears the 44px trigger with the pre-C605 inset, so it sits
   after the hamburger instead of on it (measured: 44 at 961-1155, 64 at 1280,
   103.5 at 1359 -- always 20px behind the pinned glyph, exactly the C603
   breathing room the operator approved);
   right, the kebab cell sheds its 4px side padding and fixed box for a 24px
   content-sized button, and the cluster drops its 10px right padding, so the
   glyph's right edge lands 10px off the edge on the centered band
   (1150 at 1280, 1316.5 at 1359) and 3.5px below 1240 (957.5 at 1155, 891.5
   at 1024, 830.5 at 961); the grid, not a guessed pixel, carries the rest.
    The drawer trigger stays a real, clickable anchor -- overflow clips paint,
    not hit-testing -- and this band is the only one touched.
    BLG-C611 replaces the two 100vw pins below with the header's own width:
    100vw is the scrollbar-less viewport, so in a 15px-scrollbar browser both
    pins sat 7.5px off, and they slid again whenever the off-canvas drawer
    took the scrollbar. The measurements quoted above are the 100vw-era ones. */
@media (min-width: 961px) and (max-width: 1359px) {
body:not(#layout) #header > .uk-position-left {overflow: hidden;}
.logo-hd:not(.logo-ft) {padding-left: 44px;}
#header > .uk-position-right > .grp-control-hd {margin: 0; padding: 0;}
#header .cp-nav-toggle > .nav-mb, #header .cp-nav-toggle > .nav-mb > button {margin: 0; padding: 0;}
#header .cp-nav-toggle > .nav-mb > button {display: flex; align-items: center; justify-content: flex-end; width: 24px; height: 34px;}
}

/* BLG-C611: the drawer trigger moved 7.5px to the left every time the
   off-canvas drawer opened, and the phone/tablet trigger was never on the
   content edge at all. Cause: UIkit opens the overlay drawer by moving the
   overflow from the html element to the body element (uk-offcanvas-page /
   uk-offcanvas-container), the root scrollbar goes away, and Chrome re-bases
   100vw by the scrollbar width. Measured live at 1280 with a 15px scrollbar:
   100vw 1280 closed and 1265 open, so C607's `max(0px, (100vw - 1240px) / 2)`
   fell from 20px to 12.5px -- the trigger's glyph slid from x=30 to x=22.5
   while the content edge stayed at x=32.5, and the cluster slid 7.5px right;
   both sprang back on close. The pins are now computed from the header's own
   width: 100% of the containing block (the header is position:relative) is
   the body client width, which does NOT change when the drawer takes the
   scrollbar, so the row is pinned to the content edges in every state.
   left, `+ 10px` is the icon's own horizontal padding (`.icon-menu` is
   padding:0 10px), so the visible glyph lands exactly on the content's left
   edge: measured 32.5 at 1280 (edge 32.5), 72 at 1359 (edge 72), 20 at 1155,
   1024, 961, 390 and 320 (edge 20 at every one of them). The phone band gets
   it too, which is what C610's own numbers wanted -- the logo 8px behind the
   visible glyph -- and it is the operator's reported defect.
   right, `+ 20px` is the container's padding, so the cluster's right edge
   lands on the content's right edge: 1232.5 at 1280, 989 at 1024, 370 at 390.
    Measured at 1280: the glyph, the cluster and every control cell sit at
    exactly the same x with the drawer closed, open and closed again.
    Three-dot: the operator asked for the nav kebab pinned to the content's
    right edge as well, and for the other right-side icons to keep their
    padding and their spacing. Measured on the served page: the kebab cell is
    42px wide (4px padding each side plus the 34px button) and its 20px glyph
    sat centred in that button, so the glyph's right edge was 11px inside the
    content edge (359 at 390, 978 at 1024, 1261 at 1359). The cell now keeps
    its 42px width -- the right padding goes to 0 and the left padding grows
    4px -> 8px -- and the icon is pushed to the right end of its button, so
    the glyph lands exactly on the content's right edge (370 at 390, 989 at
    1024, 1272 at 1359) while every other cell of the cluster keeps its
    width, its padding and its position, so the spacing of the HOT badge,
    the search, the social row and the dark toggle is untouched.
    Desktop logo: at 1360 the logo image sat flush on the content's left edge
    (x=72.5) and the operator asked for it to stop being glued there. A plain
    20px inset is not free: the nav labels end 10.7px short of the HOT badge
    (About ends 1162.3, the badge starts 1173), so the inset has to be paid
    for out of the gap between the image and the first nav label (35px), not
    out of the badge clearance. The logo takes the 20px gutter and gives the
    20px back to that gap, so the row's geometry is unchanged: the nav still
    starts at x=292.5, About still ends 1162.3, the badge still starts 1173.
    Measured at 1360: the image x=92.5 (72.5 + 20), the logo still 200px
    wide, the header still 60.7 tall, scrollWidth == clientWidth.
    The >=1360 band keeps the row in the wide outer margin by design; only the
    logo's gutter changes there. */
@media (max-width: 1359px) {
#header > .uk-position-left {padding-left: calc(max(0px, (100% - 1240px) / 2) + 10px);}
#header > .uk-position-right {right: calc(max(0px, (100% - 1240px) / 2) + 20px);}
  #header .grp-control-hd > .control-hd.cp-nav-toggle {padding: 0 0 0 0px;}
#header .grp-control-hd > .control-hd.cp-nav-toggle > .nav-mb > button {justify-content: flex-end;}
}

@media (min-width: 1360px) {
.logo-hd:not(.logo-ft) {padding-left: 0; margin-right: 0; margin-left: calc(max(0px, (100% - 1240px) / 2));}
#header > .uk-container {padding-left: 0; padding-right: 0;}
.nav-hd {padding-left: 0; margin-left: 0;}
}

/* BLG-C601: from 1360 the row has 18px of clearance (measured: About ends 1170,
   the control cluster starts 1188 at a 1360 viewport; 21px at 1366, 58px at
   1440). nowrap is a guard, not the fix: with 870px of labels in a 940px cell a
   fallback font a few percent wider would otherwise wrap About back under the
   controls. Scoped to the top-level list the runtime wraps in nav.nav-header. */
@media (min-width: 1360px) {
.nav-hd > .nav-header > ul {display: flex; flex-wrap: nowrap;}
.nav-hd > .nav-header > ul > li {flex: 0 0 auto;}
.cp-nav-toggle {display: none;}
.cp-hd-menu {display: none;}
}

@media (max-width: 960px) {
/* BLG-C605: the C489/C603 mobile logo indent is gone with the left trigger;
   at phone widths the logo now shares the content edge.
   BLG-C606 keeps 961-1359 on the 44px inset with the trigger on the left. */
.logo-hd h1.title, .logo-hd h1.title a {font-size: 36px; height: 55px;}
.grp-control-hd {padding-right: 0}
.order-item-1 {order: 2;}
.order-item-2 {order: 1;}
/* BLG-C049: the Trending + Featured row. These two divs carry margin: 0, so
   when the row wraps (narrow viewports, and the Blogger Layout editor) they sit
   flush with nothing between them. row-gap adds space ONLY between wrapped
   lines, so the live side-by-side layout at >=960px is untouched. Do NOT use
   `gap` here: measured, it pushes the row 20px past its container and forces
   the two items to wrap even on desktop. Selector matches exactly one of the
   16 [uk-grid] elements in the template. */
.post-box > [uk-grid] {row-gap: 20px;}
/* BLG-C051: Trending + Featured are ONE author-defined group, not two loose
   gadgets. Drawn as a dashed outline so the Layout editor shows that grouping
   instead of reading as an arbitrary barrier between unrelated sections.
   Editor-only on purpose -- a visible border on the live site would change the
   approved design, and the palette is frozen. `outline` rather than `border`
   so it encloses the group without altering a single pixel of layout.
   #999 is already this template's standard secondary/editor grey (10 uses) and
   is in the palette pin, so this adds no new colour. */
body#layout .post-box > [uk-grid] {outline: 1px dashed #999; outline-offset: 6px;}
.sidebar {width: 100%}
.post-ft h3.post-title, .post-ft h3.post-title a {font-size: 24px} /* BLG-C450: heading carries the clamp, so it takes the size too */
/* BLG-C444: split from the rule above so the hero can drop to 20px here while
   pure .post-ft contexts keep 24px. Order matters: equal specificity, so the
   dual-class hero takes this later rule. */
.post-entry-2 h3.post-title, .post-entry-2 h3.post-title a {font-size: 20px} /* BLG-C450: heading carries the clamp, so it takes the size too */
.post-entry-3 h3.post-title, .post-entry-15 h3.post-title, .post-entry-3 h3.post-title a, .post-entry-15 h3.post-title a {font-size: 18px} /* BLG-C450: heading carries the clamp, so it takes the size too */
.post-entry-5 .post-thumb {width: 47%; height: 125px}
.post-entry-13 > div > div:last-child {display: none}
.PopularPosts ul li .item-thumbnail {float: none; width: 100%; margin: 0 0 10px; height: 125px;}
.post-cate-video h2.title {margin: 0 0 10px}
.post-entry-11 > div > div:last-child {display: none}
.post-entry-12 .post-thumb {width: auto}
.logo-ft h2.title, .logo-ft h2.title a {font-size: 65px; height: 65px;}
.mog-404 {margin: 50px auto}
}

/* BLG-C421: C252 REVERTED. The operator never asked for the search ICON to move. C252 moved the .cp-hd-search cell out of the top-right cluster to the header centre, which put the icon under the navigation bar on live (see operator screenshot). The cell is back inside .grp-control-hd where C122 sizes it, so the C252 absolute-centre rules and the restated hit-target are deleted. What the operator DID ask for was the Ajax search PANEL moved down from the very top, which is the .cp-so padding change below, not an icon move. */
/* BLG-C192: C191's rules were written INSIDE the 640px query above, so they did
   nothing on a desktop -- and the operator's own screenshot proved it on a
   second blog. This is the correction, and the two mistakes it fixes are both
   worth stating because the verification had already "passed".

   MISTAKE ONE, the placement. The block sat between two rules of the
   max-width:640px media query, so every clamp and every cap it declared applied
   only to phones. Measured on the operator's second live blog at 1280px with
   the fix supposedly live: `--pe-thumb` computed to an EMPTY string on the
   offending card, the panel computed `overflow: visible` and `max-height: none`,
   and the title computed `line-clamp: none`. Nothing this block said was in
   effect. The 1280px check that reported "0 offenders, no regression" was
   worthless, because the rules it was checking were not applied at that width;
   the real numbers were 2 offenders, the worst hanging 23px below its image.

   MISTAKE TWO, the number. `--pe-thumb` for `.post-entry-5` was written as
   200px on the reasoning that it belonged to the 200px group. Its real rule
   floats a 120x120 square beside the text (the .post-entry-5 rule above), so a
   200px cap cannot bind against a 120px image and the text walks straight past
   it. The heights below are now each copied from the rule that declares them:
   120px for post-entry-5, 200px for 7/11/13/14, 150px for 9, 220px for 12.

   The block is OUTSIDE every media query now, and the only thing repeated
   inside one is the single line of heights that the 640px query itself changes
   -- which is where post-entry-5 becomes 125px and the 7/9/11/12/13/14 group
   becomes 125px as well. One variable per shape still carries the number, and
   the cap still reads that variable, so a shape cannot hold an image height
   without holding the cap that goes with it.

   The rule to carry forward when a card shape is added: if its thumbnail has a
   declared height AND its text panel sits BESIDE that thumbnail, it needs a
   `--pe-thumb` and a place in the cap list below. A stacked card (text under
   the image) cannot have this fault, and neither can an overlay card, whose
   title is already clamped by C190.

   BLG-C193: the operator's verdict on the two-line clamp was that the small
   cards show "two lines and some small part of the third", and asked for four
   lines. Measured on the operator's second live blog before changing anything:
   those cards are the side-by-side shapes, and the clamp was landing on exactly
   two lines -- post-entry-5 at 38px of title in a 66px panel beside a 120px
   image, post-entry-13 the same beside 200px, post-entry-12 at 58px beside
   220px. So the third line was not being shown at all; what the operator was
   reading as "part of the third line" is the panel's own remaining space below
   the two clamped lines.

   Four lines is 92.8px at the 23.2px line height these cards use (BLG-C195),
   and with the date line above it the panel measures inside every one of these
   shapes' images -- 120px is the tightest, and the four-line cases measure at
   or under it -- so the four-line clamp does not bring back the fault C192
   removed, and the `max-height: var(--pe-thumb)` cap is not what limits the
   text here.

   Two exceptions came out of the same measurement pass. Shape 12's title is
   24px (34.8px a line) and it is the only shape that shows the 15px-padded
   summary: four title lines plus a three-line summary wants about 251px
   against the 220px cap, so its title drops to three lines (worst case about
   214px) and its summary clamps to three as well. Shape 13 keeps four lines
   on desktop (row + 92.8 fits 200) but drops to three at 640px, where the
   stacked label+date row plus four lines measures 147px against the 125px cap
   (client 125 / scroll 143 before the change). Shapes 9, 11 and 14 are
   display:none at that width, and shape 5 keeps its four lines: row + margin +
   92.8 measures inside 125 on mobile and inside 120 on desktop.

   The cap still stands as the last line of defence for a headline long enough
   to need it. */
.post-entry-5 {--pe-thumb: 120px}
.post-entry-7, .post-entry-11, .post-entry-13, .post-entry-14 {--pe-thumb: 200px}
.post-entry-9 {--pe-thumb: 150px}
.post-entry-12 {--pe-thumb: 220px}
.post-entry-5 h3.post-title, .post-entry-9 h3.post-title, .post-entry-11 h3.post-title,
.post-entry-13 h3.post-title, .post-entry-14 h3.post-title {
display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 4;
line-clamp: 4; overflow: hidden; text-overflow: ellipsis}
.post-entry-12 h3.post-title {
display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3;
line-clamp: 3; overflow: hidden; text-overflow: ellipsis}
.post-entry-12 .post-summary {
display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3;
line-clamp: 3; overflow: hidden; text-overflow: ellipsis}
.post-entry-5 .post-panel, .post-entry-9 .post-panel, .post-entry-11 .post-panel,
.post-entry-12 .post-panel, .post-entry-13 .post-panel, .post-entry-14 .post-panel {
max-height: var(--pe-thumb); overflow: hidden}
@media (max-width: 640px) {
.post-entry-5, .post-entry-7, .post-entry-9, .post-entry-11, .post-entry-12, .post-entry-13, .post-entry-14 {--pe-thumb: 125px}
.post-entry-13 h3.post-title {-webkit-line-clamp: 3; line-clamp: 3}
/* BLG-C513: the operator's mobile screenshot of the main listing. The chip and
   the date were sharing one line, and the date is the thing that broke: with
   ~213px of panel and a 14px date, "October 15, 2026" wrapped after the comma
   and the card read as "chip, October 15," / "2026" / title. Three lines of
   noise above the one line a reader came for.

   The rule already existed, for two other shapes: line ~923 sets
   `post-entry-2` and `post-entry-3` label+date to `display: block`, and the news
   modal solved the same problem with `flex: 1 0 100%` on both. post-entry-12 is
   the MAIN listing and was simply never in either list. Adding it is the same
   three declarations the other two shapes already carry, not a new mechanism.

   `margin-right: 0` is not cosmetic tidying, it is one more line of the same
   bug: `.post-entry .post-panel span {margin-right: 10px}` applies to both, and
   on a block box with auto width that shrinks the row 10px, so the chip and the
   date would start 10px left of the title they sit above.

   Height, measured live at 430px rather than assumed: chip 22.4 + date 19.6 +
    title 3 x 23.2 + stacked gaps 2 + 2 + 4 = 119.6, against the 125px cap this
    block already sets on `.post-panel`. The third line fits with 5px spare, so
   the clamp stays at three and the ellipsis is still reachable -- a four-line
   title would measure 138.8 and be cut mid-line by the cap with no ellipsis,
   which is exactly the silent truncation BLG-C191 was written about.

   MOBILE ONLY, deliberately. Desktop puts the chip and the date on one line
   beside a 220px-tall thumbnail with room to spare, and the operator asked for
   this on a phone screenshot. Nothing above 640px moves. */
.post-entry-12 .post-ct-panel .post-label,
.post-entry-12 .post-ct-panel .post-date {display: block; margin: 0 0 2px; padding: 0;}
.post-entry-12 h3.post-title {margin: 4px 0 0; padding: 0;}
}


/* BLG-C138: the News modal. ONE control replaces the old Hot button and the old
   header search dropdown: the search field now lives INSIDE the modal, so a
   second search entry point in the header was redundant (and it was already
   hidden by BLG-C122, so removing the markup changes nothing a reader could see).

   COLOUR: no literal hex is added anywhere in this block. Every surface is a
   theme variable and the accent is the theme's own $(red.color), so the modal
   follows a rebrand instead of freezing the Broadcast mockup's navy and red
   into the skin. The mockup was dark because the site was in dark mode; with
   variables it is correct in BOTH modes, which is better than the mockup.

   The search field is deliberately NOT given a .gsc-* class. The theme's own
   search CSS (.gsc-search-box, .gsc-input) is aggressive enough to restyle a
   plain input element -- measured: a fresh input with !important still came back
   rounded with the theme's red button. A new class was the only way to own it.
   (A bare angle bracket cannot appear even inside this comment: it is raw XML
   between the skin's CDATA close and the skin's closing tag.) */
#news-modal{--nm-acc:$(red.color);--nm-on-acc:$(white.color)}
#news-modal .nm-live{display:inline-flex;align-items:center;gap:9px;font:700 12px 'Poppins',sans-serif;
  letter-spacing:.14em;text-transform:uppercase;color:var(--nm-acc);margin:0 0 16px}
/* BLG-C170: the dot element and its pulse are deleted from the markup, so the
   .nm-live i rule, the nm-pulse keyframes and the reduced-motion line for it are
   deleted here rather than left behind as rules nothing can match. The .nm-live
   row itself stays: it is what holds the new mark in the band. */
/* BLG-C170: the pulsing dot and the UIkit bolt are both gone from this band at the
   operator's request, and their rules go with them rather than being left as dead
   CSS, which means nm-pulse and the .nm-live i rules are deleted here as well. The
   new mark takes the dot's place in the flow. */
#news-modal .nm-live .nm-live-ico{display:inline-flex;align-items:center;justify-content:center;
  color:var(--nm-on-acc);width:46px;height:46px;flex:0 0 auto}
#news-modal .nm-live .nm-live-ico svg{width:46px;height:46px;display:block;fill:currentColor}
#news-modal .nm-sb-row{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:0 0 28px}
/* BLG-C165: the operator asked for the modal's top row to be ONE line -- the Hot
   news label with its blinking dot, the search field and the logo, side by side
   -- with the top band's own vertical space left exactly as it was. HOT NEWS was
   previously a line of its own above the search row, so the band spent 169px to
   show a 60px search bar. The band is now a centred flex row carrying .nm-live
   and .nm-sb-row as siblings, and min-height holds the measured 169px so the
   space the band occupied does not change; only what sits inside it does. The
   label's own 16px bottom margin goes with it, since a flex row spaces its
   children with gap instead. The search field's 680px cap is removed so it takes
   the width the single line frees up: measured on the live modal at 1422px the
   form goes 680px to 868px and the input 606px to 794px, an increase of 188px.
   Nothing is hidden at any width, and the phone layout keeps its existing stack
   (see the 560px block below, which now also turns the band itself into a
   column), so a 390px phone shows HOT NEWS, the logo and the search in that
   order with the field still spanning the band. */
#news-modal .nm-band-top{display:flex;align-items:center;gap:20px;min-height:169px}
#news-modal .nm-band-top .nm-live{margin-bottom:0;flex:0 0 auto}
#news-modal .nm-sb-row{flex:1 1 auto;margin-bottom:0}
#news-modal .nm-sb-row .nm-sb{max-width:none}
#news-modal .nm-sb{display:flex;margin:0;max-width:680px;flex:1 1 auto}
#news-modal .nm-sb input{flex:1;height:60px;border:0;background:var(--cp-surface);color:var(--cp-text);
  font:500 18px 'Poppins',sans-serif;padding:0 20px;outline:0}
#news-modal .nm-sb input::placeholder{color:color-mix(in srgb,var(--cp-text) 70%,var(--cp-card))}
#news-modal .nm-sb input:focus{box-shadow:inset 0 0 0 2px var(--nm-acc)}
#news-modal .nm-sb button{width:74px;height:60px;border:0;background:var(--nm-acc);color:var(--nm-on-acc);
  font-size:18px;display:flex;align-items:center;justify-content:center;cursor:pointer}
#news-modal .nm-h{display:flex;align-items:center;gap:12px;font:700 14px 'Poppins',sans-serif;letter-spacing:.1em;
text-transform:uppercase;color:var(--cp-text);margin:0 0 14px;padding-bottom:7px;border-bottom:2px solid var(--cp-soft-border)}
/* BLG-C224: the operator removed the gradient bar that sat with every section
   name. It was the :after pseudo-element below, drawn in --nm-acc, which is
   $(red.color) — so "Breaking now", "Most viewed", "Trending" and "Browse by
   label" each wore a red line. The border-bottom above is NOT that line and
   stays: it is a neutral divider at 32% of the band text colour, and it is
   what separates the heading from the cards underneath it. */
/* BLG-C239: the Ajax search, retouched onto the template's own idiom -- its
   Poppins stack, its small radii, its red Blogger Variable, and its badge
   shape. The first version was a correct panel that looked like it came from
   somewhere else, which for a theme sold on its appearance is the defect.
   Still no new colour: every value here is a --cp-* token, $(red.color) as
   the template itself writes it, or a palette-baselined rgba. */
/* BLG-C421: the operator asked for the Ajax search panel to sit lower than the very top. 6vh read as glued to the top under the navigation, so the overlay now opens at 22vh, top-middle. Icon untouched by this rule. */
.cp-so{position:fixed;inset:0;z-index:2147483646;background:rgba(0,0,0,.7);
  display:none;align-items:flex-start;justify-content:center;padding:22vh 14px 14px}
.cp-so.is-open{display:flex}
.cp-so-panel{width:100%;max-width:660px;max-height:84vh;display:flex;flex-direction:column;
  background:var(--cp-card);border:1px solid var(--cp-soft-border);border-radius:10px;
  box-shadow:0 18px 40px rgba(0,0,0,.18);overflow:hidden}

/* the bar: field, then the button that searches, then the button that leaves */
.cp-so-head{display:flex;align-items:center;gap:8px;padding:10px 10px 10px 14px;
  border-bottom:1px solid var(--cp-soft-border)}
.cp-so-input{flex:1 1 auto;min-width:0;border:0;background:transparent;
  padding:8px 2px;font:400 15px/1.3 'Poppins',sans-serif;color:var(--cp-text)}
/* BLG-C591: the palette's only grey is 2.31:1 on the surface; a 70% text mix
   measures 5.56:1 on card and 5.01:1 on surface (dark 6.00/6.83). A placeholder
   is not a text node, so the contrast gate cannot see it -- record the ratios
   here rather than claiming gate coverage. */
.cp-so-input::placeholder{color:color-mix(in srgb,var(--cp-text) 70%,var(--cp-card))}
.cp-so-input:focus{outline:none}
.cp-so-go,.cp-so-close{border:0;border-radius:8px;cursor:pointer;flex:0 0 auto;
  display:inline-flex;align-items:center;justify-content:center;
  font:600 13px/1 'Poppins',sans-serif;height:38px;padding:0 14px}
/* BLG-C591: the buttons used --cp-card as ink. On the fixed brand red that is
   white in light (4.54:1) but the dark card in dark (2.88:1). White is the
   brand's on-red colour in both modes and measures 4.54:1. */
.cp-so-go{background:$(red.color);color:$(white.color)}
.cp-so-go:hover{filter:brightness(.92)}
/* red, because a close control has to be findable by someone who does not
   already know it is there */
.cp-so-close{background:$(red.color);color:$(white.color);width:38px;padding:0;
  font-size:17px;line-height:1}
.cp-so-close:hover{filter:brightness(.92)}
.cp-so-head:focus-within{box-shadow:inset 0 -2px 0 $(red.color)}

.cp-so-status{padding:8px 14px;font:400 11px/1.4 'Poppins',sans-serif;
  letter-spacing:.04em;text-transform:uppercase;color:var(--cp-text);
  border-bottom:1px solid var(--cp-soft-border)}
.cp-so-results{overflow:auto;padding:6px;margin:0;list-style:none;
  overscroll-behavior:contain}
.cp-so-results li{margin:0}
/* BLG-C243: a band with nothing in it is a hole in the panel, not information.
   Both of these are empty at rest -- the status line before the first query,
   the list between queries -- and both keep their padding when emptied, so an
   empty status drew a blank row with a rule under it and the empty list drew a
   second one below that. The operator saw two white rows over an empty panel
   and, in the modal, a white pill lying across the logo. `:empty` retires each
   the moment its last child goes, which no code path can forget to do the way
   a class toggle can be skipped. */
.cp-so-status:empty{display:none}
.cp-so-results:empty{display:none}

/* a result: thumbnail, then the words. 60px from a 120px source. */
.cp-so-hit{display:flex;align-items:center;gap:12px;padding:9px 10px;
  border-radius:8px;text-decoration:none;color:inherit}
.cp-so-hit:hover,.cp-so-hit.is-active{background:var(--cp-surface)}
.cp-so-thumb{flex:0 0 auto;width:60px;height:60px;border-radius:6px;object-fit:cover;
  background:var(--cp-surface);border:1px solid var(--cp-soft-border)}
/* BLG-C576: a row with no picture is not a grey confession, it is the card
   panel's small cousin -- the same accent gradient mixed from the theme's own
   green/red Variables, and the letter tinted the way the panel text is, so an
   imageless post reads the same in search as it does on its card. The accent
   is the post's own label run through the sweep's hash (data-accent, set by
   cpSearchPaint); --cp-card/--cp-text carry the dark switch this surface
   already runs on. */
.cp-so-thumb-fallback{flex:0 0 auto;width:60px;height:60px;border-radius:6px;
  --cat-a:$(green.color);--cat-b:$(red.color);--cat-bg:var(--cp-card);--cat-fg:var(--cp-text);
  background-image:linear-gradient(135deg,
    color-mix(in srgb,var(--cat-a) 24%,var(--cat-bg)) 0%,
    color-mix(in srgb,var(--cat-b) 10%,var(--cat-bg)) 100%);
  border:1px solid var(--cp-soft-border);
  display:flex;align-items:center;justify-content:center;
  font:700 20px/1 'Poppins',sans-serif;
  color:color-mix(in srgb,var(--cat-a) 62%,var(--cat-fg))}
.cp-so-thumb-fallback[data-accent="b"]{--cat-a:$(red.color);--cat-b:$(green.color)}
.cp-so-body{min-width:0;flex:1 1 auto}
.cp-so-title{display:block;font:600 14px/1.35 'Poppins',sans-serif;
  color:var(--cp-text);overflow:hidden;text-overflow:ellipsis;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.cp-so-meta{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-top:5px}
.cp-so-date{font:400 11px/1.3 'Poppins',sans-serif;color:var(--cp-text)}
/* the theme's badge shape: small, rounded, quiet ink */
.cp-so-label{font:500 10px/1 'Poppins',sans-serif;letter-spacing:.02em;
  padding:4px 7px;border-radius:4px;background:var(--cp-surface);
  border:1px solid var(--cp-soft-border);color:var(--cp-text);
  white-space:nowrap;max-width:150px;overflow:hidden;text-overflow:ellipsis}
/* One line of text, so it is padded like one. At 26px this state read as a
   second, emptier band under the status line rather than as the message. */
.cp-so-empty{padding:18px 14px;text-align:center;
  font:400 13px/1.5 'Poppins',sans-serif;color:var(--cp-text)}

/* The modal search bar is NOT restyled, resized or wrapped. The operator was
   explicit: keep the bar exactly as it ships and only add the dropdown.
   So nothing here touches .nm-sb input. The list is absolutely positioned and
   its containing block is the FORM, which is the whole reason it is exactly as
   wide as the search control. `left:0; right:0` resolves against the nearest
   positioned ancestor, and while the list was a sibling of the form that
   ancestor was `.nm-sb-row` -- which also holds `.nm-logo` -- so the dropdown
   measured **1134px against a 929px control**: 205px too wide, which is the
   logo (185) plus the row gap (20), spilling past the control and ending under
   the brand. Measured at 1280px. `position:relative` on `.nm-sb` changes no box
   size, no padding and no border.
   BLG-C244: the list is now parented INSIDE the form, where it is out of flow
   and lays out nothing. That is deliberately not the C239 shape: C237's draft
   WRAPPED the form in a new div, which reflowed a flex row and was discarded.
   Appending an out-of-flow child adds no flex item, so the bar is untouched. */
#news-modal .nm-sb{position:relative}
/* BLG-C243: this selector was declared TWICE, the second one left behind when
   C239 took the wrapper div out, and the real value was only knowable by
   reading both: the first brought the width and the offset, the second the
   scroll cap and the 12px radius. `.nm-sb-wrap` in the same breath names a
   class C239 deleted, so it positioned nothing. Merged into the one rule that
   is actually in force.
   BLG-C244: `max-width:680px` is gone with the row. It capped the dropdown
   while the control was fluid and measured 929px, so keeping it would have made
   the dropdown 680 -- narrower than the field, which is the same defect pointed
   the other way. The width is now whatever the control is, at every viewport. */
#news-modal .cp-so-results{position:absolute;z-index:5;top:100%;left:0;right:0;
  margin-top:6px;max-height:52vh;
  background:var(--cp-card);border:1px solid var(--cp-soft-border);
  border-radius:12px;box-shadow:0 14px 30px rgba(0,0,0,.15);padding:6px;
  text-align:left;overscroll-behavior:contain}
#news-modal .cp-so-status{display:none}
@media (prefers-reduced-motion:reduce){.cp-so{transition:none}}
#news-modal .nm-h-breaking{margin-top:0}
/* BLG-C233 / B16: a breaking strip with no entries. The band is a fixed
   grey band with a heading inside it, so with nothing to show it has to leave
   entirely -- there is no useful thing to put there instead. */
.bk-news.bk-empty{display:none}
#news-modal .nm-h-labels{margin-top:30px}
#news-modal .nm-two{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:28px}
#news-modal .nm-col{min-width:0}
#news-modal .nm-tags{display:block}
#news-modal .nm-chips{display:flex;flex-wrap:wrap;gap:9px;padding:2px 0 0}
/* The logo is not a gadget: the owner asked for it and then, told a gadget would
   mean a new section and new counts, chose to mirror the header logo instead. It
   is filled from the header's own image by script, so it follows whatever the
   owner uploads and can never drift from it. Empty means no header logo, and the
   slot collapses rather than leaving a gap. */
#news-modal .nm-logo{flex:0 0 auto;display:flex;align-items:center;min-width:0}
#news-modal .nm-logo img{display:block;max-height:46px;max-width:190px;width:auto;height:auto}
/* The close control ships as a white disc with a hardcoded black stroke, so in
   dark mode the modal's own corner is a white blob. The stroke is SVG geometry,
   which CSS can reach even though the markup hardcodes the colour, and the disc
   takes the modal's own surface so the X reads in both modes. */
/* BLG-C149: the close control is a WHITE DISC and it now sits on the gradient.
   It was given that disc back in C139, correctly, because at the time it lived
   on the white panel and a white disc with a dark X was the fix for UIkit's
   hardcoded black cross in dark mode. The band moved underneath it and the disc
   stopped making sense: measured, it is #F3F3F3 with a #012E3F cross in light
   mode and #112A37 with a pale cross in dark, and the gradient under it is a
   dark blue in BOTH modes, so in both it read as a light box dropped onto the
   band's top corner. The disc goes and the cross takes --nm-on-acc, the token
   that exists to be ink on a filled surface, which is white in both modes
   because the band is dark in both. Hover is a 18% white wash rather than a
   colour change, so the affordance survives without needing a second ink, and
   it is a color-mix of the token rather than a literal so the palette freeze is
   untouched. The token had to MOVE for this to work: --nm-acc and --nm-on-acc
   were declared on .nm, and the close control is a sibling of .uk-modal-dialog
   rather than a descendant of .nm, so var(--nm-on-acc) did not resolve on it at
   all and the computed colour was falling back to --cp-text. Declaring the pair
   on #news-modal instead puts them in scope for the panel and for the control,
   since everything that used them is inside the modal. */
#news-modal .uk-modal-close-full{color:var(--nm-on-acc);background:transparent}
#news-modal .uk-modal-close-full:hover{color:var(--nm-on-acc);
  background:color-mix(in srgb, var(--nm-on-acc) 18%, transparent)}
#news-modal .uk-modal-close-full line{stroke:currentColor}
/* BLG-C151: the "grey" the operator reported on the close control was never the
   control. Measured: the button computes to `background: transparent`, no
   background-image, no box-shadow, no border, and a white cross on both lines,
   so C149 had done its job. The grey was the modal's own SCROLLBAR, a 30px
   light track sitting immediately to the right of the button, at the top-right
   corner where the operator was looking. It read as part of the control because
   it touches it, and `elementFromPoint` across that corner returned the button
   at x=1235 and nothing at all at x=1265, which is outside the document box and
   therefore inside the scrollbar gutter. The fix styles the scrollbar rather
   than the button: the track goes transparent so the modal's own background
   shows through, and the thumb takes a `color-mix` of `--cp-muted` so it is
   derived from the theme and reads in both modes rather than being the
   browser's light default, which in dark mode was a pale stripe down the side of
   a dark panel. `scrollbar-width`/`scrollbar-color` are the standard properties
   and cover Firefox; the `::-webkit-scrollbar` rules are the Chromium and Safari
   path and the two coexist, which is why both are written. The width drops from
   the default to 10px, measured, and no colour literal is introduced. */
#news-modal{scrollbar-width:thin;
  scrollbar-color:color-mix(in srgb, var(--cp-muted) 55%, transparent) transparent}
#news-modal::-webkit-scrollbar{width:10px}
#news-modal::-webkit-scrollbar-track{background:transparent}
#news-modal::-webkit-scrollbar-thumb{background:color-mix(in srgb, var(--cp-muted) 55%, transparent);
  border-radius:5px}
/* BLG-C151: the operator asked for the Breaking area's background to go from
   white to #F8F8FF. That value is not a new colour to this file: it is the
   light-mode value of the theme's own `.row-grey`, the breaking-news ticker
   class, so the palette gate's fingerprint still reads the same 52 colours and
   the operator is getting the exact tint the homepage ticker uses rather than a
   near miss. It is applied to a WRAPPER rather than to the heading and the
   section separately, because those two are siblings with margins between them
   and painting each one would leave two white stripes inside an off-white strip.
   The wrapper is the fourth `.nm-band`, which also means the mobile rule that
   hides the Breaking content on a phone has to hide this too, or the wrapper
   would survive as an empty 44px tinted bar between the two gradient bands and
   undo C149's seam fix. Dark mode is left as the panel colour on purpose: the
   request was to change a WHITE background, and in dark mode there is no white
   to change, so `transparent` keeps whatever the panel already is. */
#news-modal .nm-band-break{background:#F8F8FF}
html.dark #news-modal .nm-band-break{background:transparent}
/* BLG-C197: the modal's Layout-editor arrangement, which C157 put here and C196
   widened to four columns, now lives in template-skin beside the other editor
   rules, and the reasoning travelled with it. It left this island because the
   operator reported, after C196, that the four gadgets still show full width and
   stacked in the editor. One grid, the band wrappers flattened, the search strip
   and the section headings hidden: all of it is in the C197 block in the editor
   island, and there is no second copy of it here. */
/* BLG-C145: the operator asked for the modal's three regions to carry the SAME
   background bands the homepage already uses, and for the C143 shading to be
   taken back out again. That is the right trade and the reason is that C143 was
   faking the one thing these bands do for real. C143 added drop shadows, an
   inset field shade and a panel wash to separate cards from the page, because
   in light mode --cp-bg and --cp-card are both #ffffff and a 1px border was all
   there was. Shading a flat surface is a simulation of depth; giving each region
   the background it actually has on the homepage is depth. So the two are not
   combined, and the shadows are gone: a card sitting on the ticker's own band
   needs no lift, and lifting it as well is what made the last attempt busy.
   The backgrounds are the theme's OWN utility classes, applied to wrapper divs:
   bg-grd is the class on the homepage header and footer, and row-grey is the
   class on the breaking-news ticker strip. (BLG-C147 later moved the middle band
   off row-grey onto bg-grd as well, for the contrast reason recorded there; the
   reasoning here about reusing the class rather than copying a value still
   stands, and row-grey is still what the homepage ticker itself uses.)
   Reusing the class rather than copying
   the gradient means a rebrand customer who recolours those two elements gets
   the modal to match with no extra work, which is the entire point of shipping a
   template rather than a screenshot, and it is why this change adds no colour
   literal at all: the palette freeze reads the same 52 colours as before.
   Each wrapper is a div rather than a modifier on an existing element because
   the bands are full-bleed sections of the panel that need their own vertical
   padding, and because the two label elements are siblings of the heading with
   no common parent to paint. Breaking Now is deliberately NOT wrapped: the
   operator asked for no change there, and it now reads as the plain white strip
   between two coloured bands, which is what separates it. */
#news-modal .nm-band{padding:22px 0;margin:0}
#news-modal .nm-band-top{margin:0 0 26px}
#news-modal .nm-band-mid{margin:0 0 0;padding:26px 0 30px}
#news-modal .nm-band-bottom{margin:0}
/* BLG-C146: the operator then asked for the bands to run the FULL width of the
   page, left edge to right edge, the way the homepage header, ticker and footer
   do, rather than stopping at the content column. The first version measured
   1200px inside a 1280px page, because the panel sits inside .uk-container,
   which is max-width 1200px with 20px of margin AND 20px of padding, so the
   content column is inset 40px per side at desktop and 20px on a phone.
   Bleeding out means escaping both of those, and the two obvious ways are wrong
   in ways only measuring catches. A fixed -40px is correct at 1280 and
   OVERFLOWS at 390, where the margin collapses to 0: the band came out 430px
   wide in a 390px viewport with its left edge at -20. So the bleed is expressed
   as calc(50% - 50vw), which is the distance from the content column to the
   viewport edge and is therefore correct at every width with no breakpoint.
   The padding then has to put the CONTENT back where it was, or the band runs
   full width while its search field and cards sit 20px left of the un-banded
   Breaking row, which reads as a mistake. That padding is the container's own
   inset, and the container's max-width is 1200px while its margin is 20px, so
   the inset is max(0px, (100vw - 1240px) / 2) + 20px: the margin term is the
   auto-margin a 1200px column takes in a wider viewport, clamped at zero once
   the viewport is narrower than the column, and the flat 20px is the padding.
   Verified by measurement at both widths rather than by reading it: at 1280 the
   bands compute to left 0, width 1280, and their content at 40px, matching the
   Breaking row exactly; at 390 they compute to left 0, width 390, content 20px,
   matching the container, with documentElement.scrollWidth equal to
   clientWidth and the modal's own scrollWidth equal to its clientWidth at both,
    so the bleed introduces no horizontal scrollbar. A bleed that only works at
    one width is the failure mode here, which is why both were measured.
    BLG-C148 SUPERSEDES the calc(50% - 50vw) that the paragraph above describes,
    and the reason is a bug that only appeared once the vertical padding came off.
    50vw measures the VIEWPORT, but the bands need to reach the edges of the
    modal's scroll container, which is the viewport MINUS the vertical scrollbar.
    While the dialog's 5% vertical padding was still there the modal was not
    scrollable and the two happened to be the same width, so the rule looked
    right. Removing that padding made the content tall enough to scroll, a
    scrollbar appeared, and the bands overshot: measured, modal scrollWidth 1258
    against clientWidth 1250, which is a horizontal scrollbar on a full-screen
    modal, caused by a decorative background. 100vw would have been worse, for
    the same reason, and choosing 50vw over 100vw in C146 was reasoning about
    symmetry rather than about the scrollbar, which was the wrong axis.
    The bleed is now expressed with NO viewport unit at all. The container's
    constraints are lifted inside this modal, so .nm IS the scroll container's
    content width, and the bands simply span it. The inset the container used to
    impose moves onto .nm as padding and onto the bands as an equal negative
    margin, so the two cancel exactly and the band's outer edge lands on .nm's
    border-box edge whatever the inset computes to. That is why the viewport
    units survive only inside --nm-inset, where they position CONTENT, and a
    pixel of error there is invisible, rather than deciding a background edge,
    where it is a scrollbar. */
#news-modal{--nm-inset:calc(max(0px, (100vw - 1240px) / 2) + 20px)}
#news-modal .uk-container{max-width:none;margin-left:0;margin-right:0;padding-left:0;padding-right:0}
#news-modal .nm{padding-left:var(--nm-inset);padding-right:var(--nm-inset)}
#news-modal .nm-band{margin-left:calc(-1 * var(--nm-inset));margin-right:calc(-1 * var(--nm-inset));
  padding-top:22px;padding-bottom:22px;
  padding-left:var(--nm-inset);padding-right:var(--nm-inset)}
#news-modal .nm-band-top{margin-bottom:26px}
#news-modal .nm-band-mid{margin-top:28px;padding-top:26px;padding-bottom:30px}
/* BLG-C180: the breathing space after Browse by label. Measured on the live
   upload: the top band is 169px with its content centred, 55 to 62px of air
   above and below the search row, while the bottom band's chips ended 32px
   from the modal edge (22px of band padding plus 10px of chip margin) and the
   operator asked for the bottom to breathe like the top. The padding goes to
   46px, which puts the gap at about 56px, inside the top's measured range,
   at every viewport width and in both modes -- it is a longhand set after
   every band shorthand above it, so nothing later in the sheet resets it.
   The extra space is INSIDE the red gradient, the same place the top band
   keeps its own air, so both ends of the modal still read as one coloured
   block rather than as padding pasted on afterwards. */
#news-modal .nm-band-bottom{padding-bottom:46px}
/* BLG-C148, the white strips: the operator reported that the bands went full
   width but the top and bottom of the modal stayed white. They were not bands
   failing to bleed, they were the dialog's own padding: UIkit ships
   .uk-modal-full .uk-modal-dialog with padding 5% 0, and a percentage padding
   resolves against the WIDTH, so it measured 62.5px above the top band and
   62.5px below the bottom one at 1280, and 19.5px at 390. The dialog's
   background was showing through it, which is white in light mode. Zeroing the
   vertical padding puts the first band against the top edge of the modal and
   the last against the bottom. The selector needs the id because UIkit's own
   rule is .uk-modal-full .uk-modal-dialog, two classes, and a bare
   .uk-modal-dialog would lose to it. The horizontal padding of the dialog is
   left alone; it is already 0 and the gutter is handled above.
   BLG-C148, the missing space: the last Breaking card sat flush against the top
   edge of the Most viewed band with a 0px gap measured, because .nm-break
   carries no bottom margin and the band had no top margin, so the white strip
   and the gradient met with nothing between them. That reads as a mistake
   rather than as a division, which is the opposite of what the bands are for.
   The band takes a 28px top margin, which puts the space OUTSIDE the gradient
   on the white panel, where it separates the two areas, rather than inside it
   where it would just be padding on the band's own colour. */
#news-modal .uk-modal-dialog{padding-top:0;padding-bottom:0}
/* A coloured band needs a foreground that reads ON it, in both modes, and the
   modal already owns exactly that token: --nm-on-acc is the theme's white, set
   once on .nm and never overridden, because it is the colour meant to sit on a
    filled surface. The two headings and the LIVE label on the gradient bands take
    it. Their rule tint is --nm-acc, which stays red on both bands and on both
    modes, so nothing here is mode-specific and check-modes gains no one-sided
    entry to explain. The bottom band's underline is a mix of that white rather
    than a literal, because --cp-soft-border is a dark blue and would vanish.
    BLG-C147: the middle band took bg-grd as well, so all three are the homepage
    gradient and each one divides the modal visibly. That makes the two headings
    inside it, Most viewed and Trending, sit on the gradient too, and they had
    been taking --cp-text, which in LIGHT mode is a dark navy. Dark navy on the
    light-mode gradient, #005271 to #058bb1, is unreadable, and the light mode is
    the one that had not been checked for this because the middle band used to be
    a near-white tint where dark text was correct. So the middle band's headings
    join the bottom band's on --nm-on-acc, and their underline joins it too. The
    CARDS inside the band are not affected: each is its own --cp-card surface
    with --cp-text on it, which is correct in both modes and is why the band can
    be dark without the card text going with it. */
#news-modal .nm-band-top .nm-live,
#news-modal .nm-band-bottom .nm-h,
#news-modal .nm-band-mid .nm-h{color:var(--nm-on-acc)}
#news-modal .nm-band-bottom .nm-h,
#news-modal .nm-band-mid .nm-h{border-bottom-color:color-mix(in srgb, var(--nm-on-acc) 32%, transparent)}
#news-modal .nm-chips a{display:inline-block;background:var(--cp-surface);border:1px solid var(--cp-soft-border);
  color:var(--cp-text);font:500 13px 'Poppins',sans-serif;padding:9px 13px;border-radius:6px;text-decoration:none}
#news-modal .nm-chips a:hover{border-color:var(--nm-acc);color:var(--nm-acc)}
/* BLG-C229: the empty chip that completes the FIRST row of Browse by label, per
   the operator. Only the first row is padded, and only when the row has room:
   a label list that already fills two rows is left exactly as it is.

   BLG-C178: the width is no longer a constant. The script writes an inline
   width on each placeholder, sampled from the real chips, so the padded gap
   reads as labels of different lengths instead of a row of clones; with no
   labels at all it falls back to a small pattern of chip widths, and 96px
   stays as this rule's default. pointer-events:none and aria-hidden keep a
   placeholder out of the tab order and out of the accessibility tree.

   BLG-C179: the placeholder joins the skeleton look -- the same sk-pulse loop
   as the Breaking slots and the loading stacks -- so a waiting chip reads as
   processing too; reduced motion stops it (covered with .sk at the end of the
   skin) and the outlined chip above is what remains.

   Both modes: it borrows the chip's own border token and adds no fill of its
   own, so it reads as an outlined slot in either theme. */
#news-modal .nm-chips{--nm-chip-empty:96px}
#news-modal .nm-chips a.nm-chip-empty{display:inline-block;width:var(--nm-chip-empty);
  border-style:dashed;border-color:var(--cp-soft-border);background:transparent;
  color:transparent;pointer-events:none;animation:sk-pulse 1.15s ease-in-out infinite}
#news-modal .nm-post .widget-content{display:block}
/* BLG-C144: on a phone the owner wants the logo on top and the search bar under
   it, both centred, and no Breaking row at all. The desktop row is a flex line
   with the search and the logo at opposite ends, so a single media query
   re-stacks it, drops the 680px cap that would otherwise leave the form short
   of the edges, and reorders with flex order rather than moving the markup: the
   logo already precedes the form in the HTML, so only the visual order needs
   stating and the source order stays searchable-first. The Breaking heading and
   its grid are hidden together so the 4-across row cannot appear under a label
   with no cards. Both lists below stay. */
@media (max-width:560px){
  /* BLG-C165: the band itself stacks with its row on a phone, and the min-height
     that holds the desktop band's 169px is dropped, because at this width the
     three items are taller than one line and the space has to come from the
     content rather than from a fixed height. */
  #news-modal .nm-band-top{flex-direction:column;min-height:0;gap:14px}
  #news-modal .nm-sb-row{width:100%}
  #news-modal .nm-sb-row{flex-direction:column;align-items:center;justify-content:center;gap:14px}
  #news-modal .nm-logo{order:1;max-width:100%}
  #news-modal .nm-logo img{max-width:min(190px,100%)}
  #news-modal .nm-sb{order:2;width:100%;max-width:none;flex:1 1 auto}
  /* BLG-C151: the wrapper joins the hide list. C151 gave the Breaking region a
     wrapper so its tint would be one strip, and a wrapper that outlives its
     contents would render as an empty tinted bar between the two gradient bands
     on a phone, undoing the seam removal two rules above it. */
  #news-modal .nm-band-break,
  #news-modal .nm-h-breaking,#news-modal .nm-break{display:none}
}
/* The two HTML post-blocks (Breaking, Trending) render the THEME's own card
   markup, and Blogger wraps it in .widget-content. The grid therefore has to sit
   on .widget-content itself -- making it a grid AND letting the inner markup
   make a grid nests one grid inside one cell, which is how "Most viewed" ended
   up 51px wide: the outer grid made a 185px cell, and the inner grid split that
   into three 51px columns. One level of grid, on the element that owns the
   children, is the fix. */
/* BLG-C229: four FIXED slots, not auto-fit. This line is the third state of the
   Breaking row and the reasoning is worth keeping, because the two earlier
   states were both deliberate fixes to the same complaint.
   C149: a fixed four-column row with two posts left 568px of a 1185px row empty,
   and it read as a void. Fix: auto-fit, which collapsed the empty tracks.
   That removed the void and produced the opposite complaint: two cards stretched
   across the whole row, each one enormous.
   Now: the columns are fixed again, and the shortfall is padded with explicit
   empty slots by the feed builder, so the row keeps the width it was designed
   for and the empty positions are visibly empty on purpose. Same slot count, no
   void, no billboards. The 240px floor is kept inside minmax so a narrow
   viewport still collapses rather than overflowing. */
#news-modal .nm-break .widget-content{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
#news-modal .nm-col .widget-content{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
/* The Most-viewed block's wrapper no longer needs excluding: BLG-C139 made it an
   HTML widget like the other two, so the one-level-of-grid rule above covers all
   three and the PopularPosts exception is deleted with it. */
/* BLG-C138: the three lists in this modal are ONE design, so they share ONE
   card. The theme's post-entry-NN shortcode variants each carry their own card
   geometry -- one pins the panel over the cover, another wraps every card in
   its own half-width grid cell, a third adds a star row -- and Blogger's
   PopularPosts emitted its own markup again. Rather than undo all of that with
   CSS, the builder is told when it runs inside the modal (see the inNewsModal
   branch) and emits a flat card. BLG-C139 then removed the last PopularPosts
   from this modal as well, so all three lists are the same element type and
   every rule below targets .post-item with no per-widget exception. */
#news-modal .nm-post .post-item{display:flex;flex-direction:column;height:100%;
  background:var(--cp-card);border:1px solid var(--cp-soft-border);border-radius:10px;overflow:hidden}
#news-modal .nm-post .post-thumb{flex:0 0 auto;height:150px;min-height:0;display:block;overflow:hidden;
  background-size:cover;background-position:center}
/* BLG-C149: the Breaking row is a FIXED four-column grid, and the operator found
   that it looks too white. It is not the background, it is that the grid makes
   four columns whether or not four posts exist: measured on the live blog the
   row resolved to four 284px tracks while the label held TWO posts, so 568px of
   the 1185px row was empty and the area read as a half-empty void rather than as
   a section. auto-fit collapses the tracks that have no item in them, so two
   posts fill the row and four posts still give four across, and a label that
   grows to five or six does the obvious thing. The floor is 240px because a
   track narrower than that cannot hold a thumbnail, and min(240px, 100%) inside
   it so the floor cannot itself overflow a viewport narrower than 240px.
   The thumbnail then has to stop being a fixed height, because a card that is
   now 585px wide under a 150px-tall image is a four-to-one letterbox, which
   replaces the void with a different-looking defect. aspect-ratio lets the
   slot scale with the card, so one rule serves both the 284px four-across case
   and the wider two-across case. Scoped to the Breaking row on purpose; the two
   three-across lists below it are unchanged and keep the 150px slot, so the
   modal still has one card proportion per row rather than three.

   BLG-C181: the operator's own featured images use Blogger's CUSTOM SIZE,
   which is square, and at 16/9 the square card cropped them hard -- measured in
   the harness against the shipped rules at the live modal width (1184px): the
   Breaking thumb is 282x159, a 1.78 box, so cover kept only 56% of a square
   image's height and cut 44% of it away, most of it off the top and bottom of
   the subject, which is what the operator reported. The two three-across lists
   were never the complaint, and they measure 180x150, a 1.20 box that keeps 83%
   -- so the difference was the ratio, not the fit. C181 set the box to 1/1.

   BLG-C182: the operator then found the opposite fault in C181's own fix: a
   square image box on a 284px card makes the CARD taller than wide (measured
   279x315 at the 277px four-across card), so the row stopped reading as a row.
   Every candidate ratio was measured in the same harness before choosing, at
   both grid shapes, with a square source, and the trade is exact -- a box
   shorter than square crops the square image by exactly what it gives back in
   card height:
     ratio  thumb(4-across) card      square shown
     1/1    277x277       279x315     100%   card taller than wide
     7/6    277x237       279x275      86%   card wider than tall
     5/4    277x221       279x259      80%
     4/3    277x207       279x245      75%
     3/2    277x184       279x222      67%
     16/9   277x156       279x194      56%   the C179 crop the operator came
                                              here to remove
   The operator chose 7/6: it is the shortest box that still shows most of a
   square image while keeping the card wider than tall, so 14% of the image is
   cut instead of 44%, and the row reads as a row again. The fit is still NOT
   touched by any of this: the shared rule above keeps background-size:cover and
   background-position:center and overflow:hidden, so the crop rule every modal
   card uses is unchanged and only the shape of the box it applies to moves. The
   two three-across lists keep the 150px slot they have always had. The rank
   wedge and numeral need no change either: both are cqw-sized off the thumb's
   own inline-size container, and cqw tracks width, which this change does not
   move. */
#news-modal .nm-break .post-thumb{height:auto;aspect-ratio:7/6}
/* BLG-C153: the operator asked for the Breaking cards to be made like the
   sidebar's Most Like card, and to adopt its numbering, style, label and date
   formatting. What that card actually is was measured before anything was
   written, because the request implies it has a label and a date and it does
   not: the sidebar widget is `PopularPosts1`, and its rendered markup is
   `.item-thumbnail-only` holding `.item-thumbnail` and `.item-title` and nothing
   else, with `hasLabel` and `hasDate` both false. The numbering is real and is
   pure CSS there: a red corner triangle drawn with two borders on `::before` and
   a numeral injected by `::after`, with the digits written out one rule per
   position for 1 to 6. So the numbering and the style are portable and are
   adopted here; the label and the date are not in that card to be copied, and
   the Breaking cards keep the ones they already carry, which are the red pill
   and the formatted date this modal established in C138 and C140. If the intent
   was to REMOVE them that is one line either way, but removing information the
   request did not clearly ask to remove is the wrong default.
   The numeral is a CSS COUNTER rather than six `nth-child` rules, and that is
   the part worth keeping: C149 made this row `auto-fit`, so the card count is
   whatever the label happens to hold -- two today, and four or more if the
   operator adds posts. `counter-reset` on the grid and `counter-increment` on
   each card number them by document order at any count, where the sidebar's
   hand-written `nth-child` list would stop at 6 and silently leave a seventh
   card unnumbered.
   The badge is sized in CONTAINER QUERY UNITS against the thumbnail rather than
   in pixels, because the thumbnail's size is not fixed and the sidebar's fixed
   38px numeral was tuned for a 200px-tall image. `container-type: inline-size`
   on the thumbnail makes `cqw` resolve against the card's own width, so one
   rule set holds at any card width. `inline-size` containment is the safe axis
   to contain here because the block size is already pinned by the
   `aspect-ratio` set two rules above, so there is nothing for the containment
   to fight.

   BLG-C179 recalculates the badge for the card that actually renders. C153
   measured it against auto-fit's 585px two-card row, but C229 fixed the grid
   at four tracks, so every card is about 284px at every post count and the
   badge the operator saw was the small extreme of that old range: 8.5cqw is
   24px at 284, and it sat 1cqw (under 3px) off the corner. The numeral is now
   11.5cqw (33px at 284), inset 4.4cqw from the left and 3.2cqw from the
   bottom, and the triangle grows to 14cqw tall by 20cqw wide so the digits
   sit ON the wedge instead of floating above its tip, which is what makes the
   rank read at a glance instead of hiding in the corner.
   The badge sits above the image and the label and date stay below it, so
   nothing is displaced: the triangle is bottom-left, the numeral inset from it,
   and the card's own meta lines are untouched underneath. `z-index` 2 and 3 put
   the badge over the cover rather than under it. Colours are the modal's own
   `--nm-acc` and `--nm-on-acc`, the same accent pair the LIVE label and the
   bands use, rather than the sidebar's `$(red.color)` and `$(white.color)`
   literals, so a rebrand recolours the badge with everything else and the
   palette freeze is untouched. Scoped to `.nm-break` on purpose: the Most viewed
   and Trending columns below keep their unnumbered cards, so the modal still
   distinguishes the Breaking row from the two ranked-by-nothing rows. */
#news-modal .nm-break .widget-content{counter-reset:nmrank}
#news-modal .nm-break .post-item:not(.nm-slot-empty){counter-increment:nmrank}
#news-modal .nm-break .post-item .post-thumb{container-type:inline-size;position:relative}
 #news-modal .nm-break .post-item .post-thumb:before{content:"";position:absolute;left:0;bottom:0;z-index:2;
  border-bottom:14cqw solid var(--nm-acc);border-right:20cqw solid transparent}
 #news-modal .nm-break .post-item .post-thumb:after{content:counter(nmrank);position:absolute;left:4.4cqw;bottom:3.2cqw;
 color:var(--nm-on-acc);font:700 11.5cqw/1 'Poppins',sans-serif;z-index:3}
/* BLG-C454: an imageless Breaking thumb flex-centered its rank digit mid-card (same merge as C453). display:block with top/right auto retires the centering so the digit stands on the stripe. BLG-C455: pads stay out via :not(.nm-slot-empty) -- pad ghosts must stay suppressed, or with 1 live Breaking post + 3 pads every card reads 1. */
#news-modal .nm-break .post-item:not(.nm-slot-empty) .post-thumb.is-placeholder::after{display:block;top:auto;right:auto;height:auto;pointer-events:none;padding-top:0} /* BLG-C457: digit keeps its corner box while panel text centers up top */
#news-modal .nm-post .post-thumb img{width:100%;height:100%;object-fit:cover;display:block}
#news-modal .nm-post .post-thumb a{display:block;width:100%;height:100%}
#news-modal .nm-post .post-thumb.is-blank{background:var(--cp-surface)}
/* BLG-C229: the empty slot that pads a short row. It borrows the card's
   own shape and the existing is-blank ground rather than inventing a new visual
   language, so an unfilled slot reads as "a card waiting for a story" and not as
   a broken image or a hole in the layout.
   The rank stripe and the rank number are the two things that would otherwise
   give it away as a real card -- the stripe is a :before on .post-thumb and the
   number an :after carrying the nmrank counter -- so both are suppressed, and
   the counter is not incremented for a slot either, so a real post that lands in
   a later slot still numbers 1, 2, 3 in the order the feed returned them.
   The :after suppression also takes the NEWS ghost off the slot thumb, because
   the runtime decorates every imageless thumb with it: a skeleton thumb is the
   plain block, and the ghost belongs to a real post that has no picture.

   BLG-C179: the waiting slot PULSES on the template's skeleton loop.

   BLG-C180: three corrections from the live upload of C179, each measured on
   the live site before anything was written.
   1. SCOPE. Every rule here sat under .nm-break, while the builder emits the
      pad for ALL THREE modal lists (its condition is inNewsModal, count >
      nmCards, nmCards > 0, nothing list-specific). Measured live: Trending's
      slot rendered border 1px solid, opacity 1, animation none, an empty panel
      under a bare thumb, while Breaking's pulsed beside it. The pad was never
      Breaking's; only the styling was. Rules now scope to
      .post-item.nm-slot-empty under #news-modal, so Breaking, Most viewed and
      Trending all get the slot, and the rank numerals themselves stay
      Breaking-only (operator's choice on this change: the skeleton moves
      everywhere, the numbering does not).
   2. LIGHT MODE. The CARD was the animated element: sk-pulse on the item
      fades a white --cp-card box to .42 over the #F8F8FF band, with the thumb
      dimmed to .55 on top of it, so at the trough the whole box dissolved
      into the band instead of reading as processing. The card is now static,
      dashed border at full opacity always, and the breathing moved INSIDE:
      the thumb and the skeleton bars carry the loop, so the shape never
      disappears while its contents still read as active.
   3. ANATOMY. The pad emitted a bare thumb div where a card belongs. It now
      emits the real card's shape (thumb, then .post-panel/.post-ct-panel)
      and this block dresses the panel with .sk bars in the live card's own
   flex layout: a 999px-radius pill where the label pill sits, a date bar on its
   own row below it, two title lines on the rows below that. Bar colour is
      color-mix(in srgb, var(--cp-soft-border) 45%, var(--cp-card)) and not
      --cp-surface, because the surface token is #F3F3F3 in light -- four
      percent off the white card, i.e. exactly the invisibility reported;
the mix lands a visible step off the card in the light theme and off
       the dark card too, and it adds no literal, so the palette freeze still
       reads only tokens.

   Both modes: card, border, thumb and bar colour are tokens both themes
   define. Reduced motion: the bars are .sk and covered by the .sk guard at
   the end of the skin; the thumb's own loop is named in that guard. */
#news-modal .post-item.nm-slot-empty .post-thumb:before,
#news-modal .post-item.nm-slot-empty .post-thumb:after{display:none}
#news-modal .post-item.nm-slot-empty{border-style:dashed}
#news-modal .post-item.nm-slot-empty .post-thumb{background:var(--cp-surface);
  animation:sk-pulse 1.15s ease-in-out infinite}
#news-modal .post-item.nm-slot-empty .sk{background:color-mix(in srgb, var(--cp-soft-border) 45%, var(--cp-card))}
#news-modal .post-item.nm-slot-empty .nm-sk-pill{flex:1 0 100%;width:62px;height:21px;border-radius:999px} /* BLG-C454: pill owns row one like the label */
#news-modal .post-item.nm-slot-empty .nm-sk-date{flex:1 0 100%;height:12px;max-width:100px} /* BLG-C454: date bar owns row two like the date */
#news-modal .post-item.nm-slot-empty .nm-sk-title{flex:1 0 100%;height:16px;max-width:100%}
#news-modal .post-item.nm-slot-empty .nm-sk-title.nm-sk-short{flex:0 0 auto;width:72%;max-width:72%}
/* BLG-C229: and when a list has NO posts at all, the whole section goes -- the
   heading included. Four empty slots answer "the feed failed", which is a
   different and wrong message from "there is nothing here yet". The heading is a
   sibling of the row, so both are hidden from the same class rather than leaving
   a bare title over an empty list. A .nm-col scope is matched on its own so an
   empty Most-viewed column disappears while its neighbour stays. */
#news-modal .nm-col.nm-empty > .nm-h,
#news-modal .nm-col.nm-empty > .post-box,
#news-modal .nm-band.nm-empty > .nm-h,
#news-modal .nm-band.nm-empty > .nm-four,
#news-modal .nm-band.nm-empty > .nm-two{display:none}
/* BLG-C233 / B16: empty states. A buyer installing this on a blog with one post
   should see a template that looks NEW, not one that has failed to load. Each
   state is drawn by the surface that KNOWS whether it has content: the four modal
   lists decide in JS where the count exists, and the two server-rendered chips
   rows decide here in CSS against an empty container. No new colour: --cp-muted is
   the theme's existing secondary ink and --cp-soft-border its existing divider. */
.cp-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:8px;padding:26px 18px;text-align:center;color:var(--cp-muted);
  border:1px dashed var(--cp-soft-border);border-radius:10px}
.cp-empty-title{font:600 14px/1.3 'Poppins',sans-serif;color:var(--cp-text)}
/* BLG-C233 / B16: the same state on an ACCENT surface. The label chips sit on the
   modal's teal gradient, and --cp-muted / --cp-soft-border are page-surface
   tokens, so on the band they read as dark-on-teal and the message is lost.
   Repainted with the tokens the band itself uses: --nm-on-acc for the ink, and
   the band's own 32% color-mix for the edge, which is the same derivation the
   band headings already use. Still no new colour. */
#news-modal .cp-empty{color:color-mix(in srgb, var(--nm-on-acc) 82%, transparent);
  border-color:color-mix(in srgb, var(--nm-on-acc) 32%, transparent)}
#news-modal .cp-empty-title{color:var(--nm-on-acc)}
.cp-empty-note{font:400 12px/1.4 'Poppins',sans-serif;max-width:34ch;color:var(--cp-text)}
/* The note took its colour by INHERITANCE, which is why nothing in this skin ever
   declared it and nothing in the suite ever measured it: it resolved to
   --cp-muted, #A5A5A5, which is 2.46:1 on white. That is a serious WCAG AA
   failure, and it only became VISIBLE once BLG-C485 emptied the demo blog --
   an empty-state line is what a zero-post blog actually shows, so this is the
   first time it has rendered on a live site. Found by axe-core 4.10.2 against
   the showcase blog on 2026-10-14 (the run is recorded in
   docs/AUDIT-REPORT-v1.2.0.md O.2), not by a gate: this class was in no
   contrast-manifest entry, so check-contrast.cjs had nothing to measure and
   reported clean (BLG-C308's lesson, one level on -- a component the manifest
   never lists is a component the gate cannot see). The domain is deliberately
   NOT named here: this comment ships in the product copy, and DOC-NO-DOMAIN
   caught the first attempt at exactly that.

   --cp-text is used rather than a literal because it flips per mode and is
   already the colour its sibling .cp-empty-title uses: measured live, 14.35:1
   on white and 11.71:1 on the dark surface. --cp-muted is fine in dark (6.29:1)
   and is the failure in light, so pinning the token fixes exactly the mode that
   is broken and needs no html.dark override -- the dark override count is
   unchanged at 101, and no documented count moves.

   The news modal keeps its own treatment. That surface has NOT been measured
   (it needs the modal open), so it is pinned to inherit rather than being
   silently restyled by the rule above. */
#news-modal .cp-empty-note{color:inherit}
/* The chips row: an empty flex container has zero height, so it needs a floor
   rather than a border, or the section collapses to nothing. */
#news-modal .nm-chips:empty::after{content:"No labels yet — add one in Blogger, and it appears here";
  display:block;padding:14px 16px;border:1px dashed var(--cp-soft-border);border-radius:10px;
  font:400 12px/1.4 'Poppins',sans-serif;color:var(--cp-muted)}
#news-modal .nm-empty{display:none}
#news-modal .nm-post .post-panel{flex:1 1 auto;min-width:0;padding:11px 13px 14px;margin:0}
/* BLG-C224: the card's three text rows, as the operator asked for them — the
   label and the date share ONE line, the title sits on the second, and the
   title is bigger than it was (14px, which read as small against a 40px
   thumbnail).

   The responsiveness is the same mechanism this modal already uses for its
   thumbnails: the card is a container and the type is sized in cqw, so it
   tracks the card's OWN width rather than the viewport's. That is the property
   the operator asked for — "responsive with the numbers of post showing in this
   section and how the big or small cards has respectively" — and it matters
   here because the grid is auto-fit: the Breaking row holds two posts today and
   will hold four once two more are added, and the same rule has to read
   correctly across that range without anyone editing a breakpoint.

   cqw resolves against the nearest ancestor container, which is why
   container-type is set on .post-item and not on .post-panel: the panel is
   inside the item, so the item is the container the panel's cqw sees. The
   thumbnail is its own container already, so this does not disturb the 8.5cqw
   rank number.

   WHY THESE NUMBERS, each one measured in a real browser rather than reasoned
   about. The Breaking row is auto-fit minmax(min(240px,100%),1fr) in a ~1185px
   row (BLG-C149 measured that row live), so the card width follows the count:
   2 posts -> ~584px, 3 -> ~384px, 4 -> ~284px, floor 240px.

   Three corrections came out of measuring rather than reading:

   1. VERTICAL ALIGNMENT. align-items:center put the date 4px below the label,
      because the pill is 11px type inside 5px of padding (21px tall) while the
      date is 11px/1.3 (14px tall). Centring two different heights inside one
      flex line does not put their text on one line, it only shares the box —
      so `flex-start` plus an explicit `line-height` on both is what actually
      puts the two texts on one baseline. Measured after the change: both tops
      equal.
   2. THE TITLE WAS NOT SCALING, and it took three attempts to see why, each
      measured in Chrome rather than reasoned about. clamp(15px, 4.4cqw, 19px)
      hit its ceiling at 460px, so a 584px card and a 384px card both read 19px.
      Raising the ceiling to 22px fixed the top and not the bottom: 3.6cqw fell
      under the 15px floor at 384px, so 3 and 4 posts read the same again.
      3.2cqw was worse still. What works is 4.4cqw with a 21px ceiling, and the
      measured result at the four widths is 21 / 16.8 / 15 / 15px: three
      distinct sizes, monotonic, every one of them above the old 14px.
      The tie at the bottom is correct rather than a shortfall: between 240px
      and 284px there is no room to tell two cards apart without making the
      title unreadable, and the floor is what stops the narrowest card dropping
      below the size it has today.
   3. min-height is 4.35em, three lines at 1.45 line-height, and em tracks the
      font-size so the reserved third line still matches after a size change.

   The label and date are held flat at 11px on purpose. Scaling them was tried
   and reverted: at 2.3cqw the value fell under its own floor at three of the
   four widths, so it was not scaling either, and a date is the one line here
   that must never wrap. */
#news-modal .nm-post .post-item{container-type:inline-size}
#news-modal .nm-post .post-ct-panel{display:flex;flex-wrap:wrap;align-items:flex-start;gap:6px 8px;padding:0;margin:0}
#news-modal .nm-post .post-label{display:block;margin:0;flex:1 0 100%;max-width:100%;overflow:hidden} /* BLG-C454: label owns row one, so Trending reads like Most viewed (label, date, title) whatever the label length */
#news-modal .nm-post .post-label + .post-label{display:none}
#news-modal .nm-post .post-label a{display:inline-block;background:var(--nm-acc);color:var(--nm-on-acc);
font:700 11px/11px 'Poppins',sans-serif;padding:5px 9px;border-radius:999px;text-decoration:none;
white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
#news-modal .nm-post .post-label a:after{content:none}
#news-modal .nm-post .post-date{display:block;margin:0;flex:1 0 100%;min-width:0; /* BLG-C454: date owns row two, beside nothing */
font:400 11px/21px 'Poppins',sans-serif;opacity:.7;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* The title takes the whole third row: flex-basis 100% plus a wrap break, so
   it cannot end up beside the date on a wide card. */
#news-modal .nm-post .post-title{flex:1 0 100%;margin:0;font:600 clamp(15px,4.4cqw,21px)/1.45 'Poppins',sans-serif;
display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:4.35em}
#news-modal .nm-post .post-title a{color:var(--cp-text);text-decoration:none;font:inherit}
/* BLG-C139: the Most-viewed list is an HTML shortcode widget now, so all three
   lists are the same element type and the sidebar's PopularPosts rules -- the 10px
   li padding, the 700 link weight, the 47% float -- no longer reach it at all.
   The rules that used to fight them are deleted rather than kept as overrides. */
/* Layout editor only: the dashed outline is how the group reads as ONE group,
   the same device the Trending+Featured group already uses (BLG-C051). The
   outline colour is a theme variable, not a literal: a new rgba would trip the
   frozen-palette gate even though this rule never renders on the live site. */
body#layout #news-modal .nm{outline:1px dashed var(--cp-soft-border);outline-offset:10px}
@media (max-width:860px){
  #news-modal .nm-two{grid-template-columns:1fr}
#news-modal .nm-break .widget-content,
#news-modal .nm-col .widget-content{grid-template-columns:repeat(2,minmax(0,1fr))}
  /* BLG-C424: the operator's decision for a phone and a small tablet. The rule
     above makes this grid TWO columns wide, but Most viewed and Trending each
     hold THREE cards, so the third one sat alone on its own row beside an empty
     cell. Measured live at 390px before the change: both columns rendered 3
     cards in a 2-column grid, so nothing was missing, wrapped or clipped and the
     band was simply taller than its content needed. Rather than restyle the
     orphan into a full-width feature card, the operator asked for exactly two
     per column on mobile, which is what this hides. Selector notes, because all
     three of them matter. It is a direct-child selector on .widget-content
     because that is where the shortcode injects the cards and where the grid
     gap applies. It is scoped to .nm-col and not .nm-break because the Breaking
     row above holds four cards and is wanted at two per row. It is
     nth-child(n+3) rather than nth-child(3) so a fourth or fifth card cannot
     reappear if a shortcode count is raised later. The desktop rule at 2091 is
     untouched: a wide screen still shows all three. Hiding the card rather than
     lowering the shortcode count is deliberate, because the count lives once in
     the gadget settings and is shared by both widths. */
  #news-modal .nm-col .widget-content > *:nth-child(n+3){display:none}
}
@media (max-width:560px){
  #news-modal .nm-break .widget-content{grid-template-columns:1fr}
  #news-modal .nm-sb{max-width:none}
  /* BLG-C149: the white seam under the search bar on a phone. The Breaking row
     is display:none at this width, so the two gradient bands that used to have
     it between them end up adjacent with the gaps that used to sit either side
     of it still applied, and they measured 28px apart. Vertical margins on
     adjacent siblings COLLAPSE, so this is not 26px plus 28px; it is the larger
     of the two, and zeroing only the mid band's margin would have left the top
     band's 26px standing. Both go, and the bands meet with no white between
     them, which is what the operator asked for. It is worth being explicit that
     this is a phone-only rule and the desktop seam is untouched: on desktop the
     Breaking row is visible, so the 28px is separating two different sections
     and is wanted there. */
  #news-modal .nm-band-top{margin-bottom:0}
  #news-modal .nm-band-mid{margin-top:0}
}

head.b:template-skin:



.uk-container {max-width: $(content.width); padding: 0 20px}
body#layout {position: relative}
body#layout:before {content: "your theme name your version"; position: absolute; top: 38px; left: 0; width: 100%; color: #999; font-size: 20px; font-family: 'Arial', sans-serif; font-weight: bold; text-transform: uppercase;}
body#layout #loader {display: none;}
body#layout .post-box {margin: 0}
body#layout div.section {margin: 2px; padding: 10px}
body#layout .section h4 {margin: 0 5px}
body#layout .widget-content {padding: 10px}
body#layout .layout-flex {display: flex; flex-wrap: wrap}
body#layout .layout-width-50 {float: left; width: 50%}
body#layout .layout-width-70 {float: left; width: 70%}
body#layout .layout-width-30 {float: left; width: 30%}
body#layout .layout-width-3-3 {width: 33.333%}
body#layout #header {background: #34ad60; display: inline-block; width: 100%; padding: 10px 0}
body#layout #header:before, body#layout #header .uk-position-right .grp-control-hd:before, body#layout #wrapper:before, body#layout #footer:before, body#layout #offcanvas-usage:before {font-size: 20px; font-family: 'Arial', sans-serif; font-weight: bold; position: relative}
body#layout #header:before {content: "Header"; color: #fff;}
body#layout #header .logo-hd {height: auto}
body#layout #header .uk-position-right {padding: 15px 20px 0}
body#layout #header .uk-position-right .grp-control-hd {width: 100%; margin: 0; padding: 0}
body#layout #header .uk-position-right .grp-control-hd:before {content: "HOT NEWS SEARCH"; color: #fff; top: -3px}
body#layout #header .uk-position-right .control-hd:first-child {padding: 5px 0 10px}
body#layout #header .uk-position-right .control-hd {padding: 0}
body#layout #header .uk-position-right .uk-modal-full {width: 100%; padding: 0}
/* BLG-C158: the social icon's dropdown panel is gone (C158 replaced it with the
   #offcanvas-social drawer), so the editor has no panel left to hide here. What
   the editor must hide now is the drawer itself: it is declared outside the
   Layout tree, holds no gadget, and an empty drawer shell under the page is
   noise the same way the empty dropdown was. The widget it displays stays
   declared in the header group (C157's slot cell), so the fourth header gadget
   is still right where the operator manages it. Scoped to body#layout -- the
   front end keeps the drawer, where the relocation script that follows it puts
   the section in before UIkit binds the toggle. */
body#layout #offcanvas-social {display: none}
body#layout #header .uk-position-right .uk-modal-dialog {padding: 20px 0 10px; background: #288047; /* BLG-C157: UIkit ships .uk-modal-dialog at opacity:0 until JS adds .uk-open to its parent, and neither the Layout editor nor a CSS-only browser probe runs that script, so the group would lay out correctly yet never appear. Force it visible in editor scope only; the front end keeps UIkit's own visibility logic. */ opacity: 1}
/* BLG-C197: the operator asked for the HOT NEWS SEARCH group's four gadgets on ONE
   line, "4*1", the way the header section has its four, and after C196 had already
   asked for exactly this and measured four 69px columns, the gadgets still show
   full width and stacked in the editor. So the arrangement moves here, into the
   editor island, and two things change with it.

   WHY A MOVE AND NOT A RESTATEMENT. Editor layout belongs in template-skin: the
   island is stripped from the live site, so nothing here can reach a visitor, and
   it is the sheet the editor loads last. The copies C157 and C196 kept in b:skin
   are deleted rather than left behind, because a second copy is a second answer
   to the same question and only one of them is the one being read.

   WHY THE CELL GETS THE WHOLE GROUP. Measured before this change, in editor state
   on the live page with the shipped editor island injected: `.nm` was ALREADY a
   four column grid, but it sat in the `.cp-hd-news` cell, which is one quarter of
   `.grp-control-hd`, so each card measured 70px wide inside a dialog 7006px tall.
   One row of four slivers is not one row of four gadgets. The cell now takes the
   group's full width (`flex: 1 1 100%`), so the modal row is the group's own
   width and the four cards are four real quarters of it; the HOT control stays
   above them in the same cell.

   WHY THE SELECTORS CARRY THE HEADER CHAIN. `.nm` is a bare class on one element,
   and the editor brings its own stylesheet with its own ideas about widths, so
   these rules name the whole path (`#header .uk-position-right` ahead of
   `#news-modal`) and outrank anything a shorter selector could claim.

   Everything C196 got right is kept: four `minmax(0, 1fr)` columns, so one long
   widget word cannot force a track wide, a 10px gap, `align-content: start`, and
   `--nm-inset: 0` under `body#layout` only, because that padding runs 32.5px a
   side at 1265 and 83px at 1366 and would eat the content box the cards live in;
   the live modal keeps the inset for its bleed. The band wrappers go
   `display:contents` so the four sections reach the grid directly, and the two
   hides keep their reason: the search strip and the section headings are live
   design, not draggable gadgets. Editor-only scope, no `!important`, live modal
   untouched. The C157 rules that sized `.uk-width-1-1:last-child` and its
   `.post-box` go with this: the modal has carried no `uk-width` wrapper since the
   bands were restructured, so they matched nothing. */
body#layout #header .uk-position-right .cp-hd-news {flex: 1 1 100%; width: 100%}
body#layout #header .uk-position-right .uk-modal-dialog,
body#layout #header .uk-position-right .uk-modal-dialog .uk-container {width: 100%}
body#layout #header .uk-position-right #news-modal .nm-break .widget-content,
body#layout #header .uk-position-right #news-modal .nm-col .widget-content {grid-template-columns: 1fr}
body#layout #header .uk-position-right #news-modal .nm {display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; align-content: start; --nm-inset: 0}
body#layout #header .uk-position-right #news-modal .nm-band:not(.nm-band-top),
body#layout #header .uk-position-right #news-modal .nm-four,
body#layout #header .uk-position-right #news-modal .nm-two,
body#layout #header .uk-position-right #news-modal .nm-col,
body#layout #header .uk-position-right #news-modal .nm-tags {display: contents}
body#layout #header .uk-position-right #news-modal .nm-band-top,
body#layout #header .uk-position-right #news-modal .nm-h {display: none}
/* BLG-C156: the operator asked for Social Network Header to sit in the HEADER
   group ahead of the dark mode, with the four header gadgets as two lines of two,
   and the four modal gadgets likewise. **C155 tried to do this by overriding
   `#header` to `display:flex` and flattening four containers to `display:contents`.
   Both moves broke the editor, and the reason is the theme's own group captions.**
   Each group name is a `:before` ON the group box: `body#layout #header:before
   {content:"Header"}` (L1700), styled at L1699 with `position:relative`. That
   pseudo-element belongs to the group's own padding box. The moment `#header`
   becomes a flex container, the `:before` becomes a FLEX ITEM: it is placed in a
   track beside the cells, it is sized by that track, and a six-letter word in a
   narrow track wraps to one letter per line. That is the vertical "H e a d e r"
   the operator photographed, and the same thing happens to the Modal caption. The
   `display:contents` flattening is what let the social cell and the header cells
   share a parent, but it also dissolved the containers the captions hang off.
   **So the fix must not touch `#header` at all.** The reference theme
   (References/LTR-Blog/Gellian-Templates-xml/theme-1647045593618736566.xml) is
   the proof that no override is needed: its L558 is
   `body#layout #header {display:inline-block}`, byte for byte the rule already
   here, and it still lays out two-up. It never overrides the group box, never
   flattens anything, and never sets `order`. **The real defect, and it is in the
   theme rather than in C155: `body#layout .layout-flex` is `display:flex` with
    NO `flex-wrap`.** Two rules apart, L1693 makes the row a flex container and
    L1694 gives the cells `width:50%` and `float:left` -- and **in a flex
    container `float` is ignored and `width` becomes the flex base size, so three
    50% cells do not wrap, they SHRINK.** Measured in a browser with three 50%
    cells in a 900px row: as the theme stands they compute 300px each on a single
    line, and adding `flex-wrap:wrap` alone makes the same three cells 450px and
    450px on row one and 450px on row two. The identical result comes from taking
    the row out of flex and letting the `float` at L1694 do its job, which is
    plainly what L1694 was written to do. That single omission is why the operator
   saw the same layout before and after three rounds of edits, and it is also
   what made the group caption wrap: a 33%-wide flex track for a six-letter word
   at 20px. `.layout-flex` now carries `flex-wrap: wrap`, which is the one
   property the theme was missing, and it is a wrap and nothing else: the
   display stays the theme's own, so the caption keeps its box and its line.
   The C156 attempt to size the social CELL with a width and a float is deleted
   here rather than left beside it. It was inert, and the reason is the same
   flex rule: `.grp-control-hd` carries UIkit's `uk-grid`, so it is a flex
   container too, and a float inside a flex container is ignored. Measured with
   the cell left in the control row, the section stayed at 226px below the
   header whatever width it was given. BLG-C157 moves the SECTION into the
   header row instead, where it is a real `.layout-width-50` cell and the wrap
   above does the rest. */
body#layout #wrapper {background: #ea0c3e; padding: 10px 0}
body#layout #wrapper:before {content: "Featured Area"; color: #fff; top: -2px}
body#layout #wrapper .bk-news {padding: 0}
body#layout #wrapper .row-container, body#layout #wrapper .row-grey, body#layout #wrapper .row-black {padding: 0}
body#layout #wrapper .post-cate-video {margin: 0}
body#layout #wrapper .sidebar {width: 100%}
body#layout .mog-adv {display: inherit; width: -webkit-fill-available}
body#layout #footer {background: #046e8c; padding: 10px 0}
body#layout #footer:before {content: "Footer Area"; color: #fff; top: -2px}
body#layout #footer .bot-ft {margin: 0; padding: 0}
body#layout #footer .bot-ft .uk-width-auto {display: none}
body#layout #offcanvas-usage {background: #daca08}
body#layout #offcanvas-usage:before {content: "Off Canvas Area"; color: #fff; top: 6px}
body#layout .uk-offcanvas-bar {padding: 10px 20px}
body#layout .uk-offcanvas-bar .contact-me {padding: 0}
/* BLG-C198: the Off Canvas Area takes the layout plan's 2-tier arrangement,
   replacing BLG-C197's three rows of two. Row one: Info Me and Contact Me at
   50/50. Row two: Page Width Control, Default Images, Cookie Consent and
   Newsletter Setup as four equal cards at 25 each. The markup already declares
   the sections in exactly that order (box one Info Me, box two Contact Me,
   box three Page Width, box four holding the other three), so this is
   geometry only and no section moves, same as C197.

   Four tracks, not flex: boxes one and two span two tracks each and fill row
   one; box three takes the first track of row two; box four is
   display:contents, so the three sections it holds take the remaining three
   tracks. The plan writes these tiers as a wrapping flex row plus float rows
   with !important on every declaration. That trio was not taken: a flex row
   with C197's gap would have pushed the third card onto a third line (50 plus
   50 plus 25 exceeds the row), floats fight the gap the same way, and the
   project rule bans !important outright. The grid states both tiers in one
   declaration, keeps the measured 10px gap, and needs no !important because
   the body#layout ID anchor already outranks the editor chrome, which is the
   same reasoning C197 shipped.

   Box four stays display:contents for C197's own reason, which still holds:
   C156's warning is about a CAPTIONED group box, the Off Canvas Area caption
   hangs on #offcanvas-usage itself, and no grid item here carries a :before
   caption. min-width:0 stays for C197's reason too (the contact form's
   size=30 input must be allowed to shrink below its content width).

   The close button now needs a rule, where C197 said it did not. C197 was
   right on the live page: UIkit gives it position:absolute, so it is out of
   flow. But the real Layout editor applies neither UIkit's stylesheet nor its
   JS (BLG-C157), so in the editor that button is an in-flow grid item and
   would take the first track of row one, wrecking the 2-tier geometry the
   moment a buyer opens Layout. Hiding it under body#layout costs nothing:
   closing the drawer is a live-page affordance, meaningless while dragging
   gadgets. It stays visible in every non-editor context.

   All of it sits under body#layout: the live drawer keeps UIkit's own block
   layout, where the boxes stack as the design intends.

   The plan's HOT NEWS SEARCH replacement is deliberately NOT taken as part of
   this change: C197's measured island (four minmax columns, cards 303px at
   x=20/333/645/958) already matches what the plan asks for, and the plan's
   float block was written against the pre-C156 markup. Kept, verified
   untouched in the harness when these tiers were measured. */
body#layout #offcanvas-usage .uk-offcanvas-bar {display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; align-items: stretch}
body#layout #offcanvas-usage .uk-offcanvas-bar > .post-box {margin: 0; min-width: 0}
body#layout #offcanvas-usage .uk-offcanvas-bar > .post-box:nth-of-type(1),
body#layout #offcanvas-usage .uk-offcanvas-bar > .post-box:nth-of-type(2) {grid-column: span 2}
body#layout #offcanvas-usage .uk-offcanvas-bar > .post-box:nth-of-type(4) {display: contents}
body#layout #offcanvas-usage .uk-offcanvas-bar > .post-box:nth-of-type(4) > div {min-width: 0}
body#layout #offcanvas-usage .uk-offcanvas-bar > .uk-offcanvas-close {display: none}

b:if.script:
    //
    (function () {
      'use strict';

      // Same contract as the product copy: the licence API is a Cloudflare
      // Worker, and a genuine serial can come back flagged as a duplicate
      // because the guard reports its domain.
      var API_URL     = 'https://meva-licence-api.kuldeep7ke.workers.dev';
      var TEMPLATE_ID = 'blogger-llianmeva-template';
      // C235's escape for an unconfigured endpoint, kept because the reasoning
      // still holds; it no longer fires, as API_URL above is a real endpoint.
      var API_NOT_CONFIGURED = 'PASTE-YOUR-APPS-SCRIPT-EXEC-URL-HERE';
      // The free edition's footer credit. The guard injects it on every
      // unlicensed blog and verifies it survives; it is not in Layout to edit,
      // and removing it by editing the theme blocks the blog until it is
      // restored. The text and link are DEMO values: the operator replaces both
      // before this ships to anyone.
      // The designer credit is two halves: the sentence is plain text and only
      // the studio NAME is the bold link. One bolded whole sentence reads as a
      // banner; a plain lead-in with one bolded name reads as a credit.
      var CREDIT_PREFIX = 'Crafted with care by';
      var CREDIT_NAME   = 'Marathi Meva';
      var CREDIT_URL    = 'https://marathimeva.com/templatemeva/';
      // CREDIT_REV is the revision of that wording this template was BUILT with,
      // and it is half of the mechanism behind "a credit change reaches new
      // copies only": the Serial Manager is where the wording is edited, and this
      // number is stamped into the template by tools/sync-credit.cjs at build
      // time (tools/stamp-free-serial.cjs can move it alone). The guard reports
      // it on every validate so the operator can see how many live free installs
      // still carry older wording.
      //
      // The guard renders the constants above as its OFFLINE FALLBACK, and the
      // runtime copy below replaces them when the Worker answers. Being baked is
      // what makes the credit survive the Worker being down or removed; it is
      // not a claim that a saved wording cannot reach a live page.
      var CREDIT_REV    = 3;

      // BLG-C545: THE CREDIT IS RUNTIME, WITH THESE FOUR LINES AS THE FALLBACK.
      //
      // The wording above is the credit this copy was BUILT with. It is not the
      // authority any more: the Worker is. The credit of record rides on the
      // validate verdict, so saving a new wording on the Serial Manager reaches
      // every copy without a build, a re-upload and a deploy -- which is the
      // whole point, because before this a credit change was four steps across
      // two repositories and a trap in the middle of them.
      //
      // These four stay for the one case that matters most: the Worker being
      // unreachable, slow, or returning nonsense. Then the blog still shows a
      // credit, so the free edition keeps working offline. A build that carried
      // no credit at all would show a bare "All Rights Reserved" the moment the
      // API went down, which is the worst possible moment to lose attribution.
      //
      // `liveCredit` is what is actually rendered. It starts as the baked
      // values, is replaced by the last cached copy -- fresh or stale, so a
      // repeat visitor never sees the wording fall back while the check is in
      // flight -- and by the verdict's copy when that arrives.
      var liveCredit = {
        prefix: CREDIT_PREFIX,
        name: CREDIT_NAME,
        url: CREDIT_URL,
        revision: CREDIT_REV
      };
      // Short on purpose. The credit is three short strings, and a visitor
      // seeing yesterday's studio name for a few minutes is not a bug anyone
      // reports -- whereas a stale-for-a-day footer is exactly the sort of thing
      // an operator notices and cannot explain. Five minutes also keeps this to
      // one small request per visitor per five minutes, paid on top of the
      // licence round-trip only when that cache has also expired.
      var CREDIT_TTL_MS = 300000;
      var CREDIT_CACHE_KEY = 'meva_credit_' + TEMPLATE_ID;

      // The credit of record, validated to the same rules the Worker applies
      // before it ever sends one. A guard must not trust a payload it did not
      // check: this is server-supplied text that ends up in a link, so an
      // unchecked `javascript:` href or a megabyte of text would be a hole.
      // Every value arrives as text and is written with textContent, never
      // innerHTML, so nothing here can become markup.
      function creditFromVerdict(c) {
        if (!c || typeof c !== 'object') { return null; }
        var prefix = typeof c.prefix === 'string' ? c.prefix.trim() : '';
        var name = typeof c.name === 'string' ? c.name.trim() : '';
        var url = typeof c.url === 'string' ? c.url.trim() : '';
        // THE NAME IS REQUIRED. It is the one bolded, linked part of the line,
        // and a prefix with no name renders "<prefix> " and nothing else.
        // creditContentIntact() below requires a non-empty name, so accepting
        // this shape would make the guard convict the credit the server just
        // told it to render -- the wall would be the guard's own verdict. The
        // Worker now refuses to store a nameless credit; this rejects any legacy
        // record or malformed payload that still arrives, and the baked fallback
        // carries the page instead.
        if (!name) { return null; }
        if (prefix.length > 160 || name.length > 160 || url.length > 300) { return null; }
        if (url) {
          var u;
          try { u = new URL(url); } catch (e) { return null; }
          if (u.protocol !== 'https:' && u.protocol !== 'http:') { return null; }
          url = u.href;
        }
        var rev = Number(c.revision);
        if (!isFinite(rev) || rev < 0) { return null; }
        return { prefix: prefix, name: name, url: url, revision: Math.floor(rev) };
      }

      // The stored record is also the check stamp: `at` is when the Worker last
      // answered, and `credit: null` is a real answer ("none configured"),
      // not a missing one. The fast path reads the stamp, so a free blog with
      // no credit configured still checks once per TTL instead of on every
      // page view.
      function readCreditCache() {
        try {
          var raw = localStorage.getItem(CREDIT_CACHE_KEY);
          if (!raw) { return null; }
          var box = JSON.parse(raw);
          if (!box || !box.at) { return null; }
          var credit = box.credit === null ? null : creditFromVerdict(box.credit);
          if (box.credit !== null && !credit) { return null; }
          return { at: box.at, credit: credit };
        } catch (e) { return null; }
      }

      function creditCheckFresh() {
        var box = readCreditCache();
        return !!(box && (Date.now() - box.at) <= CREDIT_TTL_MS);
      }

      function cacheCredit(c) {
        try {
          localStorage.setItem(CREDIT_CACHE_KEY, JSON.stringify({ at: Date.now(), credit: c || null }));
        } catch (e) { /* private mode: the baked fallback carries it */ }
      }

      // Take the server's credit when there is one, and ALWAYS record the ask.
      // `c` is null when the server answered and had no credit configured: that
      // is still an answer, and refreshing the stamp is what keeps the fast
      // path from re-asking on every page view.
      function applyCredit(c) {
        cacheCredit(c);
        if (!c) { return false; }
        var same = c.prefix === liveCredit.prefix && c.name === liveCredit.name &&
                   c.url === liveCredit.url && c.revision === liveCredit.revision;
        if (same) { return false; }
        liveCredit = c;
        // Repaint the one line, in place, rather than tearing the footer down:
        // the owner line is saved by ensureFreeCredit and must not be rewritten.
        var tag = document.getElementById('meva-free-credit');
        var p3 = tag && tag.querySelector('.mcp-3');
        if (p3) {
          var link = p3.querySelector('a');
          if (link) {
            link.href = c.url;
            link.textContent = c.name;
            if (p3.firstChild && p3.firstChild.nodeType === 3) {
              p3.firstChild.nodeValue = c.prefix + ' ';
            } else {
              p3.insertBefore(document.createTextNode(c.prefix + ' '), link);
            }
          }
        }
        return true;
      }

      // Warm from the last record before anything renders, fresh or stale: it
      // is the wording this visitor saw last, and a stale one is refreshed by
      // the server round-trip isCacheValid() now requires. Throwing a stale
      // record away is what made the footer fall back to the baked copy after
      // five minutes even though the server was reachable.
      (function () {
        var box = readCreditCache();
        if (box && box.credit) { liveCredit = box.credit; }
      })();

      // The free-edition serial is shipped in the Licence Activation gadget and
      // read from there, not duplicated here: one place to change, and the owner
      // can see and copy the value. See freeEditionSerial().
      // Template identity, shown in the free-edition notice so the owner can
      // see which theme is talking: the label as the notice eyebrow, the name
      // in its opening line. These two assignments ship in every copy,
      // including the product: they are the theme's own attribution, and the
      // clean-copy sweep exempts exactly these lines (by shape, never by brand
      // string) while still forbidding the brand anywhere else. See
      // tools/make-clean-template.cjs.
      var TEMPLATE_LABEL    = 'Blogger Template Meva';
      var TEMPLATE_NAME     = 'LlianMeva v1.2.0';
      // AUD-H01: a cached pass means a licensed blog does not pay the licence
      // round-trip on every page view. 24h (was 30m); the redeem path still runs
      // first, so activation never waits out the cache window.
      var CACHE_MINS  = 1440; // 24 hours

      // The cache can only skip the server while nothing on the page still
      // depends on the answer. A licensed cached view draws its own footer. A
      // free view draws the runtime credit, whose TTL is shorter, so its check
      // must be fresh too -- otherwise the wording would sit on the baked copy
      // until this 24-hour cache expired.
      function isCacheValid() {
        try {
          var ok = sessionStorage.getItem('lic_ok');
          var at = parseInt(sessionStorage.getItem('lic_t') || '0', 10);
          var licensed = sessionStorage.getItem('lic_state') === 'active';
          return ok === '1' && (Date.now() - at) < (CACHE_MINS * 60 * 1000) &&
                 (licensed || creditCheckFresh());
        } catch (e) { return false; }
      }

      function setCache() {
        try {
          sessionStorage.setItem('lic_ok', '1');
          sessionStorage.setItem('lic_t', String(Date.now()));
        } catch (e) {}
      }

function clearCache() {
try {
sessionStorage.removeItem('lic_ok');
sessionStorage.removeItem('lic_t');
/* BLG-C515: the tamper flag is session taint, not a verdict. Recheck, the
8 s fallback and redeem all land here; a flag left standing would keep every
later validate in this session claiming credit=missing after a genuine
restore, which is the stuck "credit removed" record. A still-broken credit
re-arms the flag through reportTamper on the same run. */
sessionStorage.removeItem('meva_credit_tamper_' + TEMPLATE_ID);
} catch (e) {}
}

      // One copy helper for the whole guard. It uses a detached textarea and
      // execCommand, so it works from any control and needs no permission.
      function copyText(text, done) {
        try {
          var ta = document.createElement('textarea');
          ta.value = text;
          ta.setAttribute('readonly', '');
          ta.style.cssText = 'position:fixed;left:-9999px';
          document.body.appendChild(ta);
          ta.select();
          var okc = document.execCommand('copy');
          document.body.removeChild(ta);
          done(okc ? 'Copied' : 'Copy failed');
        } catch (e) { done('Copy failed'); }
      }


      // The footer-guard wall. It is the ONLY thing that hides the blog, and it
      // appears for exactly one reason: the free edition's footer credit was
      // removed or hidden. It carries no link out and no countdown -- the way
      // back online is to restore the credit -- and it offers a recheck. Every
      // node is built with textContent; no server string is ever parsed as
      // markup.
      function showOverlay(data) {
        if (!document.body) {
          document.addEventListener('DOMContentLoaded', function () { showOverlay(data); });
          return;
        }
        if (document.getElementById('meva-lic-overlay')) { return; }
        var m = (data && data.message) || null;
        var overlay = document.createElement('div');
        overlay.setAttribute('id', 'meva-lic-overlay');
        overlay.style.cssText = 'position:fixed;left:0;top:0;right:0;bottom:0;' +
          'background:rgba(0,0,0,.7);z-index:2147483647;display:flex;flex-direction:column;' +
          'align-items:center;justify-content:center;font-family:system-ui,-apple-system,sans-serif;' +
          'color:#ffffff;text-align:center;padding:2rem';
        var lock = document.createElement('div');
        lock.style.cssText = 'font-size:3.5rem;margin-bottom:0.5rem';
        lock.textContent = '🔒';
        var h = document.createElement('h2');
        h.style.cssText = 'font-size:1.5rem;margin:0 0 0.6rem;color:#ffffff';
        h.textContent = (m && m.headline) || 'Footer credit changed';
        var d = document.createElement('p');
        d.style.cssText = 'color:#8fafbf;max-width:400px;line-height:1.6;margin:0 0 1.5rem';
        d.textContent = (m && m.detail) ||
          'The free edition keeps its footer credit in place. Restore the designer credit in your footer to bring this blog back online.';
        var b = document.createElement('button');
        b.type = 'button';
        b.textContent = 'Recheck';
        b.style.cssText = 'display:inline-block;background:#288047;color:#fff;' +
          'padding:0.7rem 2rem;border:0;border-radius:10px;font-weight:700;' +
          'font-size:1rem;cursor:pointer';
        b.onclick = function () {
          hideOverlay();
          clearCache();
          run();
        };
        overlay.appendChild(lock); overlay.appendChild(h); overlay.appendChild(d);
        overlay.appendChild(b);
        document.body.style.overflow = 'hidden';
        document.body.appendChild(overlay);
      }

      // BLG-C235: the counterpart showOverlay() needs. Taking the wall down must
      // also restore body scroll, or the page stays scroll-locked after it goes.
      function hideOverlay() {
        var o = document.getElementById('meva-lic-overlay');
        if (o && o.parentNode) { o.parentNode.removeChild(o); }
        if (document.body) { document.body.style.overflow = ''; }
      }

      // A licence that is genuine but running on too many sites: a dismissible
      // notice, so the holder can read it and act.
      //
      // Colours are from the frozen palette, same as the product copy. See
      // docs/COLORSCHEME.md and the note on check 5a there.
      function showDuplicateNotice(data) {
        if (!document.body) { return; }
        if (document.getElementById('meva-lic-notice')) { return; }
        var m = data.message || {};
        var accent = (m.tone === 'urgent') ? '#da0100' : '#288047';
        var key = 'meva_dup_' + TEMPLATE_ID;
        try {
          if (Date.now() - parseInt(sessionStorage.getItem(key) || '0', 10) < 86400000) { return; }
        } catch (e) { /* private mode: show it */ }

        var scrim = document.createElement('div');
        scrim.setAttribute('id', 'meva-lic-scrim');
        scrim.style.cssText = 'position:fixed;left:0;top:0;right:0;bottom:0;' +
          'z-index:2147483645;background:rgba(0,0,0,0.3);' +
          'backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px)';
        // No scrim click to dismiss: a reader reaching for the page behind
        // the dim should not lose the notice for it.

        function dupOnKey(e) { if (e.key === 'Escape' || e.keyCode === 27) { dismissDuplicate(); } }
        function dismissDuplicate() {
          try { sessionStorage.setItem(key, String(Date.now())); } catch (e) {}
          document.removeEventListener('keydown', dupOnKey);
          if (scrim.parentNode) { scrim.parentNode.removeChild(scrim); }
        }

        var box = document.createElement('div');
        box.setAttribute('id', 'meva-lic-notice');
        box.setAttribute('role', 'dialog');
        box.setAttribute('aria-modal', 'true');
        box.setAttribute('aria-labelledby', 'meva-lic-title');
        box.style.cssText = 'position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);' +
          'z-index:2147483646;width:min(520px,calc(100% - 32px));' +
          'background:#0b1d27;' +
          'border:1px solid rgba(255,255,255,0.1);border-radius:14px;overflow:hidden;' +
          'box-shadow:0 24px 60px rgba(0,0,0,.7);color:#d9e9f0;' +
          'font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif';

        var bar = document.createElement('div');
        bar.style.cssText = 'height:4px;background:' + accent;

        var head = document.createElement('div');
        head.style.cssText = 'padding:18px 22px 0';
        var h = document.createElement('strong');
        h.setAttribute('id', 'meva-lic-title');
        h.style.cssText = 'font-size:17px;font-weight:700;color:#d9e9f0'; // BLG-C306: was + accent, whose both tones failed on the #0b1d27 card at 17px/700 (#da0100 3.26:1, #288047 3.50:1 -- under 4.5). #d9e9f0 is 13.8:1; the tone colour now lives on the 4px bar alone.
        h.textContent = m.headline || 'Licence notice';
        head.appendChild(h);

        // textContent, never innerHTML: the copy arrives from the API.
        var d = document.createElement('p');
        d.style.cssText = 'margin:10px 22px 0;font-size:14.5px;line-height:1.55;color:#d9e9f0';
        d.textContent = m.detail || '';
        var r = document.createElement('p');
        r.style.cssText = 'margin:8px 22px 0;font-size:13.5px;line-height:1.55;color:#8fafbf';
        r.textContent = m.remedy || '';

        var rule = document.createElement('div');
        rule.style.cssText = 'height:1px;background:rgba(255,255,255,0.1);margin:18px 0 0';

        var row = document.createElement('div');
        row.style.cssText = 'display:flex;align-items:center;gap:10px;padding:16px 22px 20px';

        // The dismiss control is the ONLY action. The notice is information:
        // its job is to be read, not to send the reader anywhere, so there is
        // no link out and nothing to buy or reply to.
        var x = document.createElement('button');
        x.type = 'button';
        x.textContent = 'Dismiss';
        x.style.cssText = 'padding:9px 22px;border:1px solid #288047;border-radius:8px;' +
          'background:#288047;color:#fff;font:600 14px/1 inherit;cursor:pointer';
        x.onclick = dismissDuplicate;
        row.appendChild(x);

        box.appendChild(bar); box.appendChild(head); box.appendChild(d); box.appendChild(r);
        box.appendChild(rule); box.appendChild(row);
        scrim.appendChild(box);
        document.body.appendChild(scrim);
        document.addEventListener('keydown', dupOnKey);
        try { x.focus({ preventScroll: true }); } catch (e) { /* older browser */ }
      }

      // A server verdict that is not a footer-credit block is shown as a
      // dismissible notice, never a wall: the reader cannot act on it, and the
      // free edition keeps working the whole time.
      function showBlocked(data) {
        showDuplicateNotice(data);
      }

      // BLG-C405 noted a bottom-fixed notice covering the footer and a
      // reserve-the-notice-height fix for it. That shape is gone: since the
      // C413 rewrite the notice is a centered dialog that reserves nothing,
      // so the padding machinery (trialPad/reserveForNotice/releaseNoticeSpace)
      // was deleted rather than wired up.
      // BLG-C199: the trial popup -- server-owned clock, masked blog id.
      // The trial passes -- the site renders -- but the clock is running, so the
      // owner is told. Dismissible for this page-open only, never a block, and
      // skipped in Layout mode, where the author is editing rather than viewing.
      // API copy arrives through textContent, never innerHTML; colours are the
      // frozen palette (docs/COLORSCHEME.md, check 5a).
      // BLG-C408: the Licence Activation gadget in the off-canvas.
      //
      // Its HTML Content box is the serial carrier: in Layout, click the
      // pencil, choose Edit HTML, and paste the line the author sent you --
      // one line, "Name@Gmail.com AB12C-34DEF-56789-0ABCD-EF012", email first,
      // the serial after. The email is optional; the serial alone on the line
      // also works. Save, and the guard on the next page load picks it up.
      //
      // It is hidden by CSS unless the document is Blogger's Layout editor, so a
      // visitor never sees it. The widget must NOT carry Blogger's hidden
      // attribute: the guard reads the paste from the RENDERED page, and a
      // hidden widget never reaches it -- activation would silently never fire.
      //
      // The pasted serial is POSTed to ?action=redeem ONCE per serial (tracked
      // in sessionStorage), in a JSON body, never in a URL. After that the
      // guard validates by domain alone and the pasted line has done its job.
      //
      // BLG-C425: BOTH halves of that payload are owner data, so the POST is
      // gated to Blogger's Layout editor, where the owner is already
      // authenticated. It is an owner action by design -- the Serial Manager
      // issues the line, the owner pastes it -- so nothing is lost off Layout.
      // The per-page ?action=validate call below carries NO credential and
      // still runs for every reader, which is exactly what it should do.
      function readPastedLicence() {
        var el = document.querySelector('#HTML22 .widget-content');
        if (!el) { return null; }
        var t = el.textContent || '';
        // The gadget ships the FREE-EDITION serial as visible text, so the very
        // same textContent the licence is read from contains one. It is not a
        // licence and redeeming it would fail on every free install, so it is
        // recognised and skipped. Shape only: <code>-<edition>-<digits>-g-g,
        // which a licence serial (five hex groups) can never match.
        if (/\b[a-z0-9]{3}-[a-z]{3,12}-\d{5,6}-[a-z0-9]{5}-[a-z0-9]{5}\b/i.test(t)) { return null; }
        var m = t.match(/([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})?[ \t]*([0-9A-Fa-f]{5}(-[0-9A-Fa-f]{5}){4})/);
        if (!m) { return null; }
        return { email: (m[1] || '').trim(), serial: (m[2] || '').toUpperCase() };
      }

      // The free-edition serial shipped in the Licence Activation gadget, read
      // from the element that displays it. Returns '' when the gadget carries no
      // serial or still carries the unminted placeholder, so an unminted template
      // behaves exactly as it did before this existed: it sends nothing and the
      // free path is unchanged. This value is PUBLIC (it ships in every download)
      // and names a release, not a buyer, so sending it is not a credential leak.
      function freeEditionSerial() {
        var el = document.querySelector('#HTML22 .meva-fes');
        if (!el) { return ''; }
        var raw = (el.textContent || '').trim();
        // The unminted placeholder is rejected BY NAME as well as by shape, and
        // it has to be: its X is not outside the check alphabet once the text is
        // lowercased, because x is a legitimate character there. Shape alone
        // accepts 'XXXXX' and would send the placeholder to the server as though
        // it had been minted. A gate that only checked the shape would have
        // called this correct.
        if (!raw || raw === 'llm-free-12026-XXXXX-XXXXX') { return ''; }
        var t = raw.toLowerCase();
        if (!/^[a-z0-9]{3}-[a-z]{3,12}-\d{5,6}-[a-z0-9]{5}-[a-z0-9]{5}$/.test(t)) { return ''; }
        return t;
      }

      // BLG-C530: THE LOCK STATE, and why it is a separate function.
      //
      // freeEditionSerial() answers "what do I send" -- '' covers three very
      // different situations (no span, placeholder, garbage) because all three
      // send nothing. The wall needs to tell those situations APART: a missing
      // span is tampering and locks, the placeholder is the legitimate unminted
      // state and does not, and garbage is a hand-edit and locks. Collapsing
      // the distinction into the sender would make the wall fire on unminted
      // templates -- which is exactly the false positive that would teach
      // owners the wall is noise and can be ignored. So the state is read
      // here, once, and both the sender and the wall below consult it.
      //
      // Four states: 'ok', 'unminted', 'missing', 'invalid'. The wall fires on
      // exactly 'missing' and 'invalid'. The logic mirrors serialState() in the
      // project's tools/free-serial.cjs; tests/check-free-serial-lock.cjs
      // asserts the two agree rather than trusting that they do.
      function freeSerialState() {
        var el = document.querySelector('#HTML22 .meva-fes');
        if (!el) { return 'missing'; }
        var raw = (el.textContent || '').trim();
        if (!raw) { return 'missing'; }
        if (raw === 'llm-free-12026-XXXXX-XXXXX') { return 'unminted'; }
        var t = raw.toLowerCase();
        if (/^[a-z0-9]{3}-[a-z]{3,12}-\d{5,6}-[a-z0-9]{5}-[a-z0-9]{5}$/.test(t)) { return 'ok'; }
        return 'invalid';
      }

      function initLicenceGadget() {
        // BLG-C425: THE LAYOUT GATE, and it is a privacy fix, not an optimisation.
        //
        // The serial is HMAC(SECRET, blogId:templateId): it is derived from the
        // BLOG's identity and never from the buyer's email, so it is a proof of
        // purchase rather than a secret -- but the EMAIL pasted beside it is the
        // buyer's own address, and it reaches this POST as contact metadata. That
        // makes the whole payload owner data, which means who may send it is not a
        // detail.
        //
        // It may only be sent by the OWNER, from the Layout editor, where Blogger
        // has already authenticated them. Before this gate, ANY reader's page load
        // found the paste in the rendered markup and redeemed once per session --
        // so the buyer's email left the site once per visitor, to a third party,
        // for ever. sessionStorage stopped the repetition but not the audience.
        //
        // The gate is exact rather than approximate: the redeem is an owner action
        // by design (the Serial Manager issues the line, the owner pastes it), so
        // losing it off Layout costs nothing. The validate path below carries NO
        // credential and still runs for every reader, which is correct: it is how
        // a licensed site proves itself to its own visitors.
        if (document.body.id !== 'layout') { return; }
        var pasted = readPastedLicence();
        if (!pasted) { return; }
        var key = 'meva_redeemed_' + TEMPLATE_ID + '_' + pasted.serial;
        var done = false;
        try { done = sessionStorage.getItem(key) === '1'; } catch (e) {}
        if (done) { return; }
        fetch(API_URL + '?action=redeem', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({
            serial: pasted.serial,
            email: pasted.email,
            domain: location.hostname,
            templateId: TEMPLATE_ID,
          }),
        }).then(function (r) { return r.json(); }).then(function (j) {
          if (j && j.ok) {
            try { sessionStorage.setItem(key, '1'); } catch (e) {}
            // The page that pasted the line is showing the free-edition view of
            // the world. Take any notice down and re-check now, so the pending
            // state lands on THIS load instead of the next one. The session flag
            // above keeps this from re-posting.
            var pop = document.getElementById('meva-free-popup');
            if (pop && pop.parentNode) { pop.parentNode.removeChild(pop); }
            var scrim = document.getElementById('meva-free-scrim');
            if (scrim && scrim.parentNode) { scrim.parentNode.removeChild(scrim); }
            var ppop = document.getElementById('meva-pending-popup');
            if (ppop && ppop.parentNode) { ppop.parentNode.removeChild(ppop); }
            var pscrim = document.getElementById('meva-pending-scrim');
            if (pscrim && pscrim.parentNode) { pscrim.parentNode.removeChild(pscrim); }
            clearCache();
            run();
          } else if (window.console && window.console.warn) {
            window.console.warn('Licence activation did not take: ' + ((j && (j.hint || j.error)) || 'unknown'));
          }
        }).catch(function () {});
      }

      // The footer is ONE line and it is REPLACED, not appended to. An earlier
      // version appended the credit beside the Copyright widget's own text, and
      // the live footer read:
      //
      //   Copyright © 2026. All rights reserved. | Testing Template |
      //   All Rights Reserved | Testing Template © 2026 | Crafted with care by Gavran Meva
      //
      // Three copyrights, two years and two title clauses in eight words of
      // credit: the widget's own line and the credit said the same thing twice.
      // So the free-edition line is written as a whole, and the widget's own
      // content is what gets replaced:
      //
      //   <blog name> © <year> | All Rights Reserved | <designer credit>
      //
      // Blog name and year are live; everything else is fixed. The name is the
      // BRAND (og:site_name), never the page's own title: on a post page the
      // tab title composes page + site, and the post title has no place in the
      // credit. The credit is injected,
      // never Layout-editable, so defeating it means editing the theme or hiding it
      // with CSS. The active-site credit is the site's own footer line (creditVisible).
      function ensureFreeCredit() {
        var host = document.querySelector('.copyright-ft .widget-content');
        if (!host) { return false; }
        if (document.getElementById('meva-free-credit')) { return true; }
        // A licensed blog keeps its own footer. Replacing the line and then
        // putting it back on every page view would flash the credit in and out
        // once per load, so the last known licence state decides before
        // anything is touched.
        try {
          if (sessionStorage.getItem('lic_state') === 'active') { return true; }
        } catch (e) { /* private mode: fall through and inject */ }
        // Keep the owner's own line verbatim, once, so a later licensed verdict
        // can restore it exactly. InnerHTML is the right level here: the
        // widget is owner-authored markup and it is preserved, not rebuilt.
        if (!host.getAttribute('data-meva-owner-line')) {
          try { host.setAttribute('data-meva-owner-line', host.innerHTML); } catch (e) {}
        }
        while (host.firstChild) { host.removeChild(host.firstChild); }
        var tag = document.createElement('span');
        tag.setAttribute('id', 'meva-free-credit');
        // Three parts, in the order the credit is read: the blog name with its
        // live year (the brand), the rights line, then the fixed studio
        // credit. The pipes between them are CSS (see #meva-free-credit in
        // the skin), so the same DOM is one line on a desktop and three on
        // a phone.
        var p1 = document.createElement('span');
        p1.className = 'mcp-1';
        // The brand, not the page: document.title carries the POST title on a
        // post page, so the credit once read "Introducing X — ... | BlogName"
        // there. og:site_name is the blog name on every page -- the same
        // source the activated footer fills .policy-title from; document.title
        // is only the fallback when the meta is absent.
        var site = document.querySelector('meta[property="og:site_name"]');
        p1.textContent = ((site && site.content) ? site.content : document.title) + ' © ' + new Date().getFullYear();
        var p2 = document.createElement('span');
        p2.className = 'mcp-2';
        p2.textContent = 'All Rights Reserved';
        var p3 = document.createElement('span');
        p3.className = 'mcp-3';
        p3.appendChild(document.createTextNode(liveCredit.prefix + ' '));
        var a = document.createElement('a');
        a.href = liveCredit.url;
        a.rel = 'noopener';
        // Inline, so no theme stylesheet can restyle it: bold white, and no
        // underline in any state -- an inline text-decoration beats a theme
        // :hover rule by specificity, so hovering never underlines.
        a.style.cssText = 'font-weight:700;color:#fff;text-decoration:none';
        a.textContent = liveCredit.name;
        p3.appendChild(a);
        tag.appendChild(p1); tag.appendChild(p2); tag.appendChild(p3);
        host.appendChild(tag);
        return true;
      }

      function removeFreeCredit() {
        var tag = document.getElementById('meva-free-credit');
        if (tag && tag.parentNode) { tag.parentNode.removeChild(tag); }
        var host = document.querySelector('.copyright-ft .widget-content');
        var saved = host && host.getAttribute('data-meva-owner-line');
        // A licensed footer is the owner's own line again, exactly as it was.
        // With nothing saved there is nothing to restore and nothing to undo.
        if (host && saved != null) {
          try { host.innerHTML = saved; } catch (e) {}
          try { host.removeAttribute('data-meva-owner-line'); } catch (e) {}
        }
      }

      // BLG-C517: the credit a site must show depends on the edition: the free
      // edition's is the injected tag, an ACTIVATED site's is its own footer line.
      // Checking only the tag walled a healthy paid site on every cached view -- the
      // tag is gone by design once active -- and filed a false credit=missing.
      function creditVisible() {
        var tag = document.getElementById('meva-free-credit');
        if (!tag || !tag.parentNode) {
          var on = false;
          try { on = sessionStorage.getItem('lic_state') === 'active'; } catch (e) {}
          return on && copyrightFingerprint() !== 'absent';
        }
        /* BLG-C590: reading mode hides #footer, and this tag with it, by design.
           That is the product's own reader, not the owner hiding the credit: the
           tag is still in the page and creditContentIntact() still verifies its
           text and link, so a free blog must not be walled 2.5s after a reader
           opens it. Absence is NOT exempt -- a removed tag returns above and a
           detached one fails -- and an edited credit still fails the content
           check after this returns. */
        var reading = false;
        try { reading = !!(document.body && document.body.classList.contains('rm-on')); } catch (e) {}
        if (reading) { return true; }
        if (tag.offsetParent === null) { return false; }
        try {
          var cs = window.getComputedStyle(tag);
          if (cs.display === 'none' || cs.visibility === 'hidden') { return false; }
        } catch (e) { /* an unreadable style is not proof of hiding */ }
        return true;
      }

      // BLG-C549: the content check, and it is the free edition ONLY.
      //
      // creditVisible() above answers "is there a visible credit element", and
      // that was the whole of the tamper test for years. It never looked at the
      // TEXT. So an owner who edited their own copy could set the studio name to
      // an empty string and render "A Creative Production by " with nothing after
      // it -- element present, visible, check green, no wall, no beacon. The same
      // hole takes a different name, or points the link somewhere else.
      //
      // What this compares is the rendered text against the credit the guard
      // BELIEVED it rendered, `liveCredit` -- not against the credit of record.
      // That distinction is deliberate and it is the limit of what this can do.
      // It catches every partial defeat: an emptied name, a swapped link, CSS
      // that keeps the element and drops the text, a footer edited by hand. It
      // does NOT catch an owner who rewrites the guard, because they rewrite this
      // function in the same keystroke. No client-side check ever will, because
      // the checked code and the checker are the same file. That gap is why the
      // Worker now also ATTESTS each blog by fetching it itself -- evidence the
      // owner does not get to write.
      //
      // The active branch is untouched and unreachable from here: creditVisible()
      // has already returned for a licensed blog, because removeFreeCredit()
      // took the element out on a licensed verdict. Nothing below runs for one.
      // One normaliser for every comparison below: trim, and collapse the
      // whitespace a template or a browser may have inserted. A declaration, not
      // a var-bound expression, so the guard's own "defines every function it
      // calls" check can see it.
      function creditText(s) { return String(s || '').replace(/\s+/g, ' ').trim(); }

      function creditContentIntact() {
        var tag = document.getElementById('meva-free-credit');
        if (!tag) {
          /* BLG-C556: BLG-C549 shipped this guard against a free edition only,
          and BLG-C517 gave creditVisible() the licensed exemption -- an active
          blog's footer is its OWN line, and the injected tag is absent BY
          DESIGN. The content check was never given the same shape, so every
          cached licensed view answered "false" for a footer that was never
          touched and walled it 2.5 seconds later: the stuck wall and the
          no-credit beacons this blog filed. An absent tag therefore asks the
          SAME question presence already asks, and the visible check owns the
          answer. */
          return creditVisible();
        }
        var link = tag.querySelector('.mcp-3 a');
        var text = (tag.querySelector('.mcp-3') || {}).textContent || '';
        // The studio name must be PRESENT and it must be the one we rendered.
        // An empty expected name is not a licence to render an empty one: the
        // Worker refuses a credit with neither prefix nor name, and the baked
        // fallback always carries both, so an empty expectation here means the
        // credit is already broken rather than that anything is excused.
        if (!liveCredit.name || creditText(text).indexOf(creditText(liveCredit.name)) === -1) { return false; }
        if (liveCredit.prefix && creditText(text).indexOf(creditText(liveCredit.prefix)) === -1) { return false; }
        if (!link) { return false; }
        if (liveCredit.url && creditText(link.getAttribute('href') || link.href) !== creditText(liveCredit.url)) { return false; }
        return true;
      }

      // The record of a defeated credit, and the wall that enforces restoring
      // it. No redirect: nobody is sent anywhere, because the only fix is on
      // this blog's own footer, and the wall carries that instruction.
      function reportTamper() {
        try { sessionStorage.setItem('meva_credit_tamper_' + TEMPLATE_ID, '1'); } catch (e) {}
        var url = API_URL + '?action=validate' +
          '&templateId=' + encodeURIComponent(TEMPLATE_ID) +
          '&domain=' + encodeURIComponent(location.hostname) +
          '&credit=missing';
        try {
          if (navigator.sendBeacon) { navigator.sendBeacon(url); }
          else { fetch(url, { method: 'GET', cache: 'no-store', keepalive: true }).catch(function () {}); }
        } catch (e) { /* the wall below is the enforcement; the beacon is the record */ }
        showOverlay();
      }

      // BLG-C530: THE SERIAL WALL. Same wall as the credit tamper above --
      // showOverlay() with different words -- because it is the same situation:
      // a shipped free-edition marker was removed and the blog must not run
      // without it. One wall, two reasons; a second overlay function would be
      // a second thing to keep styled, gated and translated.
      //
      // What it deliberately does NOT do: send a beacon. The credit tamper
      // beacons because its record attaches to a licence the server holds --
      // the Licences lookup shows the tamper against the blog. A free install
      // has no licence record to attach anything to, so a serial beacon would
      // need a new validate parameter, a new server counter and a new Serial
      // Manager surface, all to report something the wall already enforces:
      // a blog without its serial cannot run, so there is nothing to count.
      // The server already treats "no fes" as uncounted, which is exactly what
      // a locked blog sends. Observability without enforcement is a dashboard;
      // enforcement without observability is this wall, and it is enough.
      function reportSerialTamper(state) {
        try { sessionStorage.setItem('meva_serial_tamper_' + TEMPLATE_ID, '1'); } catch (e) {}
        var missing = state === 'missing';
        // Wrapped in `message`: that is the shape showOverlay() reads
        // (data.message.headline), and calling it any other way shows the
        // credit default -- a wall with the wrong words is worse than no
        // wall, because the owner follows the wrong instructions.
        showOverlay({
          message: {
            headline: missing ? 'Free serial missing' : 'Free serial changed',
            detail: missing
              ? 'The free-edition serial was removed from the Licence Activation gadget, so this blog is locked. Nothing is lost. Restore it: Blogger Layout, open the Licence Activation gadget, put the serial back into the release-serial line, Save, then press Recheck below. The serial is the value the template shipped with -- find it on the Serial Manager or in the project free-release.json.'
              : 'The free-edition serial in the Licence Activation gadget was changed to something that is not a release serial, so this blog is locked. Nothing is lost. Restore the shipped value: Blogger Layout, open the Licence Activation gadget, put the serial back into the release-serial line, Save, then press Recheck below. The serial is the value the template shipped with -- find it on the Serial Manager or in the project free-release.json.',
          },
        });
      }

      // Fingerprint of the OWNER'S copyright line. The guard replaces that
      // line with the free-edition credit, so the rendered text is not the
      // subject: the saved copy taken before the replacement is. Reading the
      // live text instead would fingerprint the guard's own credit -- and a
      // title or a year in it would read as a footer change every time either
      // moved. The first value an install ever sends becomes its reference.
      function copyrightFingerprint() {
        var el = document.querySelector('.copyright-ft .widget-content');
        if (!el) { return 'absent'; }
        var t;
        var saved = el.getAttribute ? el.getAttribute('data-meva-owner-line') : null;
        if (saved != null) {
          // The saved copy is markup; the fingerprint is of its text, which is
          // what a visitor reads and what a rebuild would alter.
          var box = document.createElement('div');
          box.innerHTML = saved;
          t = box.textContent || '';
        } else {
          t = el.textContent || '';
        }
        t = t.replace(/\s+/g, ' ').trim();
        var h = 0;
        for (var i = 0; i < t.length; i++) { h = ((h << 5) - h + t.charCodeAt(i)) | 0; }
        return 'c1:' + t.length + ':' + (h >>> 0).toString(36);
      }

      // The free-edition notice. It says what the blog is running and which blog
      // id it is, so the owner can copy that id and hand it to the author. It is
      // shown ONCE PER BROWSER (localStorage, not the session), it makes no ask,
      // and Dismiss is the only control. Nothing is blocked while it shows.
      function showFreeNotice(data) {
        if (!document.body) {
          document.addEventListener('DOMContentLoaded', function () { showFreeNotice(data); });
          return;
        }
        if (document.body.id === 'layout') { return; }
        try {
          if (localStorage.getItem('meva_free_seen_' + TEMPLATE_ID)) { return; }
        } catch (e) { /* private mode: show it */ }
        if (document.getElementById('meva-free-popup')) { return; }

        function onKey(e) { if (e.key === 'Escape' || e.keyCode === 27) { dismiss(); } }
        function dismiss() {
          try { localStorage.setItem('meva_free_seen_' + TEMPLATE_ID, '1'); } catch (e) {}
          document.removeEventListener('keydown', onKey);
          // BLG-C413: the touch listener goes with it, or it would fire against a
          // detached card and start calling dismiss on every tap for the session.
          document.removeEventListener('touchstart', outsideTouch, true);
          if (scrim.parentNode) { scrim.parentNode.removeChild(scrim); }
        }

        // BLG-C405. This used to be a fixed card in the bottom-right corner, and
        // measured on the live blog at 390x844 it covered the footer's Policy and
        // Terms box outright -- 374x228 at y600-828 against that box's y411-705 --
        // with body padding-bottom at 0, so no scroll position cleared it. The
        // notice is SKIPPABLE, so it belongs in the middle of the screen where it
        // covers nothing permanently, behind a dim the visitor can click through.
        // Every colour below is already in tests/palette-freeze.txt; that file is
        // an operator directive (2026-09-26), not a style preference, and a new
        // literal fails the build.
        // BLG-C413: the notice is a PARTIAL modal, and the difference is the platform.
        //
        // On a desktop the reader has a wheel, so the page underneath must stay
        // usable -- they should be able to scroll on past a notice that is not
        // about them. On a phone there is no wheel: the only way to scroll is to
        // touch, so a touch outside the card is the gesture that dismisses.
        //
        // Therefore the scrim is `pointer-events:none`: it dims, and it captures
        // nothing at all, so wheel scrolling and clicks reach the page below. The
        // card sets `pointer-events:auto` so its own controls still work, and a
        // CLICK anywhere is deliberately NOT a dismissal -- a reader reaching for
        // a link should get the link, not lose the notice. A touch outside the
        // card is, because on a phone that is the scroll gesture.
        //
        // "Remind later" remains the deliberate way to dismiss, and Escape still
        // works for the keyboard.
        var scrim = document.createElement('div');
        scrim.setAttribute('id', 'meva-free-scrim');
        scrim.style.cssText = 'position:fixed;left:0;top:0;right:0;bottom:0;' +
          'z-index:2147483645;background:rgba(0,0,0,0.3);pointer-events:none';
        // No scrim.onclick -- see above. A touch is handled on the document
        // instead, and only where there is no hover pointer to scroll with.
        var touchOnly = false;
        try {
          touchOnly = (window.matchMedia && window.matchMedia('(hover: none)').matches) ||
            ('ontouchstart' in window);
        } catch (e) { touchOnly = false; }
        var outsideTouch = function (ev) {
          if (ev.target === box || (box.contains && box.contains(ev.target))) { return; }
          dismiss();
        };

        var box = document.createElement('div');
        box.setAttribute('id', 'meva-free-popup');
        box.setAttribute('role', 'dialog');
        box.setAttribute('aria-modal', 'false');
        box.setAttribute('aria-labelledby', 'meva-free-title');
        box.style.cssText = 'position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);' +
          'z-index:2147483646;width:min(440px,calc(100% - 32px));background:#0b1d27;' +
          'border:1px solid rgba(255,255,255,0.1);border-radius:14px;overflow:hidden;' +
          'box-shadow:0 24px 60px rgba(0,0,0,.7);color:#d9e9f0;' +
          'font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;' +
          // The card opts back IN to pointer events, because its scrim opts out.
          // Without this the buttons inside it would be unclickable.
          'pointer-events:auto';

        var bar = document.createElement('div');
        bar.style.cssText = 'height:4px;background:#288047';

        var head = document.createElement('div');
        head.style.cssText = 'display:flex;align-items:center;gap:10px;padding:18px 22px 0';
        var h = document.createElement('strong');
        h.setAttribute('id', 'meva-free-title');
        h.style.cssText = 'font-size:17px;font-weight:700;color:#05c645';
        h.textContent = 'Free edition';
        head.appendChild(h);
        var sub = document.createElement('div');
        sub.style.cssText = 'padding:2px 22px 0;font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:#8fafbf';
        sub.textContent = TEMPLATE_LABEL;

        var d = document.createElement('p');
        d.style.cssText = 'margin:10px 22px 0;font-size:14.5px;line-height:1.55;color:#d9e9f0';
        d.textContent = 'This blog is running the free edition of ' + TEMPLATE_NAME + '. ' +
          'Everything works and nothing is blocked from working online; only the footer credit stays in place.';

        // BLG-C406. Say who this is for, in the notice itself. An owner who
        // cannot tell whether a popup is meant for them treats it as a fault
        // report; a visitor who wanders onto the owner's blog should read it as
        // not about them. Nothing is blocked either way -- the site renders.
        var who = document.createElement('p');
        who.style.cssText = 'margin:8px 22px 0;font-size:13px;line-height:1.5;color:#8fafbf';
        who.textContent = 'This notice is for the site owner. Visitors see the site ' +
          'normally.';

        // The blog id is shown MASKED on screen -- a partial id is enough to
        // recognise the blog, and the screen is where screenshots and
        // shoulders live. The COPY is unrestricted: the button copies the FULL
        // id every time, because the full value is what the owner quotes to
        // activate, and a control that works once is a control that fails.
        // The full value is only ever in the clipboard, never on the screen.
        // It is not a credential: no licence, no email and no secret travels
        // with it -- the blogId is this blog's own public identifier,
        // published in its feed and returned by the API.
        var fullId = String(data.blogId || '');

        var meta = document.createElement('div');
        meta.style.cssText = 'margin:16px 22px 0;padding:12px 14px;border-radius:10px;' +
          'background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.1)';
        // The box shows ONLY the blog id. Theme and designer live in the
        // notice title and body above -- the box is the one thing the owner
        // must act on, so it holds nothing else.
        var ml = document.createElement('div');
        ml.style.cssText = 'font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:#8fafbf';
        ml.textContent = 'your blog id';
        var idRow = document.createElement('div');
        idRow.style.cssText = 'margin-top:3px;display:flex;align-items:center;gap:10px';
        var mv = document.createElement('div');
