              (function () {
                var cap = 15;                 // the operator's label cap
                // chip-shaped widths for the no-labels row: the variety is the
                // point, so the placeholders do not read as clones of one box
                var bare = [76, 116, 88, 136];

                function padLabelRow() {
                  var box = document.querySelector('#news-modal .nm-chips');
                  // while the dialog is hidden every offsetTop measures 0,
                  // which is the bug C229 shipped; wait for a laid out box
                  if (!box || !box.offsetWidth) { return; }

                  // idempotent: a second open must not double the padding
                  var stale = box.querySelectorAll('a.nm-chip-empty');
                  for (var s = 0; s < stale.length; s++) {
                    if (stale[s].parentNode) { stale[s].parentNode.removeChild(stale[s]); }
                  }

                  // order by popularity, most used first; ties keep their
                  // markup order, and a missing count simply counts as 0
                  var chips = box.querySelectorAll('a:not(.nm-chip-empty)');
                  var order = [];
                  for (var i = 0; i < chips.length; i++) {
                    var n = parseInt(chips[i].getAttribute('data-count'), 10);
                    order.push({ el: chips[i], n: isNaN(n) ? 0 : n, i: i });
                  }
                  order.sort(function (a, b) { return (b.n - a.n) || (a.i - b.i); });

                  // keep the first 15 on show, park the rest inline (the
                  // author stylesheet would beat the hidden attribute), and
                  // rewrite the DOM in the sorted order; the parked chips past
                  // the cap are the pool fill() draws from (BLG-C179)
                  var visible = [], hidden = [];
                  for (var k = 0; k < order.length; k++) {
                    order[k].el.style.display = k < cap ? '' : 'none';
                    if (k < cap) { visible.push(order[k].el); }
                    else { hidden.push(order[k].el); }
                    box.appendChild(order[k].el);
                  }

                  // rowTop is where the first row starts, and widths are the real chip widths
                  // the placeholders copy. The first chip BELOW that top edge
                  // used to be found here and handed over as the insert-before
                  // anchor; BLG-C183 moved that into fill(), because promoting
                  // a label changes which chip is first on the second row and a
                  // stale anchor would drop the next candidate at the wrong end
                  var rowTop = -1, widths = bare;
                  if (visible.length) {
                    rowTop = visible[0].offsetTop;
                    widths = [];
                    var seen = {};
                    for (var v = 0; v < visible.length; v++) {
                      widths.push(visible[v].offsetWidth);
                      seen[visible[v].offsetWidth] = 1;
                    }
                    // one real width gives no variety, so fall back to the
                    // pattern; two or more and the placeholders take the
                    // widths of the labels actually around them
                    if (Object.keys(seen).length < 2) { widths = bare; }
                  }
                  fill(box, rowTop, widths, hidden);
                }

                /* One slot at a time, each measured after it lands: the
                   container is not exactly the width that was measured, so
                   predicting the room puts chips on the wrong row.

                   BLG-C179: a slot tries a hidden label FIRST (real labels beat
                   empty cards), moved before the first placeholder or the
                   anchor and shown; it keeps the place only if it lands on the
                   measured row, and otherwise goes back to hidden for a
                   narrower one to try next. Only when no label took the slot
                   does the skeleton run, trying the widths until one stays on
                   the row, and when neither fits the row is full. rowTop is -1
                   only in the no-labels case, where there are no hidden labels
                   and the first placeholder defines the row itself.

                   BLG-C183: the operator reported the one case this got wrong,
                   with a screenshot: an empty dashed chip sat at the end of the
                   FIRST row while six real labels sat on the second, and the
                   question was why the empty one was drawn at all. Two causes,
                   both here. The pool was only the labels parked past the cap,
                   so a label already on show that had wrapped to a later row
                   was never even offered to the gap, even though pulling it up
                   is exactly what the reader expects; and when nothing fitted,
                   the skeleton ran anyway, so the row claimed to be waiting for
                   a label while the labels were already on screen. Two changes:

                   1. The pool is now two deep. Parked labels first, as before,
                      then the labels already on show that are not on the first
                      row, in popularity order, so the promoted label lands at
                      the end of the first row and never jumps ahead of a
                      more-used one. The first row and the anchor are re-read
                      every pass, because promoting one label moves every label
                      after it.
                   2. An empty chip is a "waiting" mark, so it is only honest
                      while there is genuinely nothing left to show. If any real
                      label is still parked, or still sits on a later row, the
                      gap stays a gap and the loop stops. The skeleton therefore
                      still pads a row that holds every label there is, which is
                      the C179 look, and still builds the no-labels row. */
                function fill(box, rowTop, widths, hidden) {
                  var tried = [], slots = 0;
                  function untried(pool) {
                    for (var p = 0; p < pool.length; p++) {
                      if (tried.indexOf(pool[p]) < 0) { return true; }
                    }
                    return false;
                  }
                  while (slots < 12) {
                    // re-read the first row every pass: promoting a label moves
                    // everything after it, so the row it lands on is only known
                    // after the move
                    var chips = box.querySelectorAll('a:not(.nm-chip-empty)');
                    var top = -1, anchor = null, later = 0;
                    for (var i = 0; i < chips.length; i++) {
                      if (chips[i].style.display === 'none') { continue; }
                      if (top < 0) { top = chips[i].offsetTop; }
                      if (chips[i].offsetTop !== top) {
                        if (!anchor) { anchor = chips[i]; }
                        later++;
                      }
                    }
                    if (top < 0) { top = rowTop; }   // nothing on show at all

                    // a real label before an empty one, parked ones first
                    var cand = null, wasShown = true;
                    for (var h = 0; h < hidden.length && !cand; h++) {
                      if (tried.indexOf(hidden[h]) < 0) { cand = hidden[h]; }
                    }
                    if (cand) { wasShown = false; }
                    for (var v = 0; v < chips.length && !cand; v++) {
                      if (chips[v].style.display === 'none') { continue; }
                      if (chips[v].offsetTop !== top && tried.indexOf(chips[v]) < 0) {
                        cand = chips[v];
                      }
                    }
                    if (cand) {
                      tried.push(cand);
                      var mark = box.querySelector('a.nm-chip-empty');
                      var home = cand.nextSibling;
                      if (mark) { box.insertBefore(cand, mark); }
                      else if (anchor) { box.insertBefore(cand, anchor); }
                      else { box.appendChild(cand); }
                      cand.style.display = '';
                      if (cand.offsetTop === top) { slots++; continue; }
                      // it does not fit the gap: put it back where it was, so a
                      // rejected promotion leaves the row exactly as it found it
                      if (mark && mark.parentNode === box) { box.insertBefore(cand, mark); }
                      else if (anchor && anchor.parentNode === box) { box.insertBefore(cand, anchor); }
                      else if (home && home.parentNode === box) { box.insertBefore(cand, home); }
                      else { box.appendChild(cand); }
                      if (!wasShown) { cand.style.display = 'none'; }
                    }

                    // nothing real is left to show, so padding the gap is honest
                    if (later > 0 || untried(hidden)) { break; }

                    // no label took it: a skeleton in the remaining room
                    var placed = false;
                    for (var t = 0; t < widths.length && !placed; t++) {
                      var el = document.createElement('a');
                      el.className = 'nm-chip-empty';
                      el.setAttribute('aria-hidden', 'true');
                      el.setAttribute('tabindex', '-1');
                      el.textContent = ' ';
                      el.style.width = widths[(slots + t) % widths.length] + 'px';
                      if (anchor) { box.insertBefore(el, anchor); }
                      else { box.appendChild(el); }
                      if (top < 0) {
                        top = el.offsetTop;
                        placed = true;
                      } else if (el.offsetTop === top) {
                        placed = true;
                      } else {
                        // that width wrapped: take it back and try the next
                        if (el.parentNode) { el.parentNode.removeChild(el); }
                      }
                    }
                    if (!placed) { break; }   // neither a label nor a skeleton fits
                    slots++;
                  }
                }
                var modal = document.getElementById('news-modal');
                if (!modal) { return; }
                // UIkit 3 dispatches the event name alone, on the dialog:
                // "show" as it opens, "shown" once the open has settled
                modal.addEventListener('show', padLabelRow);
                modal.addEventListener('shown', padLabelRow);
                // and once on load, for the case where the dialog is somehow
                // already visible; normally the guard above makes it a no-op
                if (document.readyState !== 'loading') { padLabelRow(); }
                else { document.addEventListener('DOMContentLoaded', padLabelRow); }
              })();
