  // "Terms and Conditions" to "Terms and..." in the DOM while the H1
  // and the JSON-LD kept the full title (AUD-L04, verified live).
  // Overflow is handled by the a.current ellipsis rule in the skin,
  // which clamps visually without lying to crawlers.
});
})(jQuery);
//

b:includable.script:
(function() {
  var items = ;
  var msgs = ;
  var config = ;

  // 
  var cursor = null;
  if (items && items.length > 0) {
    cursor = parseInt(items[items.length - 1].timestamp) + 1;
  }

  var bodyFromEntry = function(entry) {
    if (entry.gd$extendedProperty) {
      for (var k in entry.gd$extendedProperty) {
        if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
          return '<span class="deleted-comment">' + entry.content.$t + '</span>';
        }
      }
    }
    return entry.content.$t;
  }

  var parse = function(data) {
    cursor = null;
    var comments = [];
    if (data && data.feed && data.feed.entry) {
      for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
        var comment = {};
        // comment ID, parsed out of the original id format
        var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
        comment.id = id ? id[2] : null;
        comment.body = bodyFromEntry(entry);
        comment.timestamp = Date.parse(entry.published.$t) + '';
        if (entry.author && entry.author.constructor === Array) {
          var auth = entry.author[0];
          if (auth) {
            comment.author = {
              name: (auth.name ? auth.name.$t : undefined),
              profileUrl: (auth.uri ? auth.uri.$t : undefined),
              avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
            };
          }
        }
        if (entry.link) {
          if (entry.link[2]) {
            comment.link = comment.permalink = entry.link[2].href;
          }
          if (entry.link[3]) {
            var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
            if (pid && pid[1]) {
              comment.parentId = pid[1];
            }
          }
        }
        comment.deleteclass = 'item-control blog-admin';
        if (entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
              comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
            } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
              comment.displayTime = entry.gd$extendedProperty[k].value;
            }
          }
        }
        comments.push(comment);
      }
    }
    return comments;
  };

  var paginator = function(callback) {
    if (hasMore()) {
      var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
      if (cursor) {
        url += '&published-min=' + new Date(cursor).toISOString();
      }
      window.bloggercomments = function(data) {
        var parsed = parse(data);
        cursor = parsed.length < 50 ? null
        : parseInt(parsed[parsed.length - 1].timestamp) + 1
        callback(parsed);
        window.bloggercomments = null;
      }
      url += '&callback=bloggercomments';
      var script = document.createElement('script');
      script.type = 'text/javascript';
      script.src = url;
      document.getElementsByTagName('head')[0].appendChild(script);
    }
  };
  var hasMore = function() {
    return !!cursor;
  };
  var getMeta = function(key, comment) {
    if ('iswriter' == key) {
      var matches = !!comment.author
      && comment.author.name == config.authorName
      && comment.author.profileUrl == config.authorUrl;
      return matches ? 'true' : '';
    } else if ('deletelink' == key) {
      return config.baseUri + '/delete-comment.g?blogID='
      + config.blogId + '&postID=' + comment.id;
    } else if ('deleteclass' == key) {
      return comment.deleteclass;
    }
    return '';
  };

  var replybox = null;
  var replyUrlParts = null;
  var replyParent = undefined;

  var onReply = function(commentId, domId) {
    if (replybox == null) {
      // lazily cache replybox, and adjust to suit this style:
      replybox = document.getElementById('comment-editor');
      if (replybox != null) {
        replybox.height = '250px';
        replybox.style.display = 'block';
        replyUrlParts = replybox.src.split('#');
      }
    }
    if (replybox && (commentId !== replyParent)) {
      replybox.src = '';
      document.getElementById(domId).insertBefore(replybox, null);
      replybox.src = replyUrlParts[0]
      + (commentId ? '&parentID=' + commentId : '')
      + '#' + replyUrlParts[1];
      replyParent = commentId;
    }
  };

  var hash = (window.location.hash || '#').substring(1);
  var startThread, targetComment;
  if (/^comment-form_/.test(hash)) {
    startThread = hash.substring('comment-form_'.length);
  } else if (/^c[0-9]+$/.test(hash)) {
    targetComment = hash.substring(1);
  }

  // Configure commenting API:
  var configJso = {
    'maxDepth': config.maxThreadDepth
  };
  var provider = {
    'id': config.postId,
    'data': items,
    'loadNext': paginator,
    'hasMore': hasMore,
    'getMeta': getMeta,
    'onReply': onReply,
    'rendered': true,
    'initComment': targetComment,
    'initReplyThread': startThread,
    'config': configJso,
    'messages': msgs
  };

  var render = function() {
    if (window.goog && window.goog.comments) {
      var holder = document.getElementById('comment-holder');
      window.goog.comments.render(holder, provider);
    }
  };

  // render now, or queue to render when library loads:
  if (window.goog && window.goog.comments) {
    render();
  } else {
    window.goog = window.goog || {};
    window.goog.comments = window.goog.comments || {};
    window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
    window.goog.comments.loadQueue.push(render);
  }
})();
//

div.script:
//
// BLG-C158: put the section in the drawer the social icon opens. Same
// contract as the script that used to sit right after </header>: skip
// entirely in the Layout editor (the section must stay in its header
// cell), otherwise move it into the drawer bar while the document is
// still parsing, ahead of UIkit's toggle binding and ahead of the icon
// script that appends the row labels. The slot cell it moves out of is
// hidden on the front end by
// body:not(#layout) #header .cp-hd-social-slot, so the header row keeps
// its three cells whether or not this runs.
(function () {
  if (document.getElementById('layout')) return;
  var slot = document.getElementById('Social Network Header');
  var panel = document.querySelector('#offcanvas-social .uk-offcanvas-bar');
  if (slot && panel && slot.parentNode !== panel) panel.appendChild(slot);
})();
// BLG-C163: drive the reading-progress line. Two targets, because a
// single bar has to mean something on every page: on a post or a page it
// measures the article, and everywhere else it measures the document. A
// post page is recognised by the breadcrumb the theme prints on single
// items (.uk-breadcrumb .current) -- Blogger's own body classes are not
// emitted by this template, so the view type cannot be read off <body>.
//
// The article measure is 0% when the article's top meets the top of the
// viewport and 100% when its bottom meets the bottom, which is the
// reading position rather than the visible fraction: a first attempt
// measured how much of the article was on screen and reached 100% at 55%
// page scroll, because most of a short post is taller than the fold but
// not taller than the window. An article shorter than the window cannot
// be scrolled through, so it goes straight to 100% once its top passes.
//
// Work is done in requestAnimationFrame and the width is written as a
// transform, so a scroll never triggers layout. The line is re-measured
// after load, because late images change the article's height and the
// document's, and a bar that trusted the first measurement would lie for
// the rest of the visit.
(function () {
  var bar = document.querySelector('.cp-read > i');
  if (!bar) return;
  var article = document.querySelector('.uk-breadcrumb .current') ?
    document.querySelector('.post-body.entry-content') : null;
  var ticking = false;
  function measure() {
    ticking = false;
    var p;
    if (article) {
      var box = article.getBoundingClientRect();
      var top = box.top + window.pageYOffset;
      var span = box.height - window.innerHeight;
      p = span <= 0 ? (window.pageYOffset >= top ? 1 : 0) : (window.pageYOffset - top) / span;
    } else {
      var max = document.documentElement.scrollHeight - window.innerHeight;
      p = max <= 0 ? 1 : window.pageYOffset / max;
    }
    if (p < 0) p = 0;
    if (p > 1) p = 1;
    bar.style.transform = 'scaleX(' + p.toFixed(4) + ')';
  }
  function onScroll() {
    if (ticking) return;
    ticking = true;
    window.requestAnimationFrame(measure);
  }
  window.addEventListener('scroll', onScroll, {passive: true});
  window.addEventListener('resize', onScroll, {passive: true});
  window.addEventListener('load', onScroll);
  measure();
})();
//

body.script:
//
// Page control keywords (BLG-C030 + BLG-C031): the "Page Width Control"
// gadget (offcanvas bottom) is a keyword-driven per-page config surface.
// Find the gadget link whose URL matches the current page, then read its
// title keywords: "width-expand" hides the sidebar (main column fills the
// grid), "no-comments" hides the comments block. Both are independent --
// either or both may appear in the title. No matching link => nothing is
// hidden (normal two-column layout + comments stay).
// BLG-C495: the direction is INVERTED. The skin now hides the sidebar
// and the comments block on every page view (see the data:view.isPage
// block), so this script's job is to RESTORE them for a page that should
// keep them. Previously it hid them, which meant the correct state was
// reached by a script thousands of lines after <body> and the reader saw
// the sidebar appear and vanish on every navigation.
//
// Restoring is done by clearing the inline display the stylesheet set, not
// by removing a class: a page the owner asked to be full width therefore
// keeps it, and there is no path here that can reveal a sidebar by mistake.
(function () {
  function applyPageOptions() {
    var current = location.pathname || "";
    var links = document.querySelectorAll('.full-width-control .widget-content a');
    var label = null;
    for (var i = 0; i < links.length; i++) {
      var href = links[i].getAttribute("href") || "";
      try {
        var url = new URL(href, location.origin);
        if (url.pathname === current) { label = links[i].textContent || ""; break; }
      } catch (e) {}
    }
    // Only a page view carries the full-width layout block, and that block
    // is the discriminator for everything below. It has to be: `label`
    // is null both for an unlisted page AND for every post view, because
    // no gadget link matches a post URL. Keying anything off `label`
    // alone would therefore run it on post views too.
    var fwBlock = document.getElementById('cp-full-width-layout');
    if (!fwBlock) return;

    // BLG-C497: a page that stays full width keeps its share buttons as a
    // horizontal row, and a row must not stick. The list carries UIkit
    // sticky (`uk-sticky='media: @s; bottom: #end-social'`) for the
    // post-view COLUMN, where a floating share rail running down the
    // article is the point -- so this is gated on being a page view, and
    // on staying full width, and it leaves post views alone entirely.
    // As a full-width row it does something else: measured live, scrolled
    // 900px, it takes `position: fixed !important; top: 0; z-index: 980`
    // and sits across the top of the viewport covering the headings.
    // CSS cannot undo that -- UIkit sticks it with inline !important
    // styles, which beat any stylesheet rule -- so the component is
    // destroyed, which removes the inline styles and the placeholder.
    // Verified live: after $destroy the list is position:static and
    // scrolls away with the page, and the only sticky placeholder left in
    // the document is the header's, which should stay sticky.
    // Both bases are covered on purpose: $destroy if UIkit has already
    // created the component, and removing the attribute so it never does.
    if (label === null || label.indexOf("width-expand") !== -1) {
      var socialList = document.querySelector('.post-social ul');
      if (socialList) {
        if (window.UIkit && UIkit.getComponent) {
          var stickyComp = UIkit.getComponent(socialList, 'sticky');
          if (stickyComp && stickyComp.$destroy) stickyComp.$destroy();
        }
        socialList.removeAttribute('uk-sticky');
      }
    }

    // A page with no row at all is NOT a page view in the sense the skin
    // defaulted for, so it is left exactly as the stylesheet set it.
    if (label === null) return;

    if (label.indexOf("width-expand") === -1) {
      // BLG-C496: the skin emits the one-column full-width layout for every
      // page view, and a page that keeps its sidebar must opt out of it, or
      // its title and body would sit on the full-width axis beside a
      // sidebar and look worse than either arrangement on its own. One
      // disabled style element over the whole rule set, rather than five
      // inline styles to undo and five chances to miss one.
      fwBlock.disabled = true;
      var side = document.querySelector('.sidebar-container');
      if (side) side.style.display = '';
    }
    if (label.indexOf("no-comments") === -1) {
      var comments = document.getElementById('comments');
      if (comments) comments.style.display = '';
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyPageOptions);
  } else {
    applyPageOptions();
  }
})();
//

//
// BLG-C475: "Page 1 of 0" under an empty post list.
//
// A Blog widget with no posts renders Blogger's own empty state ("No
// posts.") and then a pager reading "Page 1 of 0" -- a page count out of
// no pages. The empty state is correct and stays; the pager is arithmetic
// nobody can act on, and it was the only thing on the testing blog's
// Recent Post card that read as broken.
//
// Read from the rendered text rather than from data, because "no posts"
// is not a template state we can branch on: the same markup serves a blog
// with posts and one without. Only a total of exactly zero is removed, so
// a real pager on a real blog is never touched.
// BLG-C483: "Page 1 of 0" is back, and BLG-C475's fix ran too early to
// catch it. It hooked DOMContentLoaded -- but on this theme Blogger does
// not write the pager's ".showpageOf" label until the window load event.
// Measured on the live blog:
//
//   DOMContentLoaded  .blog-pager = 1   .showpageOf = 0
//   load              .blog-pager = 1   .showpageOf = 1  "Page 1 of 0"
//
// So the function ran, found the pager, found no label inside it, matched
// nothing, and returned having done nothing. The gate passed because it
// only checked that dropEmptyPager() EXISTED.
//
// Two events, not one: DOMContentLoaded for a server-rendered pager, and
// load for the label that arrives with it. Plus an observer, because a
// category page can append its pager after both -- without it the same
// defect returns one page type later.
(function () {
  function dropEmptyPager() {
    var pagers = document.querySelectorAll('.blog-pager');
    for (var i = 0; i < pagers.length; i++) {
      var labels = pagers[i].querySelectorAll('.showpageOf');
      for (var j = 0; j < labels.length; j++) {
        if (/\bof\s*0\s*$/i.test((labels[j].textContent || '').trim())) {
          if (pagers[i].parentNode) { pagers[i].parentNode.removeChild(pagers[i]); }
          break;
        }
      }
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', dropEmptyPager);
  } else {
    dropEmptyPager();
  }
  window.addEventListener('load', dropEmptyPager);
  if (window.MutationObserver && document.body) {
    new MutationObserver(dropEmptyPager).observe(document.body, {
      childList: true, subtree: true
    });
  }
})();
//

//
// Newsletter endpoint (BLG-C126), following the BLG-C030/C031/C032
// control-gadget pattern. The sidebar Newsletter form (HTML14) ships inert:
// onsubmit='return false', no action (BLG-C023), so no backend URL travels
// to a rebrand. The hidden offcanvas "Newsletter Setup" gadget (LinkList7)
// is where the OWNER supplies their live form endpoint from Layout:
//   - link whose title contains "newsletter-endpoint" -> its URL becomes
//     the form's action, and onsubmit='return false' is removed so the
//     form actually submits to that endpoint
//   - link whose title contains "newsletter-target"    -> forms submit in a new tab
// Empty / no keyword / no match => the form stays exactly as shipped
// (inert). Nothing here ships a URL; the endpoint is typed in Layout.
(function () {
  function wireNewsletter() {
    var form = document.querySelector('.newsletter-side-form');
    if (!form) return;
    var links = document.querySelectorAll('.newsletter-control .widget-content a');
    for (var i = 0; i < links.length; i++) {
      var t = links[i].textContent || '';
      var href = links[i].getAttribute('href') || '';
      if (t.indexOf('newsletter-endpoint') !== -1 && href) {
        form.action = href;
        form.removeAttribute('onsubmit');
      }
      if (t.indexOf('newsletter-target') !== -1) {
        form.target = '_blank';
      }
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', wireNewsletter);
  } else {
    wireNewsletter();
  }
})();
//

//
// One escaper for every place this theme builds markup by string
// concatenation and hands it to .html(): the pager, the feed blocks and
// the mega menu. It is UNCONDITIONAL and NOT deferred on purpose. It used
// to live inside the pager's b:if, which renders only on list views -- so
// on a post page the function did not exist while the feed blocks still
// ran. The entity names are BUILT, never written literally: check-js
// simulates the browser by un-escaping &lt; &gt; &amp; &quot; &#39; in
// script bodies, which turns a literal '&#39;' into ''' and breaks the
// parse. String.fromCharCode(38) keeps every ampersand out of the source
// while emitting the same bytes.
function esc(s){var A=String.fromCharCode(38);return String(s==null?'':s).split(A).join(A+'amp;').replace(/\x3C/g,A+'lt;').replace(/\x3E/g,A+'gt;').replace(/"/g,A+'quot;').replace(/'/g,A+'#39;');}
//

  //	


  // --------------- Primary Navigation  --------------- //
  // AUD-L05: `level` and `offset` were implicit globals, and `navContainer`
  // was built on every pass and never read. Both are gone: the two locals
  // are declared, and the markup the .html() call installs is built only in
  // navMenu. That string also closes the <nav> it opens, instead of leaning
  // on a stray </div> and the parser's error recovery to balance it.
  var navLevel = -1,
      navMenu = "";
  // BLG-C495: drop navigation entries that point at a page already in the
  // menu. A Blogger upload MERGES widget rows with the ones stored on the
  // blog, so a row removed from the XML can survive on the page and the
  // menu renders the same item twice -- the file is correct, the page is
  // not, and no repository gate can see it. Keeps the FIRST occurrence: the
  // stale row is always the later one, and first-wins keeps the position the
  // owner chose and the underscore depth that drives submenu nesting.
  (function () {
    var seen = Object.create(null);
    $(".nav-hd #LinkList1").find("ul").find("li").each(function () {
      var href = ($(this).find("a").attr("href") || "").trim();
      if (!href) return;                       // an entry with no target is
      if (seen[href]) { $(this).remove(); return; }   // not ours to judge
      seen[href] = true;
    });
  })();
  $(".nav-hd #LinkList1").find("ul").find("li").each(function () {
    var level, offset;
    for (var navText = $(this).text(), navLink = $(this).find("a").attr("href"), i =
         0, l = 0; l < navText.length && (i = navText.indexOf("_", i), -1 != i); l++)
      i++;
    if (level = l, level > navLevel && (navMenu += "<ul>"), level < navLevel) {
      offset = navLevel - level;
      for (var l = 0; l < offset; l++) navMenu += "</ul></li>";
    }
    navText = navText.replace(/_/gi, ""), navMenu += "<li><a href='" + navLink + "'>";
    for (var l = 0; l < level; l++) navMenu += "";
    navMenu += navText + "</a>", navLevel = level
  });
  for (var i = 0; navLevel >= i; i++) navMenu += "</ul>", 0 != i && (navMenu += "</li>");
  $(".nav-hd").html("<nav class='nav-header'>" + navMenu + "</nav>"), $(".nav-hd ul li ul").parent("li").addClass("uk-parent").append('<span class="icon-parent" uk-icon="icon: chevron-down; ratio: 0.6"></span>'); 


  $(".nav-header ul li").each(function() {
    var e = $(this).find("a").text();
    if (e.substr(0, 5).match("mega/")) {
      var t = e.replace("mega/", "");
      $(this).find("a").text(t), $(this).addClass("mega-menu"), $(this).append('<div class="mega-container uk-position-absolute"><div class="mega-menu-loader"><div class="sk-menu"><span class="sk sk-link" style="width:72%"></span><span class="sk sk-link" style="width:58%"></span><span class="sk sk-link" style="width:86%"></span><span class="sk sk-link" style="width:64%"></span><span class="sk sk-link" style="width:78%"></span><span class="sk sk-link" style="width:52%"></span></div></div></div>'), $(this).append('<span class="icon-parent icon-mega uk-icon" uk-icon="icon: chevron-down; ratio: 0.6"></span>');
      var a = $(this).find("a").attr("href"),
          n = a.replace("/search/label/", "");
      // BLG-C101: C099 replaced this with <data:blog.homepageUrl.jsonEscaped/>
      // on the belief that Blogger substitutes its data tags inside a <script>
      // block. It does not. Measured on the live site: the tag was emitted
      // literally, URL-encoded, into every mega menu feed URL, each one 404'd,
      // and jQuery's JSONP then tried to eval Blogger's HTML error page --
      // "Uncaught SyntaxError: ... Unexpected token '<'" -- which the browser
      // reports as a failure with no message, so the loader spinner stayed up
      // forever with an empty panel. The data tag works in JSON-LD, which is
      // why it looked fine when the file was read, but never in a <script>.
      // Restored to the original theme's own form (References/ LTR theme):
      //   furl = ''+ domain +'/feeds/posts/summary?...'
      // with domain="" -- a root-relative path the BROWSER resolves against
      // the origin it is already on, so it is blog-independent by
      // construction. The leading slash is load-bearing: without it the
      // concatenation below is relative to the current directory and a post
      // at /2025/10/post.html would request /2025/10/feeds/... and 404.
      var megaBlogUrl = '/';
      $(this).each(function() {
        $.ajax({
          url: megaBlogUrl + "feeds/posts/default/-/" + n + "?alt=json-in-script&max-results=4",
          type: "get",
          dataType: "jsonp",
          success: function(json) {
            // BLG-C099: mirror the C027 guard from blockfeeds(). A label
            // feed with no posts comes back with no `entry` at all, so
            // reading .length on it threw and took down the whole menu.
            var megaEntries = (json && json.feed && json.feed.entry) ? json.feed.entry : [];
            // BLG-C438: a mega menu with NO posts must not render at all --
            // C229's rule, extended from the feed blocks to the nav panel.
            // C099 let the empty grid close below so the spinner cleared,
            // which replaced "spinning forever" with a panel that opens on
            // hover and shows nothing: the zero-iteration wrapper still
            // carries .post-entry-15, and that class alone paints the white
            // padded shadowed box (its background/padding/box-shadow belong
            // to the wrapper, not to the items). Seen live on a fresh blog:
            // hovering POLITICS dropped an empty white rectangle. So the
            // empty case now removes the whole mega affordance -- panel,
            // caret, class -- and leaves a plain working link to the label
            // page. The item upgrades back to a mega menu automatically on
            // the next page load once the label has posts.
            if (megaEntries.length === 0) {
              $(".nav-header ul li").each(function() {
                var e = $(this).find("a").attr("href");
                e == a && ($(this).find(".mega-container").remove(), $(this).find(".icon-mega").remove(), $(this).removeClass("mega-menu"));
              });
              return;
            }
            for (var t = "", n = '<div class="post-entry post-ft  post-entry-10 post-entry-15"><div uk-grid="">', r = 0; r < megaEntries.length; r++) {
              // FJS-07: cleared for each entry for the same reason as `link`
              // in the feed loop below -- it is assigned only when the entry
              // carries an alternate link, so a stale value would be escaped
              // twice.
              t = "";
              for (var s = 0; s < megaEntries[r].link.length; s++)
                if ("alternate" == megaEntries[r].link[s].rel) {
                  t = megaEntries[r].link[s].href;
                  break
                }
              var postTitle = megaEntries[r].title.$t;
              var postThumbSize = 300;
              var authorImg = " ";
              var postThumb = " ";
              postThumb = postThumb.replace('/s72-c/', '/s' + postThumbSize + '/');
              var postCategory = " ";
              var date = megaEntries[r].published.$t;
              try {
                postThumb = megaEntries[r].media$thumbnail.url;
} catch (nl) {
  // BLG-C108: this pointed at a noimg hosted on the ORIGINAL THEME AUTHOR'S
  // own blog. Every reader of a rebranded install fetched an image from a
  // stranger's server on every image-less post -- a privacy leak, a branding
  // leak, and a broken image the day that blog is deleted. Empty now, so the
  // card falls back to the surface the theme already paints on an empty
