        { id: 'short',           f: function (p) { return tfmMonthAbbr[p.mo] + ' ' + p.d + ' ' + p.y; } },
        { id: 'fullDayLong',     f: function (p) { return tfmDayFull[(new Date(p.y, p.mo, p.d)).getDay()] + ', ' + tfmMonthFull[p.mo] + ' ' + p.d + ', ' + p.y; } },
