              // access back. They stay <a>, not <button>, deliberately: `.pager-nav a` is
              // the selector the skin styles them with, and switching element would leave
              // the arrows unstyled. The BLOG pager's own javascript:void(0) links are a
              // different string and are still required by check-feed-guards check 12;
              // nothing here touches them.
              var nextNav = '<a role="button" tabindex="0" uk-slider-item="next" aria-label="Next"><span uk-icon="triangle-right"></span></a>',
                  prevNav = '<a role="button" tabindex="0" uk-slider-item="previous" aria-label="Previous"><span uk-icon="triangle-left"></span></a>',
                  pagerNav = '<div class="pager-nav bg-grd uk-position-absolute">'+ prevNav +''+ nextNav +'</div>'; // BLG-C307: the two icon-only slider arrows had no accessible name (link-name, serious live on the related-posts block); UIkit's uk-icon gives the span no text, so each arrow now carries an aria-label.


              switch(style) {
case 'breakingnews':
// BLG-C186: the hyphenated spelling, same reason as the relatedposts alias
case 'breaking-news':
case 'related-posts':
// BLG-C186: the hyphen-less spelling, closing tag side
case 'relatedposts':
htmlcode += '</div>' + pagerNav + '</div>';
break;
                default:
                  break;
              }

              // Print as HTML
              parent.html(htmlcode);

                  // BLG-C229: a section with NO posts must not render at all.
                  // The padding above is for a feed that is SHORT, where the row
                  // keeps its shape and the missing positions read as "a card
                  // waiting for a story". With nothing at all that reasoning
                  // inverts: four dashed boxes under a heading is worse than
                  // either a void or content, because it looks like the feed
                  // failed rather than like the blog having nothing to say.
                  //
                  // The heading is static template markup, a SIBLING of the row
                  // this script fills, so hiding the row alone would leave a
                  // bare "Breaking now" with nothing under it. The class goes on
                  // the nearest scope that owns BOTH the heading and the list:
                  // .nm-col where there is one, so an empty Most-viewed column
                  // does not take its neighbour down with it, and .nm-band
                  // otherwise, which is the Breaking row's shape.
                  if (inNewsModal && nmCards === 0) {
                    // Same defect C233 hit on the breaking strip, and it has been
                    // here since C229: .closest() returns jQuery, so .classList was
                    // undefined. It never showed because this line only runs when a
                    // section is EMPTY -- which is precisely the empty-blog case, so
                    // the one path this whole line exists to serve was the path that
                    // threw. Found by running the live site, not by reading the code.
                    parent.closest('.nm-col, .nm-band').addClass('nm-empty');
                  }
                  // BLG-C233 / B16: the same rule, for the one surface C229 could
                  // not reach. C229's test is gated on `inNewsModal`, so it only ever
                  // looked at the modal lists; the homepage breaking strip was never
                  // checked. With zero entries this renderer still writes a slider
                  // and its next/prev arrows, which leaves the band showing a heading
                  // over an empty carousel -- the same "this feed is broken" read the
                  // modal rule was added to prevent, one screen earlier.
                  //
                  // Tested on the markup rather than on a count, because the loop
                  // above appends one .post-panel per entry and emits nothing at all
                  // when there are none, so its absence is the signal.
                  if (!inNewsModal && htmlcode.indexOf('post-panel') < 0) {
                    // parent is a jQuery object, so this returns a jQuery object
                    // and .classList on it is undefined. addClass is the jQuery
                    // API; reaching for classList here threw on every page load.
                    parent.closest('.bk-news').addClass('bk-empty');
                  }

                  // BLG-C058: name every thumbnail link generated here. Measured on live,
                  // 20 of the 27 homepage thumbnails are BUILT HERE, not authored in the
                  // template, so the aria-label added in BLG-C045 only ever covered the 7
                  // static ones -- a screen reader announced nothing for most post cards.
                  // The title is read from the sibling .post-title rather than threaded
                  // through the 13 markup variants: one place to change, no quote-escaping
                  // hazard, and it covers any variant added later. The guard makes it
                  // idempotent, so it never overwrites the static ones.
                  parent.find('.post-thumb').each(function () {
                      var a = this;
                      if (a.getAttribute('aria-label')) { return; }
                      var item = a.closest ? a.closest('.post-item') : null;
                      var t = item ? item.querySelector('.post-title') : null;
                      a.setAttribute('aria-label', t ? (t.textContent || '').replace(/^\s+|\s+$/g, '') : 'View post');
                  });


            }, // Success Function Close

            error: function(){

              parent.html("<div class='uk-alert-danger' data-uk-alert=''><p>Error loading feeds! Check if your blog is public, contains at least a label in all articles and that you've allow your blog feed as full! if the problem still please do not hesitate to contact us.</p></div>");

            } // Error Function Close

          }); // Ajax Function Close

          return false;

        } // If URL Close

      } // BlockFeeds Function Close

      // Get Global Shortcode
      $('.widget-content').each(function() {

        var $this = $(this),
            sp = $this.text().split("/");

        if(!isNaN(sp[0])) {
          var count 	= sp[0],
              style 	= shortcodeStyle(sp[1]),
              label 	= sp[2];
          blockfeeds($this, count, label, style);
        }

      });

      // Get Related Posts Shortcode
      $('.related-main .related-posts').each(function() {

        var $this = $(this),
            count = 5,
            style = 'related-posts',
            label = $this.text(),
            // AUD-M03: the label feed includes the post being read, so a thin
            // label rendered this block as one card pointing at the article the
            // reader is already on. data:post.id reaches the page as the
            // itemprop='postId' meta the post template emits; the feed entry id
            // ends with that same post id, so blockfeeds drops the match and the
            // existing empty-section guard hides the block when nothing is left.
            excludeId = ($('meta[itemprop="postId"]').attr('content') || '');

        blockfeeds($this, count, label, style, excludeId);

      });

      // Summary Grid Posts 
      $('.post-summary').each(function() {
        var re = /<\S[^>]*>/g;
        var postcontent = $(this).find('.post-ct-summary').html().replace(re,"");
        if(postcontent.length > 220){
          postcontent = ''+postcontent.substring(0,220)+'...';
        }
        $(this).html(''+ postcontent +'');
      });      

