(function() {
  var postBody = document.querySelector('.post-body');
  if (!postBody) return;
  var heads = postBody.querySelectorAll('h2, h3');
  if (heads.length < 2) return;
  var tocHtml = '<div class="post-toc"><p class="post-toc-title" role="button" tabindex="0" aria-expanded="true"><span uk-icon="icon: list; ratio: 0.9"></span> Table of Contents<span class="post-toc-caret"></span></p><ol>';
  var idCount = 0;
  for (var i = 0; i < heads.length; i++) {
    var h = heads[i];
    if (!h.id) h.id = 'cp-toc-' + (++idCount);
    tocHtml += '<li><a href="#' + h.id + '">' + h.textContent + '</a></li>';
  }
  tocHtml += '</ol></div>';
  postBody.insertBefore(document.createRange().createContextualFragment(tocHtml), postBody.firstChild);
  var tocWrap = postBody.querySelector('.post-toc');
  var tocTitle = tocWrap.querySelector('.post-toc-title');
  var tocList = tocWrap.querySelector('ol');
  tocTitle.addEventListener('click', function() {
    var collapsed = tocWrap.classList.toggle('is-collapsed');
    tocList.hidden = collapsed;
    tocTitle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
  });
  tocTitle.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      tocTitle.click();
    }
  });
})();
