body.script:
      //
      // BLG-C108: give an image-less post a category placeholder.
      // NO CONFIGURATION FOR ANY OWNER. There is no list of categories to fill
      // in: the post's own Blogger label IS the name, and the accent is a hash
      // of that label, so each category keeps its colour between page loads.
      // A post with no label falls back to NEWS. A map was tried first and was
      // wrong twice: the rebrand guide tells an owner never to edit the
      // template file, and a hardcoded label is site data that the generator
      // refuses to put in the product copy, which made the product unwritable.
      // The script therefore holds no colour and no list, only the rule for
      // reading a label -- Blogger does not substitute its variable syntax
      // inside a script block, so every colour lives in the stylesheet (C101).
      // A MutationObserver does the work rather than one pass on load, because
      // the feed cards arrive as JSONP some seconds after load.
      (function () {
        var FALLBACK = 'NEWS';
        function accentFor(name) {
          var h = 0, i;
          for (i = 0; i < name.length; i++) { h = (h * 31 + name.charCodeAt(i)) >>> 0; }
          return (h % 2) ? 'b' : 'a';
        }
        // Read the category -> image list from the 'Default Images' control
        // gadget. Same origin, no request, and it is configured in Layout like
        // the other two control gadgets, so no template editing is needed.
        var LIBRARY = {};
        (function readLibrary() {
          var g = document.querySelector('.default-images-control .widget-content');
          if (!g) return;
          // BLG-C441: the includable never rendered the gadget content, so
          // there was no .widget-content and this returned on the line above
          // with LIBRARY empty; every imageless card fell through to the
          // panel. The content renders now, and the lines are read from
          // innerHTML rather than textContent: the shipped instructions keep
          // the example line inside an HTML comment, owners duplicate that
          // line where they see it, and textContent skips comments while
          // innerHTML keeps them.
