  }

  function cpSearchGo(i) {
    if (!items.length) { return; }
    cpSearchMark((i + items.length) % items.length);
  }

  function cpSearchRun(q) {
    if (q.length < MIN) {
      list.innerHTML = '';
      items = [];
      active = -1;
      cpSearchOpen(false);
      cpSearchSay('Type at least ' + MIN + ' characters.');
      return;
    }
    var mine = ++seq;
    cpSearchSay('Searching…');
    // C243: not `true` here. The list is still empty and CSS is already hiding
    // it, so claiming it is open described a box the reader cannot see.
    cpSearchOpen(false);
    // blogUrl, not a bare `base`: C101 requires every ajax feed URL to name the
    // blogUrl family, because a literal base is exactly how the mega menu
    // regressed once. It is seeded from data:blog.homepageUrl, so a blog on a
    // custom domain feeds from the right origin with nothing to edit.
    var blogUrl = opts.base;
    var url = blogUrl + 'feeds/posts/summary?q=' + encodeURIComponent(q) +
              '&alt=json-in-script&max-results=' + MAX;
    window.jQuery.ajax({
      url: url, type: 'GET', dataType: 'jsonp', cache: true
    }).done(function (json) {
      // A slower earlier request must not repaint over a newer one.
      if (mine !== seq) { return; }
      var raw = cpSearchEntries(json);
      var hits = [];
      for (var i = 0; i < raw.length; i++) {
        var e = raw[i];
        var tEl = e.title;
        var titleEl = (tEl && tEl['$t']) ? tEl['$t'] : cpSearchText(tEl);
        hits.push({ title: titleEl || 'Untitled', href: cpSearchLink(e), date: cpSearchDate(e),
                    thumb: cpSearchThumb(e), labels: cpSearchLabels(e) });
      }
      cpSearchPaint(hits, q);
    }).fail(function () {
      if (mine !== seq) { return; }
      list.innerHTML = '';
      items = [];
      var msg = 'Search is unavailable right now. Press Enter to use Blogger search.';
      // C243: same rule as the empty result -- the modal bar has no status
      // band to fall back on, so the list carries the message there.
      if (!status) {
        var bad = document.createElement('li');
        bad.className = 'cp-so-empty';
        bad.textContent = msg;
        list.appendChild(bad);
        cpSearchOpen(true);
      } else {
        cpSearchOpen(false);
      }
      cpSearchSay(msg);
    });
  }

  input.addEventListener('input', function () {
    var q = input.value.replace(/^\s+|\s+$/g, '');
    if (timer) { clearTimeout(timer); }
    timer = setTimeout(function () { cpSearchRun(q); }, DEBOUNCE);
  });

  input.addEventListener('keydown', function (ev) {
    var k = ev.key;
    if (k === 'ArrowDown') { ev.preventDefault(); cpSearchGo(active + 1); }
    else if (k === 'ArrowUp') { ev.preventDefault(); cpSearchGo(active - 1); }
    else if (k === 'Enter') {
      if (active >= 0 && items[active]) {
        ev.preventDefault();
        window.location.href = items[active].href;
      }
      // otherwise the form submits normally, which is the fallback
    }
    else if (k === 'Escape') {
      ev.preventDefault();
      onClose();
    }
  });

  return {
    open: function () { onOpen(); input.focus(); input.select(); },
    /* BLG-C243: closing has to take the answer with it. The panel is reused, so
       a query left standing greeted the next reader with the previous search's
       results and status line still on screen -- the content they had just
       dismissed, and a stale `aria-expanded` claiming a list that was meant to
       be gone. */
    close: function () {
      if (timer) { clearTimeout(timer); }
      input.value = '';
      list.innerHTML = '';
      items = [];
      active = -1;
      cpSearchOpen(false);
      cpSearchSay('');
      onClose();
    },
    focus: function () { input.focus(); },
    // BLG-C239: the public way to run a search NOW. The in-bar button needs
    // this and had no way to reach the closure, so it called a function that
    // did not exist and threw. Exposing the action is the fix; reaching into
    // a private one is not.
    search: function () {
      var q = String(input.value || '').replace(/^\s+|\s+$/g, '');
      if (timer) { clearTimeout(timer); }
      cpSearchRun(q);
    }
  };
}


/* BLG-C239: what the in-bar Search button and Enter do.
 *
 * Search immediately if there is a query, and otherwise leave the reader to
 * Blogger's own search page. The fallback is the reason the form was never
 * replaced: the feature can be entirely absent and the box still works.
 */
function cpSearchSubmit(engine, input) {
  var q = String(input.value || '').replace(/^\s+|\s+$/g, '');
  if (q && engine && engine.search) { engine.search(); return; }
  var form = input.form;
  if (form) { form.submit(); }
}
function cpInitAjaxSearch(imageFor, accentFor) {
  // BLG-C576: the placeholder sweep hands over its Default Images resolver and
  // its label-accent hash (see the call in the sweep's start()), so both search
  // surfaces resolve a row's picture the same way a card does. The parameters
  // are optional: a caller that passes nothing still gets a working search,
  // with the plain letter tile as the last resort.
  var $ = window.jQuery;
  if (!$) { return; }
  var homeMeta = document.querySelector("meta[name='cp-homepage']");
  var base = String((homeMeta && homeMeta.getAttribute('content')) || '/');
  if (base.charAt(base.length - 1) !== '/') { base += '/'; }

  // 1. the overlay the navigation search icon opens
  var overlay = document.getElementById('cp-search-overlay');
  if (overlay) {
    var oInput = document.getElementById('cp-so-input');
    var oEngine = cpAjaxSearch({
      input: oInput,
      list: document.getElementById('cp-so-list'),
      status: document.getElementById('cp-so-status'),
      base: base,
      defaultImage: imageFor,
      defaultAccent: accentFor,
      onOpen: function () { overlay.classList.add('is-open'); },
      onClose: function () { overlay.classList.remove('is-open'); }
    });
    // Click anywhere OUTSIDE the panel closes it. The operator asked for this
    // explicitly: a panel that only leaves by its close button feels stuck.
    // mousedown rather than click, so a drag that starts inside and ends
    // outside does not close it under the reader.
    var soPanel = overlay.querySelector('.cp-so-panel');
    overlay.addEventListener('mousedown', function (ev) {
      if (!soPanel || !soPanel.contains(ev.target)) { oEngine.close(); }
    });
    // the in-bar search button runs the query without waiting for the debounce
    var goBtn = overlay.querySelector('.cp-so-go');
    if (goBtn) {
      goBtn.addEventListener('click', function () {
        cpSearchSubmit(oEngine, oInput);
      });
    }
    // Enter in the field does the same thing
    oInput.addEventListener('keydown', function (ev) {
      if (ev.key === 'Enter' && ev.target === oInput) {
        ev.preventDefault();
        cpSearchSubmit(oEngine, oInput);
      }
    });
    var closer = overlay.querySelector('.cp-so-close');
    if (closer) { closer.addEventListener('click', function () { oEngine.close(); }); }

    // the existing navigation search cell: same icon, new behaviour
    var navBtn = document.querySelector('.cp-hd-search button');
    if (navBtn) {
      navBtn.removeAttribute('uk-toggle');
      navBtn.addEventListener('click', function (ev) {
        ev.preventDefault();
        oEngine.open();
      });
    }
    /* BLG-C245: this click handler is DELETED, not repaired, and nothing
       replaces it. It re-set `uk-toggle` on the HOT label -- an attribute the
       markup already carries at L3646 -- and then called
       `UIkit('[uk-toggle]').toggle()`, which is the bug: that selector matches
       FIVE elements on this page (the label, one anchor and three
       `.uk-button`s), so one click on HOT asked UIkit to toggle every toggle
       on the page, most of which point somewhere else entirely. Clicking HOT
       logged `Uncaught TypeError: Cannot read properties of undefined (reading
       'constructor')` from inside uikit.min.js, twice per click in some
       states. `UIkit(em)` on that same label throws `reading 'args'`, so the
       failure is in reaching the component through a selector collection, not
       in the label.

       The label never needed wiring. UIkit reads `uk-toggle` out of the markup
       and binds it during its own DOMContentLoaded pass, so the plain click
       already toggles the modal -- VERIFIED on the live blog by appending a
       bare <button uk-toggle='target: #news-modal'> with no script attached at
       all: it opened the modal and closed it again. Deleting the handler
       therefore removes an error and a double-toggle, and changes no
       behaviour. C237 added it; C245 takes it back out. */

    // shortcuts: "/" or Ctrl/Cmd+K from anywhere, Escape to leave
    document.addEventListener('keydown', function (ev) {
      var typing = /^(INPUT|TEXTAREA|SELECT)$/.test((ev.target.tagName || '').toUpperCase()) ||
                   (ev.target && ev.target.isContentEditable);
      if (ev.key === 'Escape' && overlay.classList.contains('is-open')) {
        oEngine.close();
        return;
      }
      if (typing || ev.metaKey || ev.altKey) { return; }
      if (ev.key === '/' || ((ev.ctrlKey || ev.metaKey) && (ev.key || '').toLowerCase() === 'k')) {
        ev.preventDefault();
        oEngine.open();
      }
    });
  }

  // 2. inline results under the modal's own search bar, same engine
  var form = document.getElementById('cp-search-form');
  if (form) {
    // BLG-C239: the wrapper div C237 added is gone. It reflowed the flex row,
    // and the operator asked for this bar to stay exactly as it ships.
    // BLG-C244: the results list is now a CHILD of the form rather than its
    // sibling. Sibling meant `left:0; right:0` resolved against .nm-sb-row,
    // which also holds the logo, and the dropdown came out 205px wider than the
    // search control. Parented inside the form it is out of flow, so it adds no
    // flex item and the bar is unchanged -- which is the thing C237's wrapper
    // broke and this does not.
    var mList = document.createElement('ul');
    mList.className = 'cp-so-results';
    mList.setAttribute('role', 'listbox');
    form.appendChild(mList);
    var mInput = document.getElementById('cp-search-input');
    mInput.setAttribute('role', 'combobox');
    mInput.setAttribute('aria-autocomplete', 'list');
    mInput.setAttribute('aria-controls', 'cp-modal-search-list');
    mInput.setAttribute('aria-expanded', 'false');
    mList.id = 'cp-modal-search-list';
    cpAjaxSearch({
      input: mInput, list: mList, status: null, base: base,
      defaultImage: imageFor, defaultAccent: accentFor
    });
    // Enter with nothing highlighted must still reach Blogger search.
    form.addEventListener('submit', function (ev) {
      if (!mInput.value.replace(/^\s+|\s+$/g, '')) { ev.preventDefault(); }
    });
  }
}

/* BLG-C247 / B18: a news template with no video schema.
 *
 * MEASURED, not assumed. The theme emits three JSON-LD blocks -- WebSite,
 * BlogPosting, BreadcrumbList -- and BlogPosting declares an image, an author,
 * a publisher and two sameAs links, but no `video`. Verified on the live blog:
 * `JSON.parse` of the BlogPosting block succeeds and `"video" in obj` is FALSE.
 * The same post page renders a real YouTube embed inside the post body
 * (`youtube.com/embed/afRRZF6fKI8`, wrapped in `.video-embed-wrapper`), so this
 * is not a template with nothing to declare -- it is a template sitting on a
 * video and saying nothing about it.
 *
 * WHY JAVASCRIPT, when the other three blocks are server-rendered: Blogger's
 * template language has no way to ask whether a post body CONTAINS something.
 * There is no `contains`, and `data:post.body` cannot be tested, so a
 * server-rendered VideoObject would have to be emitted UNCONDITIONALLY -- and an
 * empty VideoObject is worse than none, because it tells a crawler the post has
 * a video of unknown name, thumbnail and date. The brief says so directly:
 * "Conditional, because emitting an empty VideoObject is worse than emitting
 * none." Only the browser can look, so only the browser decides.
 *
 * WHY THIS DOES NOT TOUCH THE OTHER BLOCKS. The brief's OUT OF SCOPE holds: the
 * BlogPosting block at L4985 is byte-for-byte unchanged. This ADDS a fourth
 * block, and only when a video is really there.
 *
 * THE GUARD is the existence of the BlogPosting block itself, which Blogger
 * renders only under `data:view.isPost` -- so "this URL is a post" is answered
 * by the template rather than guessed from a DOM count. The single-`.post-body`
 * count is the second condition, and it was measured rather than assumed:
 * 1 on a post page, 0 on the homepage listing. Either alone would do; both
 * together cannot be wrong in the direction that emits a false claim.
 */
function cpVideoSchema() {
  var bodies = document.querySelectorAll('.post-body');
  if (bodies.length !== 1) { return; }
  var body = bodies[0];

  var ld = null;
  var blocks = document.querySelectorAll('script[type="application/ld+json"]');
  for (var i = 0; i < blocks.length; i++) {
    /* Never emit a second VideoObject. This checks EVERY block, and the first
     * draft checked only the BlogPosting one -- which can never contain the
     * string, because the VideoObject is emitted as its OWN block. So the guard
     * was dead code and a second call appended a duplicate. Caught by running the
     * function twice on a live post: blocks went 4 -> 5 -> 6. Duplicate JSON-LD
     * is a real defect, not a cosmetic one, so the check is over the whole set. */
    if (blocks[i].textContent.indexOf('"VideoObject"') >= 0) { return; }
    if (!ld && blocks[i].textContent.indexOf('"BlogPosting"') >= 0) { ld = blocks[i]; }
  }
  if (!ld) { return; }

  // --- find a video, and only inside the post body -------------------------
  // Scoped on purpose: the page carries other iframes (the comment editor, the
  // social drawer) and none of them are this post's video.
  var src = '', id = '';
  var frames = body.querySelectorAll('iframe');
  for (var f = 0; f < frames.length; f++) {
    var s = frames[f].getAttribute('src') || '';
    var yt = s.match(/(?:youtube(?:-nocookie)?\.com\/embed\/|youtu\.be\/)([A-Za-z0-9_-]{6,})/);
    if (yt) { src = s; id = yt[1]; break; }
    var vm = s.match(/player\.vimeo\.com\/video\/(\d+)/);
    if (vm) { src = s; id = vm[1]; break; }
  }
  if (!src) {
    var tag = body.querySelector('video[src], video source[src]');
    if (tag) { src = tag.getAttribute('src') || ''; }
  }
  if (!src) { return; }               // no video: gain nothing, which is the point

  // --- the values, from what the page already renders ----------------------
  var titleEl = document.querySelector('h1.post-title, .post-title, h1');
  var name = titleEl ? (titleEl.textContent || '').replace(/\s+/g, ' ').trim() : '';
  if (!name) { return; }              // a VideoObject with no name is invalid

  var timeEl = document.querySelector('.post-date abbr[title], abbr.published, time[datetime]');
  var when = timeEl ? (timeEl.getAttribute('title') || timeEl.getAttribute('datetime') || '') : '';
  var uploadDate = when ? when.replace(/\.\d+(?=[+\-Z]|$)/, '') : '';
  if (!uploadDate) { return; }        // uploadDate is REQUIRED by Google

  var posting = null;
  try { posting = JSON.parse(ld.textContent); } catch (e) { posting = null; }
  var fallbackThumb = (posting && posting.image) ? posting.image : '';

  // A YouTube thumbnail is derived from the video id and is the same URL the
  // player shows. Nothing is invented: `hqdefault.jpg` is a real, stable
  // YouTube asset for that id, and if the id is wrong there is no video here.
  var thumb = id && /^[A-Za-z0-9_-]{6,}$/.test(id)
    ? 'https://img.youtube.com/vi/' + id + '/hqdefault.jpg'
    : fallbackThumb;
  if (!thumb) { return; }             // thumbnailUrl is also REQUIRED

  var vo = {
    '@context': 'https://schema.org',
    '@type': 'VideoObject',
    name: name,
    description: name,
    thumbnailUrl: [thumb],
    uploadDate: uploadDate
  };
  if (id && /^[A-Za-z0-9_-]{6,}$/.test(id)) {
    vo.embedUrl = 'https://www.youtube.com/embed/' + id;
    vo.contentUrl = 'https://www.youtube.com/watch?v=' + id;
  } else if (!id && /\.mp4|\.webm|\.m3u8/i.test(src)) {
    vo.contentUrl = src;
  }

  var s = document.createElement('script');
  s.type = 'application/ld+json';
  s.textContent = JSON.stringify(vo);
  document.head.appendChild(s);
}


/* BLG-C233 / B16: the two surfaces that need a real empty state.
 *
 * The breaking strip is handled above instead, by the same rule C229 already
 * applies to the modal lists, because hiding a fixed band beats leaving a
 * heading over nothing.
 *
 * Both checks below are no-ops the moment their surface has content, so none
 * of this can ever appear on a blog that has posts.
 */
function cpEmpty(box, title, note) {
  if (!box || box.querySelector('.cp-empty')) { return; }
  var d = document.createElement('div');
  d.className = 'cp-empty';
  d.innerHTML = '<span class="cp-empty-title">' + title + '</span>' +
    (note ? '<span class="cp-empty-note">' + note + '</span>' : '');
  box.appendChild(d);
}

/* BLG-C235: a state must not outlive the emptiness that justified it.
   The live site showed a populated breaking strip carrying "No breaking news"
   underneath its real headlines, because these surfaces fill asynchronously:
   the state was written while the feed was still in flight and nothing took it
   away afterwards. Writing is only half the contract -- retracting is the other
   half, and it is the half a buyer sees. */
function cpRetract(box, hasContent) {
  var s = box && box.querySelector('.cp-empty');
  if (s && hasContent) { s.parentNode.removeChild(s); }
}

function cpShowEmptyStates() {
  // An empty blog still renders CONTAINERS: the Blog widget emits its section,
  // an empty `.post-entry` feed div, a status message and the pager -- just no
  // ENTRIES. Testing the container (as this did until BLG-C267) passes
  // vacuously on a fresh install, so the designed state never injected and a
  // new blog showed Blogger's bare "No posts." (proven live on a zero-post
  // install). Test for entries, not containers.
  var main = document.getElementById('main');
  if (main) {
    var mainFull = !!main.querySelector('.post-entry .post-item, .post-entry h3.post-title, .post-entry .post-thumb, .post-body, .hentry');
    if (mainFull) { cpRetract(main, true); }
    else {
      cpEmpty(main, 'Your posts will appear here',
        'Write your first post in Blogger, and this space becomes your homepage.');
    }
  }
  // The label chips. Counted rather than matched with `:empty`, because Blogger
  // emits newlines and indentation inside the widget even with zero labels, so
  // the container is never `:empty` and its whitespace is invisible on screen.
  var chips = document.querySelector('#news-modal .nm-chips');
  if (chips) {
    if (chips.querySelector('a')) { cpRetract(chips, true); }
    else {
      cpEmpty(chips, 'No labels yet',
        'Add a label to any post in Blogger, and it appears here as a chip.');
    }
  }
}

document.addEventListener('DOMContentLoaded', function () {
  cpShowEmptyStates();
  // These surfaces fill on their own schedule -- the modal lists are injected by
  // their own loader, and a feed resolves over the network -- so a single check
  // at DOMContentLoaded can be right when it runs and wrong a second later. Each
  // pass both writes a state for a surface that is still empty and retracts one
  // that has since filled, so the answer is correct whenever the eye arrives.
  [400, 1200, 3000, 8000].forEach(function (ms) { setTimeout(cpShowEmptyStates, ms); });
});





} else { start(); }
})();
