/* BLG-C184: the post tag strip keeps ONE-WORD labels only.

   The markup already dropped the comma between tags and already carries the
   single-line CSS; what cannot be done in Blogger's own language is the word
   test, because it has no substring or regex operator and no way to index or
   break a loop. So the two-word labels (a pair of words, as most of them are) are
   removed here, where the label text is already in the DOM.

   Read from the anchor's own text, not from a data attribute: Blogger prints
   the name as the anchor's text node, and the hashtag icon inside it is an SVG
   that contributes no text, so what is left is the label and nothing else.

   A post whose every label is two words is left with nothing, and then the
   whole strip goes -- a "Tags:" heading with no tags under it reads as a bug,
   whereas no strip at all reads as a post with no tags. */
(function () {
function tidy() {
var boxes = document.querySelectorAll('.post-tags-container .post-labels');
for (var b = 0; b < boxes.length; b++) {
var box = boxes[b];
var links = box.querySelectorAll('a[rel="tag"]');
var kept = 0;
for (var i = 0; i < links.length; i++) {
var name = (links[i].textContent || '').replace(/^\s+|\s+$/g, '');
if (/\s/.test(name)) {
if (links[i].parentNode) { links[i].parentNode.removeChild(links[i]); }
continue;
}
kept++;
}
var strip = box.closest ? box.closest('.post-tags-container') : null;
if (strip && !kept) { strip.style.display = 'none'; }
}
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', tidy);
} else { tidy(); }
})();
//

  //
  (function() {
    var root = document.documentElement;
    var btn = document.querySelector('.cp-dark-toggle');

  var key = 'cp-dark-mode';
  var gadget = document.getElementById('HTML13');
  if (!gadget) {
    if (btn) btn.style.display = 'none';
    return;
  }
    var stored = null;
    try { stored = localStorage.getItem(key); } catch (e) {}
    // BLG-C102: the identical decision the <head> script already made, so
    // this pass confirms the class rather than re-deciding it. Before C102
    // this was `apply(stored === '1')`, which meant a first-time visitor was
    // always light and -- because the head had no copy of this logic at all
    // -- every page painted light before reaching here. An explicit stored
    // '0' still wins over the OS preference; only "no choice yet" follows
    // prefers-color-scheme.
    var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    var wantDark = stored === '1' || (stored !== '0' && prefersDark);
    var apply = function(dark) {
      root.classList.toggle('dark', dark);
      root.style.colorScheme = dark ? 'dark' : 'light';
      if (btn) btn.setAttribute('aria-pressed', dark ? 'true' : 'false');
    };
    apply(wantDark);
    if (btn) btn.addEventListener('click', function() {
      apply(!root.classList.contains('dark'));
      try { localStorage.setItem(key, root.classList.contains('dark') ? '1' : '0'); } catch (e) {}
    });

})();
