//
// BLG-C138: the main post list fades in through UIkit scrollspy, which holds
// every card at opacity:0 until it intersects the viewport. The fade is the
// design, but it has one bad failure mode: when scrollspy never marks a card
// -- UIkit blocked, a script error before it initialises, a print or
// save-for-later pass -- the card stays transparent and the column reads as
// "this blog has no posts". This watchdog reveals any card that is on screen,
// or already scrolled past, while it is still transparent. Cards further down
// keep the fade and are left to scrollspy alone.
(function() {
  var items = document.querySelectorAll('.post-main-container > .post-item');
  if (!items.length) return;

  var sweep = function() {
    var vh = window.innerHeight || document.documentElement.clientHeight;
    for (var i = 0; i < items.length; i++) {
      var el = items[i];
      if (el.getBoundingClientRect().top > vh) continue;
      if (window.getComputedStyle(el).opacity !== '0') continue;
      el.style.opacity = '';
    }
  };
  var queued = false;
  var schedule = function() {
    if (queued) return;
    queued = true;
    window.requestAnimationFrame(function() { queued = false; sweep(); });
  };

  sweep();
  // UIkit sets that inline opacity from its own ready hook, which runs after
  // this script, so the first pass can still see every card as visible.
  window.setTimeout(sweep, 1200);
  window.addEventListener('load', sweep);
  window.addEventListener('resize', schedule);
  // BLG-C422: the only scroll listener in this file that did not declare itself
  // passive. Its handler is already rAF-coalesced behind a `queued` flag, so
  // the practical INP cost was near zero and passive:true buys little here --
  // but its SIBLING on the same target already declared it, so the file was
  // teaching two different habits two lines apart, and the declaration is what
  // the next listener copies from this one.
  window.addEventListener('scroll', schedule, {passive: true});
})();
// BLG-C139: the modal carries the site logo opposite its search bar. It is
// not a gadget -- the owner chose mirroring over a new section -- so it is
// copied from the header's own logo image, which means it always shows what
// the owner uploaded and can never drift from it. Copied rather than
// templated because Blogger keeps the header logo in the Header gadget's
// settings, which no other widget can read. No header logo means the slot
// simply stays empty rather than reserving a gap.
(function() {
  var slot = document.querySelector('#news-modal .nm-logo');
  if (!slot) return;
  var fill = function() {
    var src = document.querySelector('.logo-hd img');
    if (!src || !src.getAttribute('src')) { slot.innerHTML = ''; return; }
    if (slot.firstChild && slot.firstChild.getAttribute('src') === src.getAttribute('src')) return;
    var img = document.createElement('img');
    img.setAttribute('src', src.getAttribute('src'));
    img.setAttribute('alt', src.getAttribute('alt') || '');
    slot.innerHTML = '';
