    if (utterLang) u.lang = utterLang;
    u.rate = RATES[rateIdx];
    u.onstart = function () { if (my !== state.session) return; state.preparing = false; syncPlay(); };
    u.onboundary = function (e) {
      if (my !== state.session) return;
      if (typeof e.charIndex !== 'number') return;
      // Some engines report a sentence boundary; the say mark already carries
      // the sentence, so a sentence boundary must not become one giant word.
      if (e.name && e.name !== 'word') return;
      var run = ensureText();
      var w0 = s.start + Math.max(0, Math.min(e.charIndex, s.text.length - 1));
      // BLG-C561: skip a boundary that lands on whitespace instead of marking
      // that single space (the old code made the word mark invisible until the
      // next event), and honour charLength when the engine reports it.
      while (w0 < s.end && /\s/.test(run.text.charAt(w0))) w0++;
      if (w0 >= s.end) return;
      var w1;
      if (typeof e.charLength === 'number' && e.charLength > 0) w1 = Math.min(s.end, w0 + e.charLength);
      else { w1 = w0; while (w1 < s.end && !/\s/.test(run.text.charAt(w1))) w1++; }
      if (w1 <= w0) w1 = Math.min(s.end, w0 + 1);
      highlightRange(w0, w1, 'word', 'rm-word');
      followCurrent();
    };
    u.onend = function () {
      if (my !== state.session || !state.playing) return;
      state.spoken++;
      speakFrom(i + 1);
    };
    u.onerror = function (e) {
      if (my !== state.session || !state.playing) return;
      if (e.error === 'canceled' || e.error === 'interrupted') return;
      speakFrom(i + 1);
    };
    updatePos();
    followCurrent();
    tts.speak(u);
  }

  function togglePlay() {
    if (!tts) return;
    if (state.playing || state.preparing) { stopSpeech(false); return; }
    var sents = ensureSentences();
    if (!sents.length) return;
    speakFrom(Math.min(state.index, sents.length - 1));
  }

  function step(delta) {
    if (!tts) return;
    var sents = ensureSentences();
    if (!sents.length) return;
    var i = state.index + delta;
    if (i < 0) i = 0;
    if (i >= sents.length) { stopSpeech(true); return; }
    if (state.playing || state.preparing) { speakFrom(i); return; }
    state.index = i;
    highlightRange(sents[i].start, sents[i].end, 'say', 'rm-say');
    var stepVerdict = langVerdict(sents[i].text);
    syncLang(state.override !== 'auto' ? state.override : (stepVerdict.lang || detectLang(sents[i].text)), stepVerdict);
    updatePos();
    followCurrent();
  }

  /* ---------------- the reader's manual control wins ---------------- */
  function holdFollow() {
    if (!state.on || !state.follow || state.manualHold) return;
    state.manualHold = true;
    showChip();
  }
  window.addEventListener('wheel', holdFollow, { passive: true, capture: true });
  window.addEventListener('touchmove', holdFollow, { passive: true, capture: true });
  window.addEventListener('keydown', function (e) {
    var t = e.target;
    if (t && t.closest && t.closest('button,input,select,textarea,a')) return;
    var k = e.key;
    if (k === 'ArrowUp' || k === 'ArrowDown' || k === 'PageUp' || k === 'PageDown' || k === 'Home' || k === 'End' || k === ' ') holdFollow();
  });
  function resumeFollow() {
    state.manualHold = false;
    hideChip();
    followCurrent();
  }

  /* BLG-C559: slide between posts. A horizontal swipe on the reading
     sheet navigates -- left toward the NEWER post, right toward the OLDER
     one -- through the pager links the template already prints. First or
     last post has no target and the swipe does nothing; a
     vertical-dominant move is a scroll, not a swipe. */
  var SWIPE_MIN = 60;
  var swipeX = null, swipeY = null;
  document.addEventListener('touchstart', function (e) {
    if (!state.on || !e.touches || e.touches.length !== 1) { swipeX = null; return; }
    swipeX = e.touches[0].clientX;
    swipeY = e.touches[0].clientY;
  }, { passive: true });
  document.addEventListener('touchend', function (e) {
    if (!state.on || swipeX === null || !e.changedTouches || e.changedTouches.length !== 1) { swipeX = null; return; }
    var dx = e.changedTouches[0].clientX - swipeX;
    var dy = e.changedTouches[0].clientY - swipeY;
    swipeX = null;
    if (Math.abs(dx) < SWIPE_MIN || Math.abs(dx) <= Math.abs(dy) * 1.5) return;
    var link = document.querySelector(dx < 0
      ? 'a.blog-pager-newer-link, #blog-pager-newer-link a, .blog-pager .newer-link a'
      : 'a.blog-pager-older-link, #blog-pager-older-link a, .blog-pager .older-link a');
    if (link && link.href) window.location.href = link.href;
  }, { passive: true });

  /* ---------------- wiring ---------------- */
  playBtn.addEventListener('click', togglePlay);
  prevBtn.addEventListener('click', function () { step(-1); });
  nextBtn.addEventListener('click', function () { step(1); });
  rateBtn.addEventListener('click', function () {
    rateIdx = (rateIdx + 1) % RATES.length;
    rateBtn.textContent = RATES[rateIdx] + 'x';
    rateBtn.setAttribute('aria-label', 'Reading speed: ' + RATES[rateIdx] + 'x');
    /* BLG-C558: one Reading speed button drives both the narration rate and
       the follow-scroll pace, so the two cannot disagree, and it persists. */
    state.speed = RATES[rateIdx] <= 0.75 ? 'slow' : (RATES[rateIdx] >= 1.25 ? 'fast' : 'normal');
    persistFollow();
  });
  fsBtn.addEventListener('click', function () { setFs((state.fs + 1) % 3, true); });
  langBtn.addEventListener('click', cycleLang);
  darkBtn.addEventListener('click', function () {
    var dark = document.documentElement.classList.toggle('dark');
    document.documentElement.style.colorScheme = dark ? 'dark' : 'light';
    store('cp-dark-mode', dark ? '1' : '0');
    syncDark();
  });
  closeBtn.addEventListener('click', function () { setMode(false, true); });
  exitBtn.addEventListener('click', function () { setMode(false, true); });
  chipBtn.addEventListener('click', resumeFollow);
  window.addEventListener('pagehide', function () { if (tts) tts.cancel(); });

  function setMode(on, persist) {
    state.on = on;
    document.body.classList.toggle('rm-on', on);
    for (var i = 0; i < entries.length; i++) entries[i].setAttribute('aria-pressed', on ? 'true' : 'false');
    if (persist) store(KEY_ON, on ? '1' : '0');
    if (on) {
      ensureSentences();
      updateNav();
      var box = sheetBox();
      if (box) box.scrollTop = 0;
    } else {
      stopSpeech(true);
      hideChip();
      state.manualHold = false;
    }
  }

  for (var eb = 0; eb < entries.length; eb++) {
    entries[eb].addEventListener('click', function () { setMode(!state.on, true); });
  }

  /* ---------------- init ----------------
     A stored ON restores the surface only; speech never starts without a
     gesture. The reader's other choices restore wholesale. */
  var fsSaved = recall(KEY_FS);
  if (fsSaved === '1' || fsSaved === '2') setFs(parseInt(fsSaved, 10), false);
  var folSaved = recall(KEY_FOLLOW);
  if (folSaved) {
    try {
      // BLG-C558: follow is no longer a stored on/off -- it is on by
      // default and the chip is the only pause. Only the speed recalls,
      // and the toolbar's Reading speed button is what writes it: one
      // control drives both the narration rate and the follow-scroll.
      var f = JSON.parse(folSaved);
      if (f && (f.speed === 'slow' || f.speed === 'normal' || f.speed === 'fast')) state.speed = f.speed;
      rateIdx = state.speed === 'slow' ? 0 : (state.speed === 'fast' ? 3 : 1);
      rateBtn.textContent = RATES[rateIdx] + 'x';
      rateBtn.setAttribute('aria-label', 'Reading speed: ' + RATES[rateIdx] + 'x');
    } catch (e) {}
  }
  var langSaved = recall(KEY_LANG);
  if (langSaved === 'en' || langSaved === 'hi' || langSaved === 'mr') state.override = langSaved;
  updateNav();
  syncDark();
  var langSavedInit = state.override !== 'auto' ? state.override : 'en';
  langBtn.textContent = state.override !== 'auto' ? langName(state.override) : 'Auto';
  langBtn.setAttribute('aria-label', 'Reading language: ' + (state.override !== 'auto' ? langName(state.override) : 'automatic'));
  syncLang(langSavedInit, langVerdict(langSavedInit === 'en' ? 'The' : (langSavedInit === 'hi' ? '\u0939\u093F\u0902\u0926\u0940 \u092D\u093E\u0937\u093E \u0939\u0948' : '\u092E\u0930\u093E\u0920\u0940 \u092D\u093E\u0937\u093E \u0906\u0939\u0947')));
  if (recall(KEY_ON) === '1') setMode(true, false);
})();
//
